      /* CSS cho chat widget */
      .chat-widget {
      position: fixed;
      bottom: 90px;
      right: 20px;
      width: 320px;
      height: 400px;
      background: white;
      border-radius: 12px;
      box-shadow: 0 5px 25px rgba(0, 0, 0, 0.2);
      display: flex;
      flex-direction: column;
      z-index: 1001;
      display: none;
      }

      .chat-header {
      background: linear-gradient(135deg, #2c7873 0%, #1e5f74 100%);
      color: white;
      padding: 15px;
      border-radius: 12px 12px 0 0;
      display: flex;
      justify-content: space-between;
      align-items: center;
      }

      .chat-header h3 {
      margin: 0;
      font-size: 1.1rem;
      }

      .close-chat {
      cursor: pointer;
      font-size: 1.5rem;
      }

      .chat-messages {
      flex: 1;
      padding: 15px;
      overflow-y: auto;
      background: #f9f9f9;
      }

      .message {
      margin-bottom: 15px;
      display: flex;
      flex-direction: column;
      }

      .message.admin {
      align-items: flex-start;
      }

      .message.user {
      align-items: flex-end;
      }

      .message-content {
      padding: 10px 15px;
      border-radius: 18px;
      max-width: 80%;
      }

      .message.admin .message-content {
      background: #e3f2fd;
      border-bottom-left-radius: 4px;
      }

      .message.user .message-content {
      background: #2c7873;
      color: white;
      border-bottom-right-radius: 4px;
      }

      .message-time {
      font-size: 0.7rem;
      color: #888;
      margin-top: 5px;
      }

      .system-message {
      text-align: center;
      margin: 10px 0;
      }

      .system-message p {
      font-size: 0.9rem;
      color: #666;
      background: #fff3cd;
      padding: 8px;
      border-radius: 8px;
      }

      .chat-input {
      display: flex;
      padding: 10px;
      border-top: 1px solid #eee;
      }

      .chat-input input {
      flex: 1;
      padding: 10px;
      border: 1px solid #ddd;
      border-radius: 20px;
      outline: none;
      }

      .chat-input button {
      background: #2c7873;
      color: white;
      border: none;
      border-radius: 50%;
      width: 40px;
      height: 40px;
      margin-left: 10px;
      cursor: pointer;
      }

      /* ĐIỀU CHỈNH VỊ TRÍ NÚT HỖ TRỢ */
      .open-chat-btn {
      position: fixed;
      bottom: 150px; /* Nằm trên nút Zalo (90px) và Messenger (20px) */
      right: 20px;
      background: linear-gradient(135deg, #2c7873 0%, #1e5f74 100%);
      color: white;
      border: none;
      border-radius: 50%;
      width: 60px;
      height: 60px;
      font-size: 1.5rem;
      cursor: pointer;
      box-shadow: 0 4px 15px rgba(44, 120, 115, 0.3);
      z-index: 1000;
      display: flex;
      align-items: center;
      justify-content: center;
      }

      /* Đảm bảo các nút khác không bị che khuất */
      .fixed-contact {
      bottom: 20px;
      right: 20px;
      display: flex;
      flex-direction: column;
      gap: 10px;
      z-index: 1000;
      position: fixed;
      }

      .fixed-contact a {
      display: block;
      width: 50px;
      height: 50px;
      border-radius: 50%;
      box-shadow: 0 0 10px rgba(0,0,0,0.2);
      transition: transform 0.3s;
      }

      /* Điều chỉnh thứ tự z-index để không bị che khuất */
      .fixed-contact a.zalo-contact {
      z-index: 999;
      }

      .fixed-contact a.messenger-contact {
      z-index: 998;
      }

      /* Hiệu ứng khi di chuột */
      .open-chat-btn:hover {
      transform: scale(1.1);
      box-shadow: 0 6px 20px rgba(44, 120, 115, 0.4);
      }

