      @keyframes pulse {
      0% { opacity: 1; }
      50% { opacity: 0.5; }
      100% { opacity: 1; }
      }

      .online-user-item.recent {
      opacity: 0.7;
      }

      .recent-users-section {
      margin-top: 15px;
      padding-top: 15px;
      border-top: 1px solid rgba(255, 255, 255, 0.1);
      }

      .recent-users-section h4 {
      font-size: 0.9rem;
      margin-bottom: 10px;
      color: #aaa;
      }
      /* ========================================================================= */
      /* NEWS SECTION STYLES */
      /* ========================================================================= */
      .news-section {
      background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
      padding: 60px 0;
      margin: 40px 0;
      position: relative;
      overflow: hidden;
      }

      .news-section::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 4px;
      background: linear-gradient(90deg, #2c7873, #1e5f74, #ffd700);
      background-size: 200% 100%;
      animation: gradientShift 3s ease infinite;
      }

      @keyframes gradientShift {
      0% { background-position: 0% 50%; }
      50% { background-position: 100% 50%; }
      100% { background-position: 0% 50%; }
      }

      .news-section .section-header {
      text-align: center;
      margin-bottom: 50px;
      }

      .news-section .section-title {
      font-size: 2.5rem;
      font-weight: 700;
      background: linear-gradient(135deg, #2c7873 0%, #1e5f74 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      margin-bottom: 15px;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 15px;
      }

      .news-section .section-title i {
      font-size: 2.2rem;
      background: linear-gradient(135deg, #2c7873 0%, #1e5f74 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      }

      .news-section .section-subtitle {
      font-size: 1.1rem;
      color: #555;
      max-width: 600px;
      margin: 0 auto;
      line-height: 1.6;
      }

      .news-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
      gap: 30px;
      margin-bottom: 40px;
      }

      .news-card {
      background: white;
      border-radius: 16px;
      overflow: hidden;
      box-shadow: 0 5px 20px rgba(0, 0, 0, 0.08);
      transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      position: relative;
      height: 100%;
      display: flex;
      flex-direction: column;
      }

      .news-card:hover {
      transform: translateY(-8px);
      box-shadow: 0 15px 35px rgba(0, 0, 0, 0.15);
      }

      .news-card::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 4px;
      background: linear-gradient(90deg, #2c7873, #1e5f74);
      transform: scaleX(0);
      transform-origin: left;
      transition: transform 0.4s ease;
      z-index: 2;
      }

      .news-card:hover::before {
      transform: scaleX(1);
      }

      .news-image {
      position: relative;
      height: 200px;
      overflow: hidden;
      background: linear-gradient(135deg, #2c7873 0%, #1e5f74 100%);
      }

      .news-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 0.5s ease;
      }

      .news-card:hover .news-image img {
      transform: scale(1.05);
      }

      .news-badge {
      position: absolute;
      top: 15px;
      left: 15px;
      background: linear-gradient(135deg, #2c7873, #1e5f74);
      color: white;
      padding: 6px 12px;
      border-radius: 20px;
      font-size: 0.8rem;
      font-weight: 600;
      z-index: 2;
      }

      .news-content {
      padding: 25px;
      flex-grow: 1;
      display: flex;
      flex-direction: column;
      }

      .news-date {
      display: flex;
      align-items: center;
      gap: 8px;
      color: #666;
      font-size: 0.9rem;
      margin-bottom: 12px;
      }

      .news-date i {
      color: #2c7873;
      }

      .news-title {
      font-size: 1.3rem;
      font-weight: 700;
      line-height: 1.4;
      margin-bottom: 15px;
      color: #333;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
      }

      .news-title a {
      color: inherit;
      text-decoration: none;
      transition: color 0.3s;
      }

      .news-title a:hover {
      color: #2c7873;
      }

      .news-excerpt {
      color: #666;
      line-height: 1.6;
      margin-bottom: 20px;
      flex-grow: 1;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
      }

      .news-meta {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-top: auto;
      padding-top: 15px;
      border-top: 1px solid #f0f0f0;
      }

      .news-author {
      display: flex;
      align-items: center;
      gap: 8px;
      color: #666;
      font-size: 0.9rem;
      }

      .news-author img {
      width: 24px;
      height: 24px;
      border-radius: 50%;
      object-fit: cover;
      }

      .read-more {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      color: #2c7873;
      font-weight: 600;
      text-decoration: none;
      font-size: 0.9rem;
      transition: all 0.3s;
      }

      .read-more:hover {
      color: #1e5f74;
      gap: 12px;
      }

      /* News Share Styles */
      .news-share {
      display: flex;
      gap: 12px;
      margin-top: 20px;
      padding-top: 20px;
      border-top: 1px solid #f0f0f0;
      justify-content: flex-end;
      }

      .news-share a {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.15);
      color: #2c7873;
      text-decoration: none;
      font-size: 16px;
      transition: all 0.3s ease;
      border: 1px solid #e0e0e0;
      }

      .news-share a:hover {
      background: rgba(44, 120, 115, 0.1);
      transform: translateY(-2px);
      color: #1e5f74;
      border-color: #2c7873;
      }

      .news-footer {
      text-align: center;
      margin-top: 30px;
      }

      .load-more-btn {
      background: linear-gradient(135deg, #2c7873 0%, #1e5f74 100%);
      color: white;
      border: none;
      padding: 15px 35px;
      border-radius: 50px;
      font-weight: 600;
      font-size: 1rem;
      cursor: pointer;
      transition: all 0.3s ease;
      display: inline-flex;
      align-items: center;
      gap: 12px;
      box-shadow: 0 4px 15px rgba(44, 120, 115, 0.3);
      }

      .load-more-btn:hover {
      transform: translateY(-3px);
      box-shadow: 0 8px 25px rgba(44, 120, 115, 0.4);
      gap: 15px;
      }

      .load-more-btn:active {
      transform: translateY(-1px);
      }

      .loading-news {
      text-align: center;
      padding: 40px;
      grid-column: 1 / -1;
      }

      .loading-news .spinner {
      width: 40px;
      height: 40px;
      border: 4px solid #f3f3f3;
      border-top: 4px solid #2c7873;
      border-radius: 50%;
      animation: spin 1s linear infinite;
      margin: 0 auto 15px;
      }

      @keyframes spin {
      0% { transform: rotate(0deg); }
      100% { transform: rotate(360deg); }
      }

      /* Responsive Design */
      @media (max-width: 768px) {
      .news-section {
      padding: 40px 0;
      }

      .news-section .section-title {
      font-size: 2rem;
      }

      .news-grid {
      grid-template-columns: 1fr;
      gap: 20px;
      }

      .news-content {
      padding: 20px;
      }

      .news-share {
      justify-content: center;
      }

      .load-more-btn {
      padding: 12px 25px;
      font-size: 0.9rem;
      }
      }

      @media (max-width: 480px) {
      .news-section .section-title {
      font-size: 1.7rem;
      }

      .news-title {
      font-size: 1.2rem;
      }

      .news-share {
      gap: 8px;
      }

      .news-share a {
      width: 32px;
      height: 32px;
      font-size: 14px;
      }
      }




/* ========================================================================= */
/* MOBILE MENU FIX - Menu trượt (off-canvas) + submenu kiểu accordion */
/* ========================================================================= */

/* Nút hamburger - ẩn trên desktop */
#mobile-menu-toggle {
  display: none;
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 1200;
  width: 44px;
  height: 44px;
  background: rgba(255, 255, 255, 0.15);
  border: none;
  border-radius: 8px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  cursor: pointer;
}
#mobile-menu-toggle span {
  display: block;
  width: 24px;
  height: 3px;
  background: #fff;
  border-radius: 2px;
  transition: transform 0.25s ease, opacity 0.25s ease;
}
#mobile-menu-toggle.active span:nth-child(1) { transform: translateY(8px) rotate(45deg); }
#mobile-menu-toggle.active span:nth-child(2) { opacity: 0; }
#mobile-menu-toggle.active span:nth-child(3) { transform: translateY(-8px) rotate(-45deg); }

#mobile-menu-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 1000;
}
#mobile-menu-overlay.active { display: block; }

/* Nút mũi tên mở submenu (chỉ dùng trên mobile) - ẩn hẳn trên desktop */
.submenu-toggle {
  display: none;
}

@media (max-width: 768px) {
  header { position: relative; padding-left: 60px; }

  #mobile-menu-toggle { display: flex; }

  /* Nav biến thành ngăn kéo trượt từ trái vào, cuộn dọc riêng */
  #main-nav {
    position: fixed;
    top: 0;
    left: 0;
    width: 82%;
    max-width: 320px;
    height: 100vh;
    overflow-y: auto;
    background: var(--secondary-color);
    box-shadow: 4px 0 20px rgba(0, 0, 0, 0.3);
    z-index: 1100;
    padding-top: 60px;
    transform: translateX(-100%);
    transition: transform 0.3s ease;
    -webkit-overflow-scrolling: touch;
  }
  #main-nav.active { transform: translateX(0); }

  #main-nav .menu {
    display: block;
    width: 100%;
  }
  #main-nav .menu > li { width: 100%; }
  #main-nav .menu a {
    display: block;
    width: 100%;
    white-space: normal;
    border-radius: 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  }

  /* Submenu: bỏ định vị tuyệt đối, xổ xuống dạng accordion, không tràn màn hình */
  #main-nav .submenu,
  #main-nav .submenu .submenu {
    display: none;
    position: static;
    left: auto;
    top: auto;
    width: 100%;
    min-width: 0;
    max-width: 100%;
    box-shadow: none;
    border-radius: 0;
    background: rgba(0, 0, 0, 0.15);
  }
  #main-nav .submenu.open { display: block; }
  /* Thụt lề theo từng cấp để dễ phân biệt */
  #main-nav .submenu .submenu a { padding-left: 35px; }
  #main-nav .submenu .submenu .submenu a { padding-left: 50px; }
  #main-nav .submenu .submenu .submenu .submenu a { padding-left: 65px; }

  /* Bỏ hover cũ trên mobile để tránh xung đột với JS click */
  #main-nav .menu li:hover > .submenu,
  #main-nav .submenu li:hover > .submenu { display: none; }
  #main-nav .submenu.open { display: block !important; }

  /* Nút mũi tên mở/đóng submenu, thêm bằng JS */
  .submenu-toggle {
    position: absolute;
    right: 0;
    top: 0;
    width: 44px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: none;
    border: none;
    color: #fff;
    font-size: 14px;
    cursor: pointer;
  }
  .submenu-toggle.open { transform: rotate(180deg); }
  #main-nav .menu li { position: relative; }

  body.mobile-nav-open { overflow: hidden; }
}

/* ========================================================================= */
/* DESKTOP MENU - thu gọn, luôn 1 hàng, chừa chỗ cho các nút nổi bên phải */
/* ========================================================================= */
@media (min-width: 769px) {
  nav {
    display: flex;
    justify-content: flex-start;
    padding: 8px 100px 8px 20px;
    overflow-x: auto;
    scrollbar-width: none;
  }
  nav::-webkit-scrollbar { display: none; }
  .menu {
    flex-wrap: nowrap;
    justify-content: flex-start;
    gap: 6px;
    margin: 0;
    max-width: 100%;
  }
  .menu a {
    padding: 7px 12px;
    font-size: 0.8rem;
    box-shadow: none;
    white-space: nowrap;
  }
  .menu a:hover {
    box-shadow: 0 4px 12px rgba(44, 120, 115, 0.4);
  }

  /* Menu con định vị theo tọa độ màn hình thực (JS tính), để không bị vùng cuộn ngang của nav cắt mất */
  .submenu {
    position: fixed;
  }
}

