div.script:
//
(function(){
  var BASE = 'https://script.google.com/macros/s/AKfycbyneetf4rDS23h9svUHXqGdyrsbSzXqV_zgdlGoxuA7fni20qvGiZgh84VKNiOIPFxsdQ/exec';
  var REFRESH_MS = 5 * 60 * 1000;
  var DEFAULT_FIRST_MONDAY = { '2023-2024': '2023-09-04', '2024-2025': '2024-09-02', '2025-2026': '2025-09-08', '2026-2027': '2026-09-07' };
  var DAYKEYS = [
    ['monday', 'mon', 'Thứ 2', 'thứ 2', 't2'],
    ['tuesday', 'tue', 'Thứ 3', 'thứ 3', 't3'],
    ['wednesday', 'wed', 'Thứ 4', 'thứ 4', 't4'],
    ['thursday', 'thu', 'Thứ 5', 'thứ 5', 't5'],
    ['friday', 'fri', 'Thứ 6', 'thứ 6', 't6'],
    ['saturday', 'sat', 'Thứ 7', 'thứ 7', 't7']
  ];
  var root = document.getElementById('lbgc'); if (!root) return;
  var btn = document.getElementById('toggleCalendarBtn');
  var box = document.getElementById('calendarContainer');
  function $(i){ return document.getElementById(i); }
  function esc(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
  function pad(n){ return (n < 10 ? '0' : '') + n; }
  function key(d){ return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }

  var now0 = new Date();
  var st = { saved: [], tkb: [], plan: [], classes: {}, dayCache: {}, grpCache: {}, cur: new Date(now0.getFullYear(), now0.getMonth(), 1), sel: null, cls: '', loading: false, loadedAt: 0, err: false, warn: '' };

  // ---------- ngày tháng ----------
  function pDate(v){
    if (v === null || v === undefined || v === '') return null;
    if (v instanceof Date) return isNaN(v) ? null : new Date(v.getFullYear(), v.getMonth(), v.getDate());
    if (typeof v === 'number') {
      var dn = v > 1e11 ? new Date(v) : new Date(1899, 11, 30 + Math.floor(v));
      return isNaN(dn) ? null : new Date(dn.getFullYear(), dn.getMonth(), dn.getDate());
    }
    var s = String(v).trim(), m;
    if ((m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/))) return new Date(+m[1], +m[2] - 1, +m[3]);
    if ((m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) return new Date(+m[3], +m[2] - 1, +m[1]);
    var d = new Date(s);
    return isNaN(d) ? null : new Date(d.getFullYear(), d.getMonth(), d.getDate());
  }
  function mondayOf(d){ var x = new Date(d.getFullYear(), d.getMonth(), d.getDate()); x.setDate(x.getDate() - ((x.getDay() + 6) % 7)); return x; }
  function schoolYearOf(d){ var y = d.getFullYear(); return d.getMonth() >= 7 ? y + '-' + (y + 1) : (y - 1) + '-' + y; }
  function firstMonday(sy){
    var s = null;
    try { var c = JSON.parse(localStorage.getItem('lbg_week_config') || '{}'); s = c[sy]; } catch (e) {}
    s = s || DEFAULT_FIRST_MONDAY[sy];
    var d = s ? pDate(s) : null;
    if (!d) { var sep = new Date(parseInt(sy, 10), 8, 1), w = sep.getDay(); if (w === 0) sep.setDate(2); else if (w > 1) sep.setDate(1 + (8 - w)); d = sep; }
    return d;
  }
  function weekNumber(d){
    var fm = firstMonday(schoolYearOf(d));
    var n = Math.round((mondayOf(d) - fm) / (7 * 86400000)) + 1;
    return (n >= 1 && n <= 35) ? n : null;
  }

  // ---------- tên lớp / môn ----------
  function classCodeOf(cn){
    if (!cn) return '';
    if (cn.indexOf('_') > -1) { var p = cn.split('_'); return p.length > 1 ? p[1] : cn; }
    var m = cn.match(/(10|11|12)[A-Z]\d+/); return m ? m[0] : cn;
  }
  function gradeOf(cn){
    if (!cn) return '10';
    var part = cn.indexOf('_') > -1 ? (cn.split('_')[1] || '') : cn;
    var m = part.match(/(10|11|12)/) || cn.match(/(10|11|12)/);
    return m ? m[0] : '10';
  }
  function subjectOf(cn){
    if (!cn) return '';
    if (cn.indexOf('_') > -1) return cn.split('_')[0].trim();
    var pats = [[/^(Lý|ly|VL|vl)/i, 'Lý'], [/^(CĐ|cd|Chuyên\s*đề)/i, 'CĐ'], [/^(Toán|toan)/i, 'Toán'], [/^(Văn|van)/i, 'Văn'], [/^(Anh|anh)/i, 'Anh'], [/^(Hóa|hoa)/i, 'Hóa'], [/^(Sinh|sinh)/i, 'Sinh']];
    for (var i = 0; i < pats.length; i++) if (pats[i][0].test(cn)) return pats[i][1];
    return cn.substring(0, 2);
  }
  var SUBJ_FULL = { 'Lý': 'Vật lý', 'CĐ': 'Chuyên đề', 'CD': 'Chuyên đề', 'Văn': 'Ngữ văn', 'Anh': 'Tiếng Anh', 'Hóa': 'Hóa học', 'Sinh': 'Sinh học' };
  function strip(s){ return String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/gi, 'd').toLowerCase().replace(/\s+/g, ' ').trim(); }
  function subjKey(s){
    var t = strip(s);
    if (['ly', 'li', 'vl', 'vat ly', 'vat li'].indexOf(t) > -1) return 'ly';
    if (['cd', 'chuyen de'].indexOf(t) > -1) return 'cd';
    if (t === 'gd' || t.indexOf('giao duc') === 0) return 'gd';
    return t;
  }
  function sessOrd(s){ s = String(s || '').toLowerCase(); return s.indexOf('sáng') > -1 ? 0 : (s.indexOf('chiều') > -1 ? 1 : 2); }
  function cmp(a, b){ return (sessOrd(a.session) - sessOrd(b.session)) || ((+a.period || 0) - (+b.period || 0)) || String(a.classCode).localeCompare(String(b.classCode)); }

  // ---------- chọn TKB (Lần) theo tuần ----------
  function pick(it, names){ for (var i = 0; i < names.length; i++) { var v = it[names[i]]; if (v !== undefined && v !== null && String(v).trim() !== '') return v; } return ''; }
  function selectTKB(monday){
    var ck = key(monday); if (st.grpCache[ck]) return st.grpCache[ck];
    var groups = {}, noDate = [];
    st.tkb.forEach(function(it){
      var s = pDate(pick(it, ['startDate', 'Ngày bắt đầu'])), e = pDate(pick(it, ['endDate', 'Ngày kết thúc']));
      if (!s || !e) { noDate.push(it); return; }
      var k = key(s) + '|' + key(e);
      (groups[k] = groups[k] || { s: s, e: e, items: [] }).items.push(it);
    });
    var arr = Object.keys(groups).map(function(k){ return groups[k]; }), res;
    if (!arr.length) res = noDate;
    else {
      var inside = arr.filter(function(g){ return monday >= g.s && monday <= g.e; }).sort(function(a, b){ return b.s - a.s; })[0];
      if (!inside) {
        var valid = arr.filter(function(g){ return g.s <= monday; }).sort(function(a, b){ return b.s - a.s; });
        inside = valid.length ? valid[0] : arr.sort(function(a, b){ return a.s - b.s; })[0];
      }
      res = inside.items;
    }
    st.grpCache[ck] = res; return res;
  }

  // ---------- tìm tên bài từ kế hoạch ----------
  function planFor(d, grade, subject, classCode){
    var wk = weekNumber(d); if (wk === null || !st.plan.length) return null;
    var sk = subjKey(subject);
    var cand = st.plan.filter(function(p){
      var pg = String(p.grade || p['Khối'] || '').trim(), ps = subjKey(p.subject || p['Môn'] || '');
      if (!((!grade || !pg || pg === String(grade)) && (!sk || !ps || ps === sk))) return false;
      if (parseInt(p.week || p['Tuần'], 10) !== wk) return false;
      var pc = p.className || p['Lớp'] || '';
      return !pc || classCode.indexOf(pc) > -1;
    });
    return cand.length ? cand[0] : null;
  }

  // ---------- tạo tiết dạy cho một ngày ----------
  function fromTKB(d){
    var dow = (d.getDay() + 6) % 7; if (dow > 5) return [];
    var out = [], used = {}, dstr = key(d);
    selectTKB(mondayOf(d)).forEach(function(it){
      var cn = String(pick(it, DAYKEYS[dow])).trim(); if (!cn) return;
      var period = parseInt(pick(it, ['period', 'Tiết']), 10); if (isNaN(period)) return;
      var grade = gradeOf(cn), session = pick(it, ['session', 'Buổi']) || 'Sáng';
      if (grade === '11' || grade === '12') session = 'Chiều'; else if (grade === '10') session = 'Sáng';
      var uk = session + '|' + period + '|' + cn; if (used[uk]) return; used[uk] = 1;
      var code = classCodeOf(cn), subj = subjectOf(cn), p = planFor(d, grade, subj, code), name = '', desc = String(pick(it, ['description', 'Mô tả']) || '');
      if (p) name = p.name || p['Tên bài'] || '';
      if (!name) name = (desc && desc.indexOf('Lần') < 0) ? desc : ((SUBJ_FULL[subj] || subj) + ' - ' + code);
      out.push({
        name: name, grade: grade, className: cn, classCode: code, subject: subj, date: dstr, period: period, session: session,
        requirement: p ? (p.requirement || p['Yêu cầu cần đạt'] || '') : '', competence: p ? (p.competence || '') : '',
        format: 'Dạy học trên lớp', integration: p ? (p.integration || p['Địa chỉ tích hợp'] || p['Tích hợp'] || '') : '', src: 'TKB'
      });
    });
    return out;
  }
  function lessonsOn(k){
    if (st.dayCache[k]) return st.dayCache[k];
    var d = pDate(k), list = [], seen = {};
    st.saved.forEach(function(l){
      if (l._d !== k) return;
      var s = sessOrd(l.session) === 1 ? 'Chiều' : 'Sáng';
      seen[s + '|' + l.period + '|' + l.classCode] = 1; list.push(l);
    });
    if (d) fromTKB(d).forEach(function(l){ if (!seen[l.session + '|' + l.period + '|' + l.classCode]) list.push(l); });
    list.sort(cmp); st.dayCache[k] = list; return list;
  }
  function dayList(k){ var a = lessonsOn(k); return st.cls ? a.filter(function(l){ return l.classCode === st.cls; }) : a; }

  // ---------- nạp dữ liệu ----------
  function index(){
    st.dayCache = {}; st.grpCache = {}; st.classes = {};
    st.saved.forEach(function(l){ l._d = (pDate(l.date) ? key(pDate(l.date)) : ''); l.classCode = classCodeOf(l.className || ''); if (l.classCode) st.classes[l.classCode] = 1; });
    st.tkb.forEach(function(it){ DAYKEYS.forEach(function(ks){ var cn = String(pick(it, ks)).trim(); if (cn) st.classes[classCodeOf(cn)] = 1; }); });
    var sel = $('lbgc-class'), keep = st.cls;
    sel.innerHTML = '<option value="">Tất cả lớp</option>' + Object.keys(st.classes).sort().map(function(c){ return '<option value="' + esc(c) + '">' + esc(c) + '</option>'; }).join('');
    sel.value = st.classes[keep] ? keep : ''; st.cls = sel.value;
  }
  function get(action){
    return fetch(BASE + '?action=' + action + '&t=' + Date.now()).then(function(r){
      if (!r.ok) throw new Error(action + ': HTTP ' + r.status);
      return r.json();
    });
  }
  function load(force){
    if (st.loading) return;
    if (!force && st.loadedAt && Date.now() - st.loadedAt < 30000) return;
    st.loading = true;
    var stEl = $('lbgc-status'); if (!st.loadedAt) { stEl.className = 'lbgc-status'; stEl.textContent = 'Đang tải lịch báo giảng...'; }
    var errs = [];
    function safe(a){ return get(a).catch(function(e){ errs.push(e.message); return null; }); }
    Promise.all([safe('getData'), safe('getTimetable'), safe('getTeachingPlan')]).then(function(r){
      var a = r[0], b = r[1], c = r[2];
      if (!a && !b && !c) throw new Error(errs[0] || 'không có dữ liệu');
      st.saved = (a && Array.isArray(a.lessons)) ? a.lessons : [];
      st.tkb = (b && Array.isArray(b.timetable)) ? b.timetable : ((a && Array.isArray(a.timetable)) ? a.timetable : []);
      st.plan = (c && Array.isArray(c.teachingPlan)) ? c.teachingPlan : ((a && Array.isArray(a.teachingPlan)) ? a.teachingPlan : []);
      st.warn = errs.length ? ('Một phần dữ liệu chưa tải được (' + errs.join('; ') + ')') : '';
      st.err = false; st.loadedAt = Date.now(); index(); render();
    }).catch(function(e){
      st.err = true; stEl.className = 'lbgc-status err';
      stEl.textContent = '⚠️ Không tải được lịch báo giảng (' + e.message + '). Bấm ⟳ để thử lại.';
    }).then(function(){ st.loading = false; });
  }

  // ---------- hiển thị ----------
  function render(){
    var y = st.cur.getFullYear(), m = st.cur.getMonth();
    $('lbgc-title').textContent = 'Tháng ' + (m + 1) + '/' + y;
    var off = (new Date(y, m, 1).getDay() + 6) % 7;
    var days = new Date(y, m + 1, 0).getDate();
    var total = Math.ceil((off + days) / 7) * 7;
    var today = key(new Date()), html = '', monthCount = 0;
    for (var i = 0; i < total; i++){
      var d = new Date(y, m, 1 - off + i), k = key(d), inM = d.getMonth() === m;
      var list = dayList(k); if (inM) monthCount += list.length;
      var cls = 'lbgc-cell' + (inM ? '' : ' out') + (k === today ? ' today' : '') + (k === st.sel ? ' sel' : '');
      var chips = list.slice(0, 3).map(function(l){
        return '<span class="lbgc-chip s' + sessOrd(l.session) + '">T' + esc(l.period) + ' ' + esc(l.classCode) + '</span>';
      }).join('');
      if (list.length > 3) chips += '<div class="lbgc-more">+' + (list.length - 3) + ' tiết</div>';
      html += '<div class="' + cls + '" data-k="' + k + '"><div class="d">' + d.getDate() + '</div>' + chips +
        (list.length ? '<div class="lbgc-badge">' + list.length + '</div>' : '') + '</div>';
    }
    $('lbgc-grid').innerHTML = html;
    var stEl = $('lbgc-status');
    if (!st.err) {
      stEl.className = 'lbgc-status';
      stEl.textContent = st.loadedAt ? ('Tháng này có ' + monthCount + ' tiết' + (st.cls ? ' (lớp ' + st.cls + ')' : '') + ' · cập nhật lúc ' + new Date(st.loadedAt).toLocaleTimeString('vi-VN') + (st.warn ? ' · ⚠️ ' + st.warn : '')) : 'Đang tải lịch báo giảng...';
    }
    renderDetail();
  }
  function item(l){
    var more = [['Yêu cầu cần đạt', l.requirement], ['Năng lực', l.competence], ['Hình thức', l.format], ['Tích hợp', l.integration]]
      .filter(function(x){ return x[1]; }).map(function(x){ return '<div><b>' + x[0] + ':</b> ' + esc(x[1]) + '</div>'; }).join('');
    return '<div class="lbgc-item s' + sessOrd(l.session) + '"><div class="t">' + esc(l.name || '(chưa có tên bài)') + '</div>' +
      '<div class="m">Tiết ' + esc(l.period) + (l.session ? ' (' + esc(l.session) + ')' : '') + ' · Lớp ' + esc(l.classCode) + (l.subject ? ' · ' + esc(l.subject) : '') + '</div>' +
      (more ? '<details><summary>Chi tiết</summary>' + more + '</details>' : '') + '</div>';
  }
  function fmtDay(k){ var p = k.split('-'); return pad(+p[2]) + '/' + pad(+p[1]) + '/' + p[0]; }
  function renderDetail(){
    var el = $('lbgc-detail'), today = key(new Date()), k = st.sel || today, list = dayList(k);
    var title = (st.sel ? 'Ngày ' : 'Hôm nay · ') + fmtDay(k) + ' (' + list.length + ' tiết)';
    var h = '<h4>' + title + '</h4>' + (list.length ? list.map(item).join('') : '<div class="lbgc-status">Không có tiết báo giảng.</div>');
    el.innerHTML = h;
  }

  $('lbgc-grid').addEventListener('click', function(e){
    var c = e.target; while (c && c !== this && !(c.getAttribute && c.getAttribute('data-k'))) c = c.parentNode;
    if (!c || c === this) return;
    var k = c.getAttribute('data-k'); st.sel = (st.sel === k) ? null : k; render();
  });
  $('lbgc-prev').addEventListener('click', function(){ st.cur = new Date(st.cur.getFullYear(), st.cur.getMonth() - 1, 1); render(); });
  $('lbgc-next').addEventListener('click', function(){ st.cur = new Date(st.cur.getFullYear(), st.cur.getMonth() + 1, 1); render(); });
  $('lbgc-today').addEventListener('click', function(){ var n = new Date(); st.cur = new Date(n.getFullYear(), n.getMonth(), 1); st.sel = key(n); render(); });
  $('lbgc-class').addEventListener('change', function(){ st.cls = this.value; render(); });
  $('lbgc-refresh').addEventListener('click', function(){ load(true); });

  var tabs = box.querySelectorAll('.lbgc-tab');
  Array.prototype.forEach.call(tabs, function(t){
    t.addEventListener('click', function(){
      Array.prototype.forEach.call(tabs, function(x){ x.classList.remove('active'); });
      t.classList.add('active');
      var g = t.getAttribute('data-tab') === 'gcal';
      $('lbgc-panel-lbg').style.display = g ? 'none' : 'block';
      $('lbgc-panel-gcal').style.display = g ? 'block' : 'none';
    });
  });

  function visible(){ return box.style.display !== 'none'; }
  if (btn) btn.addEventListener('click', function(){ setTimeout(function(){ if (visible()) { render(); load(false); } }, 80); });
  setInterval(function(){ if (visible() && !document.hidden) load(true); }, REFRESH_MS);
  render();
})();
