(function(){
  var URL_API = 'https://script.google.com/macros/s/AKfycbwxLYPwIo6UsWlhF2zbUreKQur7vdER7taw1ygiE86gv4a8O90mWlQeqFtisU0PiJGXgw/exec?action=members';
  var box = document.getElementById('tv-box'); if (!box) return;
  var data = null, tab = 'active';
  function $(i){ return document.getElementById(i); }
  function esc(s){ return String(s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
  function item(m, sub){
    return '<div class="tv-item"><div class="tv-av">' + esc((m.name||'?').trim().charAt(0).toUpperCase()) +
           '</div><div>' + esc(m.name) + '<small>' + esc(sub||'') + '</small></div></div>';
  }
  function render(){
    if (!data) return;
    $('tv-stats').innerHTML = [['total','Thành viên'],['activeCount','Tích cực tuần này'],['newCount','Mới 30 ngày']]
      .map(function(x){ return '<div class="tv-stat"><b>' + (data[x[0]]||0) + '</b><span>' + x[1] + '</span></div>'; }).join('');
    var L = tab==='active' ? data.active : tab==='new' ? data.newest : data.all, h = '';
    (L||[]).forEach(function(m,i){
      var sub = '';
      if (tab==='active') sub = (i<3 ? ['🥇','🥈','🥉'][i]+' ' : '') + m.sessions + ' buổi · ' + m.score + ' điểm';
      if (tab==='new') sub = (m.cls ? 'Lớp ' + m.cls + ' · ' : '') + 'Tham gia ' + (m.joined||'');
      if (tab==='all' && m.cls) sub = 'Lớp ' + m.cls;
      h += item(m, sub);
    });
    $('tv-list').innerHTML = h || 'Chưa có dữ liệu.';
  }
  box.querySelectorAll('.tv-tabs button').forEach(function(b){
    b.onclick = function(){
      box.querySelectorAll('.tv-tabs button').forEach(function(x){ x.classList.remove('on'); });
      b.classList.add('on'); tab = b.getAttribute('data-t'); render();
    };
  });
  fetch(URL_API).then(function(r){ return r.json(); }).then(function(j){
    data = j.data || j; box.style.display = 'block'; render();
  }).catch(function(){ /* chưa cài API thì ẩn khung, không hiện lỗi */ });
})();
