// 
            // JavaScript for enhanced interactivity
            document.addEventListener('DOMContentLoaded', function() {
              const websiteCards = document.querySelectorAll('.website-card');

              // Add click effect
              websiteCards.forEach(card => {
                card.addEventListener('click', function(e) {
                  // Don't trigger if clicking the link directly
                  if (!e.target.closest('.website-link')) {
                    const link = this.querySelector('.website-link');
                    if (link) {
                      // Add click animation
                      this.style.transform = 'scale(0.98)';
                      setTimeout(() => {
                        this.style.transform = '';
                      }, 150);
                    }
                  }
                });
              });

              // Parallax effect on scroll
              window.addEventListener('scroll', function() {
                const scrolled = window.pageYOffset;
                const parallaxElements = document.querySelectorAll('.website-card');

                parallaxElements.forEach((element, index) => {
                  const rate = scrolled * -0.1 + (index * 10);
                  element.style.transform = `translateY(${rate}px)`;
                });
              });

              // Intersection Observer for animation on scroll
              const observerOptions = {
                threshold: 0.1,
                rootMargin: '0px 0px -50px 0px'
              };

              const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                  if (entry.isIntersecting) {
                    entry.target.style.opacity = '1';
                    entry.target.style.transform = 'translateY(0)';
                  }
                });
              }, observerOptions);

              websiteCards.forEach(card => {
                observer.observe(card);
              });
            });

