body.script:
// 

         // =========================================================================
         //         MAIN APPLICATION CLASS - PHIÊN BẢN SỬA LỖI HOÀN CHỈNH
         //         Tác giả: Thầy Hùng - Cập nhật & Tối ưu bởi Gemini
         // =========================================================================
         class PhysicsApp {
         constructor() {
         // KHỞI TẠO CƠ BẢN
         this._initializeConfig();
         this._initializeStorageKeys();
         this._initializeMappings();
         this._initializeCourseInfo();
         this._initializeQuotes();
         this._initializeTestimonials();
         this._initializeRewardSystem();
         this._initializeMusicPlaylist();
         this._initializeOnlineUsersSystem(); // <-- THÊM DÒNG NÀY

         this.dom = this._initDomElements();
         this.cart = this._loadFromStorage(this.storageKeys.CART, []);
         this.userPoints = 0;
         this.allProducts = []; // Lưu trữ dữ liệu sản phẩm động sau khi tải

         this._init();
         }
         // =========================================================================
         // PHẦN QUẢN LÝ WIDGET "ĐANG ONLINE" VỚI TÍNH NĂNG THU GỌN
         // =========================================================================

         _setupOnlineUsersWidget() {
         const widget = document.getElementById('online-users-container');
         const header = widget.querySelector('.online-users-header');
         const arrow = document.createElement('span');

         arrow.className = 'toggle-arrow';
         arrow.innerHTML = '▼';

         // Thêm mũi tên vào header
         header.appendChild(arrow);

         // Kiểm tra trạng thái thu gọn từ localStorage
         const isCollapsed = localStorage.getItem('onlineWidgetCollapsed') === 'true';

         if (isCollapsed) {
         widget.classList.add('collapsed');
         arrow.classList.add('collapsed');
         }

         // Xử lý sự kiện click để thu gọn/mở rộng
         header.addEventListener('click', () => {
         widget.classList.toggle('collapsed');
         arrow.classList.toggle('collapsed');

         // Lưu trạng thái vào localStorage
         localStorage.setItem('onlineWidgetCollapsed', widget.classList.contains('collapsed'));
         });

         // Tự động thu gọn sau 10 giây nếu người dùng không tương tác
         setTimeout(() => {
         if (!widget.classList.contains('collapsed') && !localStorage.getItem('onlineWidgetCollapsed')) {
         widget.classList.add('collapsed');
         arrow.classList.add('collapsed');
         localStorage.setItem('onlineWidgetCollapsed', 'true');
         }
         }, 10000);
         }
         //=========================================================================
         //                           Chát online
         //==========================================================================
         // 1. Thêm phương thức setupChatSystem
         _setupChatSystem() {
         this.chatWidget = document.getElementById('chat-widget');
         this.openChatBtn = document.getElementById('open-chat');
         this.closeChatBtn = document.getElementById('close-chat');
         this.chatMessages = document.getElementById('chat-messages');
         this.chatInput = document.getElementById('chat-input');
         this.sendMessageBtn = document.getElementById('send-message');

         // Mở/đóng chat
         this.openChatBtn.addEventListener('click', () => {
         this.chatWidget.style.display = 'flex';
         this.openChatBtn.style.display = 'none';
         });

         this.closeChatBtn.addEventListener('click', () => {
         this.chatWidget.style.display = 'none';
         this.openChatBtn.style.display = 'block';
         });

         // Gửi tin nhắn
         const sendMessage = () => {
         const message = this.chatInput.value.trim();
         if (message) {
         this._sendChatMessage(message);
         this.chatInput.value = '';
         }
         };

         this.sendMessageBtn.addEventListener('click', sendMessage);
         this.chatInput.addEventListener('keypress', (e) => {
         if (e.key === 'Enter') sendMessage();
         });

         // Thiết lập lắng nghe tin nhắn mới
         this._setupChatListener();
         }

         // 2. Thêm phương thức gửi tin nhắn
         async _sendChatMessage(message) {
         // Hiển thị tin nhắn của người dùng ngay lập tức
         this._addMessageToChat(this.userName, message, 'user');

         try {
         // Gửi tin nhắn đến server (mô phỏng)
         console.log("Tin nhắn đã gửi:", message);
         // Trong thực tế, bạn sẽ gửi request đến server ở đây

         // Mô phỏng phản hồi từ admin sau 2 giây
         setTimeout(() => {
         this._addMessageToChat('Admin', 'Cảm ơn bạn đã liên hệ. Chúng tôi sẽ phản hồi sớm!', 'admin');
         }, 2000);
         } catch (error) {
         console.error("Lỗi khi gửi tin nhắn:", error);
         this._addMessageToChat('Hệ thống', 'Không thể gửi tin nhắn. Vui lòng thử lại sau.', 'admin');
         }
         }

         // 3. Thêm phương thức hiển thị tin nhắn
         _addMessageToChat(sender, message, type) {
         const messageElement = document.createElement('div');
         messageElement.className = `message ${type}`;

         const now = new Date();
         const timeString = now.toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' });

         messageElement.innerHTML = `
         <div class="message-content">${message}</div>
         <div class="message-time">${sender} • ${timeString}</div>
         `;

         this.chatMessages.appendChild(messageElement);
         this.chatMessages.scrollTop = this.chatMessages.scrollHeight;
         }
