         // Thêm dòng này để khởi tạo hệ thống chat
         this._setupChatSystem();

         console.log("Physics App Initialized with Chat System");

         console.log("Physics App Initialized with Online Users Tracking");
         document.dispatchEvent(new Event('physicsAppReady'));
         // Hiển thị thông báo đăng nhập nếu người dùng chưa đăng nhập
