         // =========================================================================
         // Slide ảnh chào mừng
         // =========================================================================
         document.addEventListener('DOMContentLoaded', function() {
            // Khởi tạo slider
            const slider = document.querySelector('.modern-slider');
            const slides = document.querySelectorAll('.modern-slide');
            const dots = document.querySelectorAll('.modern-dot');
            const prevBtn = document.querySelector('.modern-control.prev');
            const nextBtn = document.querySelector('.modern-control.next');
            const currentSlideEl = document.querySelector('.current-slide');
            const totalSlidesEl = document.querySelector('.total-slides');

            let currentSlide = 0;
            const totalSlides = slides.length;

            // Thiết lập tổng số slide
            totalSlidesEl.textContent = totalSlides;

            // Hàm cập nhật slide
            function updateSlide() {
                slider.style.transform = `translateX(-${currentSlide * 100}%)`;

                // Cập nhật trạng thái active
                slides.forEach((slide, index) => {
                    slide.classList.toggle('active', index === currentSlide);
                });

                dots.forEach((dot, index) => {
                    dot.classList.toggle('active', index === currentSlide);
                });

                // Cập nhật số đếm
                currentSlideEl.textContent = currentSlide + 1;
            }

            // Sự kiện nút next
            nextBtn.addEventListener('click', function() {
                currentSlide = (currentSlide + 1) % totalSlides;
                updateSlide();
            });

            // Sự kiện nút prev
            prevBtn.addEventListener('click', function() {
                currentSlide = (currentSlide - 1 + totalSlides) % totalSlides;
                updateSlide();
            });

            // Sự kiện chấm điều hướng
            dots.forEach((dot, index) => {
                dot.addEventListener('click', function() {
                    currentSlide = index;
                    updateSlide();
                });
            });

            // Tự động chuyển slide
            let autoSlide = setInterval(function() {
                currentSlide = (currentSlide + 1) % totalSlides;
                updateSlide();
            }, 5000);

            // Dừng tự động chuyển slide khi hover
            const sliderContainer = document.querySelector('.modern-slider-container');
            sliderContainer.addEventListener('mouseenter', function() {
                clearInterval(autoSlide);
            });

            sliderContainer.addEventListener('mouseleave', function() {
                autoSlide = setInterval(function() {
                    currentSlide = (currentSlide + 1) % totalSlides;
                    updateSlide();
                }, 5000);
            });

            // Khởi tạo ban đầu
            updateSlide();
         });

