         // DRAGGABLE ONLINE USERS WIDGET
         document.addEventListener('DOMContentLoaded', function() {
           const widget = document.getElementById('online-users-container');
           if (!widget) return;

           // Thêm mũi tên thu gọn vào header
           const header = widget.querySelector('.online-users-header');
           if (header && !header.querySelector('.toggle-arrow')) {
             const toggleArrow = document.createElement('span');
             toggleArrow.className = 'toggle-arrow';
             toggleArrow.innerHTML = '▼';
             header.appendChild(toggleArrow);

             // Thêm sự kiện thu gọn/mở rộng
             toggleArrow.addEventListener('click', function(e) {
               e.stopPropagation();
               widget.classList.toggle('collapsed');
               toggleArrow.classList.toggle('collapsed');
             });
           }

           // Thêm tính năng kéo thả
           let isDragging = false;
           let currentX;
           let currentY;
           let initialX;
           let initialY;
           let xOffset = 0;
           let yOffset = 0;

           // Hàm bắt đầu kéo
           function dragStart(e) {
             // Chỉ kéo khi click vào header
             if (!e.target.closest('.online-users-header')) return;

             initialX = e.clientX - xOffset;
             initialY = e.clientY - yOffset;

             if (e.target === header || header.contains(e.target)) {
               isDragging = true;
               widget.classList.add('dragging');

               // Ngăn chặn sự kiện mặc định
               e.preventDefault();
             }
           }

           // Hàm kéo
           function drag(e) {
             if (isDragging) {
               e.preventDefault();

               currentX = e.clientX - initialX;
               currentY = e.clientY - initialY;

               xOffset = currentX;
               yOffset = currentY;

               setTranslate(currentX, currentY, widget);
             }
           }

           // Hàm kết thúc kéo
           function dragEnd(e) {
             initialX = currentX;
             initialY = currentY;
             isDragging = false;
             widget.classList.remove('dragging');

             // Lưu vị trí vào localStorage
             saveWidgetPosition();
           }

           // Hàm đặt vị trí widget
           function setTranslate(xPos, yPos, el) {
             el.style.left = xPos + 'px';
             el.style.top = yPos + 'px';
             el.style.right = 'auto'; // Xóa right để ưu tiên left
           }

           // Lưu vị trí widget
           function saveWidgetPosition() {
             const position = {
               x: xOffset,
               y: yOffset
             };
             localStorage.setItem('onlineWidgetPosition', JSON.stringify(position));
           }

           // Tải vị trí widget đã lưu
           function loadWidgetPosition() {
             const savedPosition = localStorage.getItem('onlineWidgetPosition');
             if (savedPosition) {
               const position = JSON.parse(savedPosition);
               xOffset = position.x;
               yOffset = position.y;
               setTranslate(position.x, position.y, widget);
             }
           }

           // Thêm sự kiện cho widget
           widget.addEventListener('mousedown', dragStart, false);
           document.addEventListener('mousemove', drag, false);
           document.addEventListener('mouseup', dragEnd, false);

           // Tải vị trí đã lưu khi trang được tải
           loadWidgetPosition();

           // Responsive: Ẩn widget trên mobile
           function handleResize() {
             if (window.innerWidth <= 768) {
               widget.style.position = 'static';
               widget.style.width = '100%';
               widget.style.margin = '20px 0';
             } else {
               widget.style.position = 'fixed';
               widget.style.width = '280px';
               widget.style.margin = '0';

               // Đảm bảo widget không bị đẩy ra khỏi màn hình
               const rect = widget.getBoundingClientRect();
               if (rect.left < 0) {
                 widget.style.left = '10px';
                 xOffset = 10;
               }
               if (rect.top < 0) {
                 widget.style.top = '10px';
                 yOffset = 10;
               }
               if (rect.right > window.innerWidth) {
                 widget.style.left = (window.innerWidth - rect.width - 10) + 'px';
                 xOffset = window.innerWidth - rect.width - 10;
               }
               if (rect.bottom > window.innerHeight) {
                 widget.style.top = (window.innerHeight - rect.height - 10) + 'px';
                 yOffset = window.innerHeight - rect.height - 10;
               }

               saveWidgetPosition();
             }
           }

           // Xử lý sự kiện thay đổi kích thước cửa sổ
           window.addEventListener('resize', handleResize);
           handleResize(); // Chạy lần đầu khi tải trang
         });

         // JavaScript để tải và hiển thị tin tức - Phiên bản đã sửa lỗi
         document.addEventListener('DOMContentLoaded', function() {
         // Đợi một chút để đảm bảo các script khác đã load
         setTimeout(function() {
         initNewsSection();
