         function initNewsSection() {
         const newsContainer = document.getElementById('news-container');
         const loadMoreBtn = document.getElementById('load-more-news');

         if (!newsContainer) {
         console.error('Không tìm thấy container tin tức');
         return;
         }

         let currentPage = 0;
         const postsPerPage = 6;

         // Ảnh mặc định
         const defaultImage = 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhsx26L4YU2v5RzZKx50vVSr-4PCkveK1DQege_O-qiSDx3YsoC-ErmViXpi9w68KoCamz9Xkwi8O2mhvSsaF-XMIsC5G3lhKCRsWe42k4wnDUCB9iwKwqowGjJnif1FbehSUQzV6fjlrQPgpvKo0Ielpp4_KTEshViOLpW4sMlyWF_CC60VOX1njyTb54/s1600/logo_256x256.png';

         // Hàm tải tin tức
         function loadNews(page = 0) {
         const loadingHtml = `
         <div class='loading-news'>
            <div class='spinner'/>
            <p>Đang tải tin tức...</p>
         </div>
         `;

         if (page === 0) {
         newsContainer.innerHTML = loadingHtml;
         }

         // Tạo URL API cho Blogger
         const blogUrl = 'https://thayhungp.blogspot.com';
         const label = 'tin-tuc';
         const startIndex = page * postsPerPage;

         // Sử dụng JSONP thay vì fetch để tránh CORS
         loadNewsJSONP(blogUrl, label, startIndex, postsPerPage);
         }

         // Hàm tải tin tức bằng JSONP
         function loadNewsJSONP(blogUrl, label, startIndex, maxResults) {
         // Tạo callback function name
         const callbackName = 'handleNewsData_' + Date.now();

         // Tạo script element
         const script = document.createElement('script');
         const url = `${blogUrl}/feeds/posts/default/-/${label}?alt=json-in-script&start-index=${startIndex + 1}&max-results=${maxResults}&callback=${callbackName}`;

         script.src = url;

         // Định nghĩa callback function
         window[callbackName] = function(data) {
         // Xóa script sau khi sử dụng
         document.head.removeChild(script);
         delete window[callbackName];

         displayNews(data.feed.entry || []);
         };

         // Xử lý lỗi
         script.onerror = function() {
         document.head.removeChild(script);
         delete window[callbackName];
         displayError();
         };

         // Thêm script vào head
         document.head.appendChild(script);
         }

         // Hàm hiển thị tin tức
         function displayNews(entries) {
         if (currentPage === 0) {
         newsContainer.innerHTML = '';
         }

         if (entries.length === 0) {
         if (currentPage === 0) {
            newsContainer.innerHTML = `
               <div class='no-news' style='grid-column: 1 / -1; text-align: center; padding: 40px;'>
                  <i class='fas fa-newspaper' style='font-size: 3rem; color: #ddd; margin-bottom: 15px;'></i>
                  <h3 style='color: #666; margin-bottom: 10px;'>Chưa có tin tức nào</h3>
                  <p style='color: #888;'>Các tin tức mới sẽ được cập nhật tại đây</p>
               </div>
            `;
         }
         if (loadMoreBtn) loadMoreBtn.style.display = 'none';
         return;
         }

         // Hiển thị bài viết
         entries.forEach(entry => {
         const title = entry.title.$t;
         const published = new Date(entry.published.$t);
         const author = entry.author[0].name.$t;
         const postUrl = entry.link.find(link => link.rel === 'alternate').href;

         // Tìm ảnh đại diện - sử dụng ảnh mặc định nếu không có
         let thumbnail = defaultImage;
         if (entry.media$thumbnail) {
            thumbnail = entry.media$thumbnail.url;
         } else {
            // Thử tìm ảnh trong content nếu không có thumbnail
            const content = entry.content ? entry.content.$t : '';
            const imgMatch = content.match(/<img[^>]+src="([^">]+)"/);
            if (imgMatch && imgMatch[1]) {
               thumbnail = imgMatch[1];
            }
         }

         // Tạo excerpt từ nội dung
         let excerpt = '';
         if (entry.content) {
            // Loại bỏ HTML tags và giới hạn độ dài
            excerpt = entry.content.$t.replace(/<[^>]*>/g, '').substring(0, 150) + '...';
         }

         const newsCard = document.createElement('div');
         newsCard.className = 'news-card';
         newsCard.innerHTML = `
            <div class='news-image'>
