(function () {
  function isMobile() { return window.innerWidth <= 768; }

  document.addEventListener('DOMContentLoaded', function () {
    var toggleBtn = document.getElementById('mobile-menu-toggle');
    var nav = document.getElementById('main-nav');
    var overlay = document.getElementById('mobile-menu-overlay');
    if (!toggleBtn || !nav || !overlay) return;

    function openNav() {
      nav.classList.add('active');
      overlay.classList.add('active');
      toggleBtn.classList.add('active');
      document.body.classList.add('mobile-nav-open');
    }
    function closeNav() {
      nav.classList.remove('active');
      overlay.classList.remove('active');
      toggleBtn.classList.remove('active');
      document.body.classList.remove('mobile-nav-open');
      nav.querySelectorAll('.submenu.open').forEach(function (el) {
        el.classList.remove('open');
      });
      nav.querySelectorAll('.submenu-toggle.open').forEach(function (el) {
        el.classList.remove('open');
      });
    }

    toggleBtn.addEventListener('click', function () {
      if (nav.classList.contains('active')) { closeNav(); } else { openNav(); }
    });
    overlay.addEventListener('click', closeNav);

    // Thêm nút mũi tên cho mỗi mục có submenu, để bấm mở/đóng thay vì hover
    nav.querySelectorAll('li').forEach(function (li) {
      var submenu = li.querySelector(':scope > ul.submenu');
      var link = li.querySelector(':scope > a');
      if (!submenu || !link) return;

      link.style.paddingRight = '44px';

      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'submenu-toggle';
      btn.innerHTML = '&#9660;'; // ▼
      btn.setAttribute('aria-label', 'Mở mục con');
      li.appendChild(btn);

      btn.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        var isOpen = submenu.classList.contains('open');
        // Đóng các submenu anh em cùng cấp (accordion gọn hơn)
        var parentList = li.parentElement;
        if (parentList) {
          parentList.querySelectorAll(':scope > li > ul.submenu.open').forEach(function (sib) {
            if (sib !== submenu) sib.classList.remove('open');
          });
          parentList.querySelectorAll(':scope > li > .submenu-toggle.open').forEach(function (sib) {
            if (sib !== btn) sib.classList.remove('open');
          });
        }
        submenu.classList.toggle('open', !isOpen);
        btn.classList.toggle('open', !isOpen);
      });

      // Nếu link cha chỉ là "#" (không có trang riêng), bấm vào chữ cũng mở submenu
      var href = link.getAttribute('href') || '';
      if (href === '#' || href === '') {
        link.addEventListener('click', function (e) {
          if (isMobile()) {
            e.preventDefault();
            btn.click();
          }
        });
      }
    });

    // Đóng menu khi bấm 1 link lá (không có submenu) trên mobile
    nav.querySelectorAll('a').forEach(function (a) {
      a.addEventListener('click', function () {
        var parentLi = a.parentElement;
        var hasSubmenu = parentLi && parentLi.querySelector(':scope > ul.submenu');
        if (isMobile() && !hasSubmenu) closeNav();
      });
    });

    window.addEventListener('resize', function () {
      if (!isMobile()) closeNav();
    });
  });
})();
