(function () {
  function isDesktop() { return window.innerWidth > 768; }

  document.addEventListener('DOMContentLoaded', function () {
    var nav = document.querySelector('nav');
    if (!nav) return;
    var topMenu = nav.querySelector(':scope > ul.menu');
    if (!topMenu) return;

    var activePairs = [];

    function positionOne(pair) {
      var rect = pair.li.getBoundingClientRect();
      if (pair.isNested) {
        pair.submenu.style.top = rect.top + 'px';
        pair.submenu.style.left = rect.right + 'px';
      } else {
        pair.submenu.style.top = rect.bottom + 'px';
        pair.submenu.style.left = rect.left + 'px';
      }
    }

    function repositionActive() {
      activePairs.forEach(positionOne);
    }

    topMenu.querySelectorAll('li').forEach(function (li) {
      var submenu = li.querySelector(':scope > ul.submenu');
      if (!submenu) return;
      var isNested = li.parentElement.closest('ul.submenu') !== null;
      var pair = { li: li, submenu: submenu, isNested: isNested };

      li.addEventListener('mouseenter', function () {
        if (!isDesktop()) return;
        positionOne(pair);
        if (activePairs.indexOf(pair) === -1) activePairs.push(pair);
      });
      li.addEventListener('mouseleave', function () {
        var idx = activePairs.indexOf(pair);
        if (idx !== -1) activePairs.splice(idx, 1);
      });
    });

    nav.addEventListener('scroll', function () {
      if (isDesktop()) repositionActive();
    });
    window.addEventListener('resize', function () {
      if (isDesktop()) repositionActive();
    });
  });
})();
