(function () {
  'use strict';

  /* ---------- Chuẩn hoá & so khớp văn bản tiếng Việt ---------- */
  function removeTones(str) {
    return str.normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .replace(/đ/g, 'd').replace(/Đ/g, 'D');
  }
  function normalize(str) {
    return removeTones(String(str || '').toLowerCase().trim()).replace(/\s+/g, ' ');
  }

  var micBtn, transcriptBox, statusText, heardText, helpPanel, helpList, helpCloseBtn;

  function setStatus(text) {
    if (statusText) statusText.textContent = text;
    if (transcriptBox) transcriptBox.classList.add('show');
  }
  function setHeard(text) {
    if (heardText) heardText.textContent = text ? ('Bạn nói: "' + text + '"') : '';
  }
  function notify(message, type) {
    if (window.physicsApp && typeof window.physicsApp.showNotification === 'function') {
      try { window.physicsApp.showNotification(message, type || 'info'); } catch (e) {}
    }
    setStatus(message);
  }

  /* ---------- Tìm liên kết bài học gần đúng nhất trong menu ---------- */
  function findBestNavLink(spokenText) {
    var links = Array.prototype.slice.call(document.querySelectorAll('#main-nav a[href]'));
    var target = normalize(spokenText);
    if (!target) return null;
    var targetWords = target.split(' ').filter(Boolean);
    var best = null, bestScore = 0;

    links.forEach(function (a) {
      var label = normalize(a.textContent);
      if (!label) return;
      var score = 0;
      if (label === target) score = 1000;
      else if (label.indexOf(target) !== -1) score = 500 + target.length;
      else if (target.indexOf(label) !== -1) score = 400 + label.length;
      else {
        var labelWords = label.split(' ').filter(Boolean);
        targetWords.forEach(function (w) {
          if (w.length > 1 && labelWords.indexOf(w) !== -1) score += 10;
        });
      }
      if (score > bestScore) { bestScore = score; best = a; }
    });
    return bestScore >= 10 ? best : null;
  }

  /* ---------- Danh sách lệnh giọng nói được hỗ trợ ---------- */
  var commands = [
    {
      test: /^(mo|hien|bat)\s+(menu|danh muc)/,
      title: 'Mở menu',
      hint: 'mở danh mục điều hướng (trên di động)',
      run: function () {
        var btn = document.getElementById('mobile-menu-toggle');
        var nav = document.getElementById('main-nav');
        if (btn && nav && !nav.classList.contains('active')) { btn.click(); notify('Đã mở menu'); }
        else notify('Menu đã hiển thị');
      }
    },
    {
      test: /^(dong|tat)\s+(menu|danh muc)/,
      title: 'Đóng menu',
      hint: 'đóng danh mục điều hướng',
      run: function () {
        var btn = document.getElementById('mobile-menu-toggle');
        var nav = document.getElementById('main-nav');
        if (btn && nav && nav.classList.contains('active')) { btn.click(); notify('Đã đóng menu'); }
        else notify('Menu hiện đang đóng');
      }
    },
    {
      test: /^(tim kiem|tim)\s+(.+)/,
      title: 'Tìm kiếm [từ khoá]',
      hint: 'tìm bài viết theo từ khoá, ví dụ "tìm kiếm định luật newton"',
      run: function (m) {
        var q = m[2].trim();
        var input = document.querySelector('.search-bar input[type="text"]');
        var btn = document.getElementById('search-button');
        if (input) {
          input.value = q;
          if (btn) btn.click();
          else window.location.href = window.location.origin + '/search?q=' + encodeURIComponent(q);
          notify('Đang tìm: ' + q);
        } else {
          notify('Không tìm thấy ô tìm kiếm trên trang');
        }
      }
    },
    {
      test: /^(mo|xem)\s*gio hang/,
      title: 'Mở giỏ hàng',
      hint: '',
      run: function () {
        var popup = document.getElementById('cart-popup');
        if (popup) { popup.classList.remove('hidden'); popup.style.display = 'flex'; notify('Đã mở giỏ hàng'); }
      }
    },
    {
      test: /^dong gio hang/,
      title: 'Đóng giỏ hàng',
      hint: '',
      run: function () {
        var closeBtn = document.getElementById('close-cart-popup');
        var popup = document.getElementById('cart-popup');
        if (closeBtn) closeBtn.click();
        else if (popup) { popup.classList.add('hidden'); popup.style.display = 'none'; }
        notify('Đã đóng giỏ hàng');
      }
    },
    {
      test: /^(thanh toan|tien hanh thanh toan)/,
      title: 'Thanh toán',
      hint: 'tiến hành thanh toán đơn hàng',
      run: function () {
        var popupBtn = document.getElementById('checkout-btn-popup');
        var pageBtn = document.getElementById('checkoutBtn');
        if (popupBtn && popupBtn.offsetParent !== null) popupBtn.click();
        else if (pageBtn) { pageBtn.scrollIntoView({ behavior: 'smooth', block: 'center' }); pageBtn.click(); }
        notify('Đang chuyển tới thanh toán');
      }
    },
    {
      test: /^(huy thanh toan|huy bo)/,
      title: 'Hủy thanh toán',
      hint: '',
      run: function () {
        var cancelBtn = document.getElementById('cancelPayment');
        if (cancelBtn) { cancelBtn.click(); notify('Đã hủy thanh toán'); }
      }
    },
    {
      test: /^(mo|goi)\s+(chat|ho tro)/,
      title: 'Mở chat / Hỗ trợ',
      hint: 'mở khung chat hỗ trợ',
      run: function () {
        var btn = document.getElementById('open-chat');
        if (btn) { btn.click(); notify('Đã mở khung chat'); }
      }
    },
    {
      test: /^dong chat/,
      title: 'Đóng chat',
      hint: '',
      run: function () {
        var btn = document.getElementById('close-chat');
        if (btn) { btn.click(); notify('Đã đóng khung chat'); }
      }
    },
    {
      test: /^(bat|tat|mo|dong)\s+nhac/,
      title: 'Bật / Tắt nhạc',
      hint: 'chuyển trạng thái nhạc nền',
      run: function () {
        var btn = document.getElementById('musicControl');
        if (btn) { btn.click(); notify('Đã chuyển trạng thái nhạc nền'); }
      }
    },
    {
      test: /^(xem|danh sach|cuon (den|toi))\s*san pham/,
      title: 'Xem sản phẩm',
      hint: 'cuộn tới danh sách khoá học / sản phẩm',
      run: function () {
        var el = document.getElementById('product-list-container');
        if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); notify('Đang cuộn tới sản phẩm'); }
      }
    },
    {
      test: /^(len dau trang|ve dau trang)/,
      title: 'Lên đầu trang',
      hint: '',
      run: function () { window.scrollTo({ top: 0, behavior: 'smooth' }); notify('Đã lên đầu trang'); }
    },
    {
      test: /^(xuong cuoi trang|cuoi trang)/,
      title: 'Xuống cuối trang',
      hint: '',
      run: function () { window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' }); notify('Đã xuống cuối trang'); }
    },
    {
      test: /^dang nhap/,
      title: 'Đăng nhập',
      hint: 'di chuyển tới ô đăng nhập',
      run: function () {
        var box = document.getElementById('login-container');
        var user = document.getElementById('username');
        if (box) box.scrollIntoView({ behavior: 'smooth', block: 'center' });
        if (user) user.focus();
        notify('Mời bạn nhập tên đăng nhập');
      }
    },
    {
      test: /^(mo bai|vao bai|hoc bai|di den bai)\s+(.+)/,
      title: 'Mở bài [tên bài học]',
      hint: 'chuyển tới bài giảng theo tên, ví dụ "mở bài định luật 2 newton"',
      run: function (m) {
        var q = m[2].trim();
        var link = findBestNavLink(q);
        if (link) { notify('Đang mở: ' + link.textContent.trim()); window.location.href = link.href; }
        else notify('Không tìm thấy bài học phù hợp với: ' + q, 'warning');
      }
    },
    {
      test: /^(dung nghe|tat micro|tat tro ly|ngung nghe)/,
      title: 'Dừng nghe',
      hint: 'tắt trợ lý giọng nói',
      run: function () { stopListening(); notify('Đã tắt trợ lý giọng nói'); }
    },
    {
      test: /^(tro giup|huong dan|co the lam gi|danh sach lenh)/,
      title: 'Trợ giúp',
      hint: 'hiển thị danh sách lệnh này',
      run: function () { showHelp(); }
    }
  ];

  function buildHelpList() {
    if (!helpList) return;
    helpList.innerHTML = '';
    commands.forEach(function (c) {
      var li = document.createElement('li');
      li.innerHTML = '<b>' + c.title + '</b>' + (c.hint ? (' — ' + c.hint) : '');
      helpList.appendChild(li);
    });
  }
  function showHelp() { buildHelpList(); if (helpPanel) helpPanel.classList.remove('hidden'); }
  function hideHelp() { if (helpPanel) helpPanel.classList.add('hidden'); }

  function handleTranscript(rawText) {
    setHeard(rawText);
    var text = normalize(rawText);
    for (var i = 0; i < commands.length; i++) {
      var m = text.match(commands[i].test);
      if (m) { commands[i].run(m); return; }
    }
    // Không khớp lệnh cố định nào -> thử tìm bài học gần đúng nhất theo toàn bộ câu nói
    var link = findBestNavLink(text);
    if (link) {
      notify('Đang mở: ' + link.textContent.trim());
      window.location.href = link.href;
    } else {
      notify('Chưa hiểu lệnh này. Hãy nói "trợ giúp" để xem danh sách lệnh.', 'warning');
    }
  }

  /* ---------- Web Speech API: nhận diện giọng nói tiếng Việt ---------- */
  var SpeechRecognitionCtor = window.SpeechRecognition || window.webkitSpeechRecognition;
  var recognition = null, isListening = false;

  function initRecognition() {
    if (!SpeechRecognitionCtor) return null;
    var r = new SpeechRecognitionCtor();
    r.lang = 'vi-VN';
    r.continuous = false;
    r.interimResults = true;
    r.maxAlternatives = 1;

    r.onstart = function () {
      isListening = true;
      micBtn.classList.add('listening');
      setStatus('Đang nghe... hãy nói lệnh của bạn');
      setHeard('');
    };
    r.onresult = function (event) {
      var text = '';
      for (var i = event.resultIndex; i < event.results.length; i++) {
        text += event.results[i][0].transcript;
      }
      setHeard(text);
      if (event.results[event.results.length - 1].isFinal) {
        handleTranscript(text);
      }
    };
    r.onerror = function (event) {
      isListening = false;
      micBtn.classList.remove('listening');
      if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
        setStatus('Vui lòng cho phép truy cập micro để dùng tính năng này');
      } else if (event.error === 'no-speech') {
        setStatus('Không nghe thấy gì. Hãy thử lại.');
      } else {
        setStatus('Có lỗi xảy ra: ' + event.error);
      }
    };
    r.onend = function () {
      isListening = false;
      micBtn.classList.remove('listening');
    };
    return r;
  }

  function startListening() {
    if (!SpeechRecognitionCtor) {
      notify('Trình duyệt này chưa hỗ trợ nhận diện giọng nói. Hãy dùng Chrome hoặc Edge mới nhất.', 'warning');
      return;
    }
    if (!recognition) recognition = initRecognition();
    if (!isListening) {
      try { recognition.start(); } catch (e) { /* đang chạy dở, bỏ qua lỗi */ }
    }
  }
  function stopListening() {
    if (recognition && isListening) recognition.stop();
  }

  /* ---------- Khởi tạo giao diện khi trang tải xong ---------- */
  document.addEventListener('DOMContentLoaded', function () {
    micBtn = document.getElementById('voice-mic-btn');
    transcriptBox = document.getElementById('voice-transcript-box');
    statusText = document.getElementById('voice-status-text');
    heardText = document.getElementById('voice-heard-text');
    helpPanel = document.getElementById('voice-help-panel');
    helpList = document.getElementById('voice-help-list');
    helpCloseBtn = document.getElementById('voice-help-close');

    if (!micBtn) return;

    if (!SpeechRecognitionCtor) {
      micBtn.classList.add('unsupported');
      micBtn.title = 'Trình duyệt không hỗ trợ điều khiển bằng giọng nói';
    }

    micBtn.addEventListener('click', function () {
      if (isListening) stopListening(); else startListening();
    });
    micBtn.addEventListener('dblclick', function (e) { e.preventDefault(); showHelp(); });
    if (helpCloseBtn) helpCloseBtn.addEventListener('click', hideHelp);

    // Phím tắt Alt/Cmd + V để bật/tắt nghe nhanh
    document.addEventListener('keydown', function (e) {
      if ((e.altKey || e.metaKey) && e.key.toLowerCase() === 'v') {
        e.preventDefault();
        if (isListening) stopListening(); else startListening();
      }
    });
  });
})();
