(function () {
  // =========================================================================
  // [SỬA] CSS — trước đây nằm trong thẻ tĩnh (bị Blogger xoá mất
  // nội dung), giờ chuyển thành chuỗi JS và tự chèn vào  bên dưới.
  // Muốn đổi màu/kích thước/vị trí thì sửa trực tiếp trong chuỗi này.
  // =========================================================================
  // [SỬA] Khoảng cách từ mép phải màn hình tới nút Trợ giúp (đơn vị px).
  // Trang đang có 1 ô quảng cáo cố định ở góc phải (khoảng 90-100px) — để
  // 130px cho chắc, nút sẽ nằm hẳn bên trái ô quảng cáo đó, không bị che.
  // Nếu sau này quảng cáo đổi kích thước hoặc đổi vị trí, chỉ cần sửa số
  // này, không cần sửa gì khác.
  var TG_RIGHT_GAP = 130;

  var TG_CSS = ""
    + "#tg-help-fab{position:fixed;z-index:999999;display:flex;align-items:center;"
    + "gap:6px;background:#7c3aed;color:#fff;padding:10px 16px;border-radius:999px;"
    + "box-shadow:0 4px 14px rgba(0,0,0,.25);cursor:pointer;font-family:Arial,Helvetica,"
    + "sans-serif;font-size:14px;font-weight:bold;user-select:none;transition:"
    + "transform .15s ease,box-shadow .15s ease;}"
    + "#tg-help-fab:hover{transform:scale(1.05);box-shadow:0 6px 18px rgba(0,0,0,.32);}"
    + "#tg-help-fab .tg-fab-icon{font-size:16px;line-height:1;}"
    + "#tg-help-fab .tg-fab-text{white-space:nowrap;}"
    + "#tg-help-fab.tg-pos-middle-right{top:50%;right:" + TG_RIGHT_GAP + "px;transform:translateY(-50%);}"
    + "#tg-help-fab.tg-pos-middle-right:hover{transform:translateY(-50%) scale(1.05);}"
    + "#tg-help-fab.tg-pos-middle-left{top:50%;left:16px;transform:translateY(-50%);}"
    + "#tg-help-fab.tg-pos-middle-left:hover{transform:translateY(-50%) scale(1.05);}"
    + "#tg-help-fab.tg-pos-top-right{top:16px;right:16px;}"
    + "#tg-help-fab.tg-pos-bottom-left-high{bottom:90px;left:16px;}"
    + "#tg-guide-overlay{position:fixed;inset:0;z-index:1000000;background:rgba(0,0,0,.55);"
    + "display:none;align-items:center;justify-content:center;padding:16px;"
    + "font-family:Arial,Helvetica,sans-serif;}"
    + "#tg-guide-overlay.tg-open{display:flex;}"
    + "#tg-guide-card{background:#fff;max-width:420px;width:100%;border-radius:16px;"
    + "padding:24px;box-shadow:0 10px 40px rgba(0,0,0,.3);box-sizing:border-box;}"
    + "#tg-guide-dots{display:flex;gap:6px;margin-bottom:14px;}"
    + "#tg-guide-dots .tg-dot{width:8px;height:8px;border-radius:50%;background:#ddd;"
    + "transition:background .15s ease;}"
    + "#tg-guide-dots .tg-dot.tg-active{background:#7c3aed;}"
    + "#tg-guide-title{margin:0 0 10px;font-size:18px;color:#222;}"
    + "#tg-guide-text{margin:0 0 20px;font-size:15px;line-height:1.5;color:#444;}"
    + "#tg-guide-actions{display:flex;align-items:center;justify-content:space-between;"
    + "gap:10px;flex-wrap:wrap;}"
    + "#tg-guide-actions button{cursor:pointer;border-radius:8px;font-size:14px;"
    + "padding:8px 14px;border:1px solid transparent;font-family:inherit;}"
    + ".tg-btn-skip{background:transparent;color:#888;border-color:#ddd;}"
    + ".tg-btn-skip:hover{background:#f5f5f5;}"
    + ".tg-btn-nav{background:#7c3aed;color:#fff;font-weight:bold;}"
    + ".tg-btn-nav:hover{background:#6d28d9;}"
    + ".tg-btn-prev{background:#fff;color:#7c3aed;border-color:#7c3aed;font-weight:normal;"
    + "margin-right:8px;}"
    + ".tg-btn-prev:hover{background:#f5f3ff;}"
    + "@media (max-width:480px){#tg-help-fab .tg-fab-text{display:none;}"
    + "#tg-help-fab{padding:12px;border-radius:50%;}}";

  var styleTag = document.createElement('style');
  styleTag.setAttribute('id', 'tg-help-style');
  if (styleTag.styleSheet) { styleTag.styleSheet.cssText = TG_CSS; } // IE cũ, phòng hờ
  else { styleTag.appendChild(document.createTextNode(TG_CSS)); }
  document.head.appendChild(styleTag);

  // =========================================================================
  // [THÊM] VỊ TRÍ NÚT TRỢ GIÚP — đổi giá trị này nếu thấy nút vẫn đè lên
  // 1 nút/widget khác của trang nào đó, KHÔNG cần sửa CSS ở trên.
  // Các lựa chọn: 'middle-right' (mặc định, dán mép phải giữa màn hình),
  // 'middle-left' (mép trái giữa màn hình), 'top-right' (góc trên-phải),
  // 'bottom-left-high' (góc dưới-trái nhưng cách đáy 90px, tránh đè nút
  // mic/loa nếu trang có phát audio).
  // =========================================================================
  var TG_POSITION = 'middle-right';

  // =========================================================================
  // [THÊM] Hàm phụ trợ: kiểm tra bài viết ĐANG MỞ có gắn đúng 1 nhãn (label)
  // nào đó không — dùng để hướng dẫn hiện đúng cả khi học sinh bấm thẳng
  // vào 1 bài cụ thể (không chỉ đúng trên trang danh sách của nhãn đó).
  // Luôn bỏ qua các link nằm trong thanh menu #main-nav (menu có sẵn link
  // tới mọi nhãn trên MỌI trang, nên phải loại trừ để không nhận nhầm).
  // =========================================================================
  function pageHasLabel(label) {
    var links = document.querySelectorAll('a[href*="/search/label/"]');
    for (var i = 0; i < links.length; i++) {
      var a = links[i];
      if (a.closest && a.closest('#main-nav')) continue;
      var m = (a.getAttribute('href') || '').match(/\/search\/label\/([^\/?#]+)/);
      if (m && decodeURIComponent(m[1]) === label) return true;
    }
    return false;
  }
  // Giống trên nhưng khớp theo TIỀN TỐ nhãn (dùng cho GDĐP: bg-gd-10-1,
  // bg-gd-11-3, bg-gd-12-7... đều tính là "trang GDĐP").
  function pageHasLabelPrefix(prefix) {
    var links = document.querySelectorAll('a[href*="/search/label/"]');
    for (var i = 0; i < links.length; i++) {
      var a = links[i];
      if (a.closest && a.closest('#main-nav')) continue;
      var m = (a.getAttribute('href') || '').match(/\/search\/label\/([^\/?#]+)/);
      if (m && decodeURIComponent(m[1]).indexOf(prefix) === 0) return true;
    }
    return false;
  }

  // =========================================================================
  // GUIDES — DANH SÁCH HƯỚNG DẪN THEO TỪNG LOẠI TRANG
  // Thêm/sửa/xoá thoải mái trong mảng này. Trang nào khớp "match" ĐẦU TIÊN
  // (theo thứ tự trong mảng) sẽ được dùng — nên đặt các "match" đặc trưng,
  // hẹp hơn lên trước, "match" chung chung để cuối cùng.
  // =========================================================================
  var GUIDES = [
    {
      key: 'luyen-tap-trac-nghiem',
      // Nhận diện trang luyện tập trắc nghiệm Vật lí (kiểu như new_15.txt):
      // các trang này có màn hình chọn Lớp/Bài (#lesson-picker-overlay) hoặc
      // biến toàn cục PAGE_LABEL.
      match: function () {
        return !!document.getElementById('lesson-picker-overlay') ||
               typeof window.PAGE_LABEL !== 'undefined';
      },
      steps: [
        { title: 'Chào mừng bạn đến với bài luyện tập!',
          text: 'Đây là trang luyện tập trắc nghiệm Vật lí. Hãy làm theo các bước sau để bắt đầu làm bài.' },
        { title: 'Bước 1 — Chọn Lớp và Bài',
          text: 'Chọn đúng Lớp và Bài học bạn muốn luyện tập ở màn hình đầu tiên, sau đó bấm "Xác nhận".' },
        { title: 'Bước 2 — Đăng nhập bằng số điện thoại',
          text: 'Nhập đúng số điện thoại đã đăng ký với thầy để hệ thống lưu đúng kết quả và điểm của bạn.' },
        { title: 'Bước 3 — Đọc quy chế trước khi bắt đầu',
          text: 'Tích vào ô "Tôi đã đọc quy chế" rồi mới bấm được "Bắt Đầu Làm Bài". Lưu ý quan trọng: trong lúc làm bài KHÔNG được chuyển sang tab/cửa sổ khác, KHÔNG dán (paste) nội dung, KHÔNG mở DevTools — hệ thống tự động ghi nhận vi phạm, đủ 3 lần sẽ khoá bài vĩnh viễn và đồng bộ khoá trên mọi thiết bị.' },
        { title: 'Bước 4 — Làm bài và nộp bài',
          text: 'Trả lời từng câu, có thể bấm "Bỏ qua" nếu chưa chắc rồi quay lại sau. Làm xong phần Cơ bản thì bấm "Nộp bài" để xem điểm ngay. Muốn thử sức thêm thì làm tiếp phần Nâng cao.' },
        { title: 'Thấy câu hỏi bị sai hoặc thiếu dữ kiện?',
          text: 'Bấm nút "⚠️ Báo lỗi" ngay dưới câu hỏi đó để báo cho thầy biết, không cần nhắn tin riêng.' }
      ]
    },
    {
      key: 'bai-giang',
      // Menu "Bài giảng" trỏ tới /search/label/bg — mỗi bài giảng cụ thể
      // cũng gắn nhãn "bg" nên nhận diện được cả khi mở thẳng 1 bài.
      match: function () {
        return location.pathname === '/search/label/bg' || pageHasLabel('bg');
      },
      steps: [
        { title: 'Mục Bài giảng',
          text: 'Đây là nơi tổng hợp bài giảng chính khoá theo từng chủ đề/lớp. Mỗi bài giảng trình bày theo các bước tổ chức dạy học (Khởi động, Hình thành kiến thức, Luyện tập, Vận dụng...), có thể kèm video ở phần Khởi động và hình ảnh minh hoạ ở các bước có nội dung trực quan. Chọn đúng bài của lớp mình đang học để xem.' }
      ]
    },
    {
      key: 'chuyen-de-vat-li',
      match: function () {
        return location.pathname === '/search/label/cd' || pageHasLabel('cd');
      },
      steps: [
        { title: 'Mục Chuyên đề vật lí',
          text: 'Đây là các bài mở rộng, đào sâu theo từng chủ đề (khác với Bài giảng chính khoá), phù hợp để tìm hiểu thêm hoặc ôn luyện nâng cao. Chọn đúng chuyên đề liên quan tới bài học của mình.' }
      ]
    },
    {
      key: 'chuyen-de-bai-tap',
      match: function () {
        return location.pathname === '/search/label/cd-bt' || pageHasLabel('cd-bt');
      },
      steps: [
        { title: 'Mục Chuyên đề bài tập vật lí',
          text: 'Đây là kho bài tập tự luyện, trình bày theo từng dạng/chuyên đề kèm hướng dẫn hoặc lời giải — dùng để luyện thêm ngoài giờ, khác với mục Luyện tập trắc nghiệm (mục đó có chấm điểm và khoá bài chống gian lận).' }
      ]
    },
    {
      key: 'gdcp',
      // GDĐP: các nhãn dạng bg-gd-10-1, bg-gd-11-3, bg-gd-12-7...
      match: function () {
        return location.pathname.indexOf('/search/label/bg-gd-') === 0 || pageHasLabelPrefix('bg-gd-');
      },
      steps: [
        { title: 'Mục Giáo dục địa phương (GDĐP)',
          text: 'Nội dung GDĐP được chia theo từng khối lớp (10, 11, 12), mỗi khối có nhiều Chủ đề riêng (ví dụ Âm nhạc Khánh Hòa, Danh nhân Khánh Hòa...). Vào đúng lớp rồi chọn đúng Chủ đề đang học trên lớp.' }
      ]
    },
    {
      key: 'test-online',
      match: function () {
        return location.pathname === '/p/he-thong-kiem-tra-truc-tuyen-div.html';
      },
      steps: [
        { title: 'Hệ thống kiểm tra trực tuyến',
          text: 'Đây là nơi vào làm bài kiểm tra chính thức thầy giao (khác với mục Luyện tập tự do). Chọn đúng lớp/bài kiểm tra, đăng nhập đúng số điện thoại đã đăng ký, đọc kỹ quy chế trước khi bấm Bắt đầu.' },
        { title: 'Lưu ý khi làm bài kiểm tra',
          text: 'Trong lúc làm bài KHÔNG chuyển tab/cửa sổ khác, KHÔNG dán (paste) nội dung, KHÔNG mở DevTools — hệ thống ghi nhận vi phạm, đủ số lần quy định sẽ khoá bài và đồng bộ khoá trên mọi thiết bị.' }
      ]
    },
    {
      key: 'trang-chu',
      // Trang chủ blog: đường dẫn gốc, không có tiêu đề bài viết riêng.
      match: function () {
        return location.pathname === '/' || location.pathname === '';
      },
      steps: [
        { title: 'Chào mừng đến với blog Thầy Hùng!',
          text: 'Đây là trang chủ, nơi hiện các bài viết mới nhất. Dùng menu hoặc ô tìm kiếm phía trên để tìm đúng bài học/lớp của mình. Nếu thầy giao bài luyện tập, thường thầy sẽ gửi kèm đường link trực tiếp — bấm vào link đó là vào thẳng đúng bài, không cần tìm.' }
      ]
    }
    // -----------------------------------------------------------------------
    // TODO (anh Hùng tự thêm): các loại trang khác của blog, ví dụ trang
    // "Khoá học", trang "Kiểm tra miệng" (phòng thi), trang "Bảng vàng",
    // trang đăng ký... Copy 1 khối {key, match, steps} ở trên, sửa lại.
    // Gợi ý cách viết "match" cho 1 trang bất kỳ nếu không có dấu hiệu riêng:
    //   match: function () { return location.pathname.indexOf('/2025/08/khoa-hoc') === 0; }
    // hoặc theo tiêu đề trang:
    //   match: function () { return document.title.indexOf('Khoá học Vật lí') === 0; }
    // -----------------------------------------------------------------------
  ];

  // Hướng dẫn CHUNG khi không có mục nào ở trên khớp — luôn có để nút Trợ
  // giúp không bao giờ "im lặng" không phản hồi.
  var FALLBACK_GUIDE = {
    key: 'chung',
    match: function () { return true; },
    steps: [
      { title: 'Hướng dẫn sử dụng blog',
        text: 'Dùng menu hoặc ô tìm kiếm phía trên trang để tìm đúng bài học của lớp mình. Nếu cần hỗ trợ thêm, hãy liên hệ trực tiếp với thầy.' }
    ]
  };

  // =========================================================================
  // PHẦN LÕI — không cần sửa
  // =========================================================================
  function getStudentKey() {
    return localStorage.getItem('user_phone') || 'anonymous';
  }
  function seenKey(g) { return 'tg_guide_seen_' + g.key + '_' + getStudentKey(); }

  function findGuide() {
    for (var i = 0; i < GUIDES.length; i++) {
      try { if (GUIDES[i].match()) return GUIDES[i]; } catch (e) { /* trang không có phần tử này thì bỏ qua */ }
    }
    return FALLBACK_GUIDE;
  }

  var currentGuide = null;
  var currentStep = 0;

  var overlay = document.getElementById('tg-guide-overlay');
  var titleEl = document.getElementById('tg-guide-title');
  var textEl = document.getElementById('tg-guide-text');
  var dotsEl = document.getElementById('tg-guide-dots');
  var btnNext = document.getElementById('tg-btn-next');
  var btnPrev = document.getElementById('tg-btn-prev');
  var btnSkip = document.getElementById('tg-btn-skip');
  var fab = document.getElementById('tg-help-fab');

  function render() {
    var step = currentGuide.steps[currentStep];
    titleEl.textContent = step.title;
    textEl.textContent = step.text;
    dotsEl.innerHTML = '';
    currentGuide.steps.forEach(function (_, i) {
      var d = document.createElement('div');
      d.className = 'tg-dot' + (i === currentStep ? ' tg-active' : '');
      dotsEl.appendChild(d);
    });
    btnPrev.style.display = currentStep > 0 ? 'inline-block' : 'none';
    btnNext.textContent = currentStep === currentGuide.steps.length - 1 ? 'Đã hiểu ✓' : 'Tiếp theo ›';
  }

  function open(guide) {
    currentGuide = guide;
    currentStep = 0;
    render();
    overlay.classList.add('tg-open');
  }

  function close(markSeen) {
    overlay.classList.remove('tg-open');
    if (markSeen && currentGuide) {
      try { localStorage.setItem(seenKey(currentGuide), '1'); } catch (e) {}
    }
  }

  btnNext.addEventListener('click', function () {
    if (currentStep < currentGuide.steps.length - 1) {
      currentStep++;
      render();
    } else {
      close(true);
    }
  });
  btnPrev.addEventListener('click', function () {
    if (currentStep > 0) { currentStep--; render(); }
  });
  btnSkip.addEventListener('click', function () { close(true); });
  overlay.addEventListener('click', function (e) { if (e.target === overlay) close(true); });
  fab.addEventListener('click', function () { open(findGuide()); });

  document.addEventListener('DOMContentLoaded', function () {
    fab.classList.add('tg-pos-' + TG_POSITION); // [THÊM] áp vị trí theo TG_POSITION ở trên
    var g = findGuide();
    var already = false;
    try { already = !!localStorage.getItem(seenKey(g)); } catch (e) {}
    if (!already) open(g); // tự động hiện lần đầu học sinh vào loại trang này
  });
})();

