(function () {
  'use strict';
  // Danh sách id các "nút công cụ nổi" cần có nút (X) để ẩn đi khi soạn bài/làm việc.
  // Muốn áp dụng cho widget nổi nào khác, chỉ cần thêm id vào mảng này.
  // Lưu ý: KHÔNG ghi nhớ trạng thái ẩn — mỗi lần tải lại trang, các nút này
  // luôn hiện mặc định; người dùng tự bấm (X) để ẩn khi cần trong phiên đang xem.
  var TG_HIDE_TARGETS = ['coinDisplay', 'tg-help-fab'];

  function addCloseBadge(el) {
    if (!el || el.querySelector('.tg-close-badge')) return;
    var badge = document.createElement('span');
    badge.className = 'tg-close-badge';
    badge.title = 'Ẩn nút này';
    badge.setAttribute('aria-label', 'Ẩn nút này');
    badge.textContent = '\u00D7';
    badge.addEventListener('click', function (e) {
      e.stopPropagation();
      e.preventDefault();
      el.style.display = 'none';
    });
    el.appendChild(badge);
  }

  function initHideButtons() {
    TG_HIDE_TARGETS.forEach(function (id) {
      var el = document.getElementById(id);
      if (!el) return;
      addCloseBadge(el);
    });
  }

  var tgCloseStyle = document.createElement('style');
  tgCloseStyle.textContent =
    '.tg-close-badge{position:absolute;top:-6px;right:-6px;width:18px;height:18px;' +
    'background:#333;color:#fff;border-radius:50%;display:flex;align-items:center;' +
    'justify-content:center;font-size:12px;line-height:1;cursor:pointer;' +
    'z-index:2147483647;box-shadow:0 1px 4px rgba(0,0,0,.4);user-select:none;}' +
    '.tg-close-badge:hover{background:#e63946;}';
  document.head.appendChild(tgCloseStyle);

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initHideButtons);
  } else {
    initHideButtons();
  }
})();
