(function () {
  'use strict';
  if (window.top !== window.self) return;            // không chạy trong khung nhúng

  /* ===== CẤU HÌNH ===== */
  var FORUM_API   = 'https://script.google.com/macros/s/AKfycbzDPDKKNBDaNYEVAglkcWft0tDMAAwaBBkQgf1eAw-ozCppBRU9njp0I11DX2qhmUl_/exec';
  var ACTION      = 'getAllData'; // sau này có thể đổi thành 'getLatest' cho nhẹ (xem hướng dẫn)
  var LINK_MATCH  = 'dien-hoc-tap';   // đoạn địa chỉ của trang Diễn đàn
  var POLL_MS     = 90 * 1000;        // kiểm tra lại mỗi 90 giây khi đang mở tab
  var FIRST_DAYS  = 3;                // lần đầu ghé: tính bài trong 3 ngày gần đây
  var KEY_SEEN    = 'forumLastSeen';  // mốc thời gian đã xem diễn đàn
  var KEY_USER    = 'physicsForumUser'; // khóa mà diễn đàn dùng để lưu người đăng nhập

  var baseTitle = document.title, badge = null, li = null, link = null;

  function find() {
    link = document.querySelector('#main-nav a[href*="' + LINK_MATCH + '"]');
    if (!link) return false;
    li = link.closest('li');
    return true;
  }

  function getSeen() {
    try { return parseInt(localStorage.getItem(KEY_SEEN), 10) || 0; } catch (e) { return 0; }
  }
  function setSeen(t) {
    try { localStorage.setItem(KEY_SEEN, String(t)); } catch (e) {}
  }
  function myId() {
    try { var u = JSON.parse(localStorage.getItem(KEY_USER)); return u && u.id != null ? String(u.id) : null; }
    catch (e) { return null; }
  }
  function onForumPage() { return location.pathname.indexOf(LINK_MATCH) > -1; }

  function show(n) {
    if (!li) return;
    if (!badge) {
      badge = document.createElement('span');
      badge.className = 'forum-badge';
      li.appendChild(badge);
    }
    if (n > 0) {
      badge.textContent = n > 9 ? '9+' : String(n);
      badge.setAttribute('aria-label', n + ' bài mới trên Diễn đàn');
      badge.hidden = false;
      li.classList.add('forum-has-new');
      link.title = n + ' bài mới trên Diễn đàn';
      document.title = '(' + n + ') ' + baseTitle;
    } else {
      badge.hidden = true;
      li.classList.remove('forum-has-new');
      link.removeAttribute('title');
      document.title = baseTitle;
    }
  }

  function check() {
    if (document.hidden) return;
    var ctl = ('AbortController' in window) ? new AbortController() : null;
    var timer = ctl ? setTimeout(function () { ctl.abort(); }, 12000) : null;

    fetch(FORUM_API + '?action=' + ACTION + '&_=' + Date.now(), { cache: 'no-store', signal: ctl ? ctl.signal : undefined })
      .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
      .then(function (data) {
        var posts = (data && data.posts) || [];
        var times = posts.map(function (p) { return { t: new Date(p.timestamp).getTime(), a: String(p.authorId) }; })
                         .filter(function (x) { return !isNaN(x.t); });
        var newest = times.reduce(function (m, x) { return Math.max(m, x.t); }, 0);

        if (onForumPage()) {            // đang ở trang Diễn đàn = đã xem
          if (newest) setSeen(newest);
          show(0);
          return;
        }
        var seen = getSeen();
        if (!seen) seen = Date.now() - FIRST_DAYS * 86400000;   // lần đầu ghé
        var me = myId();
        var n = times.filter(function (x) { return x.t > seen && x.a !== me; }).length;
        show(n);
      })
      .catch(function () { /* mạng lỗi: im lặng, lần sau thử lại */ })
      .then(function () { if (timer) clearTimeout(timer); });
  }

  function start() {
    if (!find()) return;
    check();
    setInterval(check, POLL_MS);
    document.addEventListener('visibilitychange', function () { if (!document.hidden) check(); });
    window.addEventListener('focus', check);
    // Khi bấm vào "Diễn đàn": tắt chấm ngay, không chờ tải xong trang
    link.addEventListener('click', function () { show(0); });
    // Đồng bộ giữa nhiều tab: xem ở tab này thì tab kia cũng tắt chấm
    window.addEventListener('storage', function (e) { if (e.key === KEY_SEEN) check(); });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();
