     'Quyền của bạn: bạn có thể yêu cầu xem, sửa, xóa dữ liệu hoặc rút lại sự đồng ý bất kỳ lúc nào qua email pnhungc3nvt@gmail.com hoặc số điện thoại 0982493474. Người xây dựng trang sẽ phản hồi trong vòng 5 ngày làm việc. Nếu xảy ra sự cố lộ dữ liệu, người bị ảnh hưởng sẽ được thông báo.<br><br>' +
     'Xem chi tiết tại <a href="https://thayhungp.blogspot.com/p/chinh-sach-quyen-rieng-tu.html" target="_blank" rel="noopener">Chính sách quyền riêng tư</a>.'],
    ['7. Thay đổi và chấp thuận',
     'Người xây dựng trang có quyền sửa đổi tuyên bố này, thay đổi hoặc ngừng cung cấp nền tảng vào bất kỳ lúc nào. Bạn xác nhận đã đọc, hiểu và đồng ý với tuyên bố này bằng cách tích vào ô xác nhận khi sử dụng nền tảng. Nếu không đồng ý, vui lòng ngừng sử dụng. Không điều khoản nào ở đây loại trừ những trách nhiệm mà pháp luật không cho phép loại trừ.']
  ];

  /* ---------- GIAO DIỆN ---------- */
  var css =
    '#dc-ov{position:fixed;inset:0;z-index:2147483647;background:rgba(15,30,40,.78);display:none;align-items:center;justify-content:center;padding:14px;font-family:"Segoe UI",Tahoma,Geneva,Verdana,sans-serif}' +
    '#dc-ov.on{display:flex}' +
    '#dc-box{background:#fff;color:#333;width:100%;max-width:640px;max-height:92vh;display:flex;flex-direction:column;border-radius:14px;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.45)}' +
    '#dc-head{background:linear-gradient(135deg,#2c7873,#1e5f74);color:#fff;padding:16px 20px;font-size:18px;font-weight:700}' +
    '#dc-body{padding:16px 20px;overflow-y:auto;font-size:15px;line-height:1.6}' +
    '#dc-body ul{margin:0 0 12px 18px;padding:0}#dc-body li{margin-bottom:8px}' +
    '#dc-body details{border:1px solid #d5e3e6;border-radius:8px;padding:8px 12px;background:#f6fbfc}' +
    '#dc-body summary{cursor:pointer;font-weight:600;color:#1e5f74}' +
    '#dc-body h4{margin:12px 0 4px;color:#1e5f74;font-size:15px}#dc-body p{margin:0;font-size:14px}' +
    '#dc-foot{padding:14px 20px;border-top:1px solid #e3ecee;background:#fafcfc}' +
    '#dc-foot label{display:flex;gap:10px;align-items:flex-start;cursor:pointer;font-size:14px;margin-bottom:12px}' +
    '#dc-foot input{margin-top:4px;width:18px;height:18px;flex:none}' +
    '#dc-btns{display:flex;gap:10px;flex-wrap:wrap}' +
    '#dc-ok{flex:1;min-width:200px;padding:11px 16px;border:0;border-radius:8px;background:#2c7873;color:#fff;font-size:15px;font-weight:700;cursor:pointer}' +
    '#dc-ok:disabled{background:#a9c5c3;cursor:not-allowed}' +
    '#dc-bn{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(12px + env(safe-area-inset-bottom,0px));z-index:2147483646;width:calc(100% - 24px);max-width:720px;display:none;align-items:center;gap:10px;background:#1e5f74;color:#fff;padding:10px 12px 10px 14px;border-radius:10px;box-shadow:0 6px 24px rgba(0,0,0,.35);font:13.5px/1.45 "Segoe UI",Tahoma,sans-serif}' +
    '#dc-bn.on{display:flex}#dc-bn span{flex:1}' +
    '#dc-bn button{border:0;border-radius:6px;padding:6px 10px;cursor:pointer;font-size:13px}' +
    '#dc-bn-more{background:#ffd700;color:#333;font-weight:700;white-space:nowrap}#dc-bn-x{background:transparent;color:#fff;font-size:20px;line-height:1;padding:2px 8px}' +
    '#dc-no{padding:11px 16px;border:1px solid #c9d6d8;border-radius:8px;background:#fff;color:#555;font-size:14px;cursor:pointer}';

  var ov, built = false;

  function build() {
    if (built) return;
    built = true;
    var st = document.createElement('style');
    st.textContent = css;
    document.head.appendChild(st);

    var li = SHORT.map(function (t) { return '<li>' + t + '</li>'; }).join('');
    var full = FULL.map(function (s) { return '<h4>' + s[0] + '</h4><p>' + s[1] + '</p>'; }).join('');

    ov = document.createElement('div');
    ov.id = 'dc-ov';
    ov.setAttribute('role', 'dialog');
    ov.setAttribute('aria-modal', 'true');
    ov.setAttribute('aria-labelledby', 'dc-head');
    ov.innerHTML =
      '<div id="dc-box">' +
        '<div id="dc-head">⚠️ Lưu ý quan trọng trước khi sử dụng</div>' +
        '<div id="dc-body"><ul>' + li + '</ul>' +
        '<details><summary>Xem toàn văn tuyên bố miễn trừ trách nhiệm</summary>' + full + '</details></div>' +
        '<div id="dc-foot">' +
          '<label><input type="checkbox" id="dc-chk"><span>Tôi đã đọc, hiểu và <b>tự nguyện</b> sử dụng nền tảng (nếu dưới 18 tuổi, tôi đã được cha mẹ/người giám hộ đồng ý).</span></label>' +
          '<div id="dc-btns"><button type="button" id="dc-ok" disabled>Tôi đã hiểu, tiếp tục</button>' +
          '<button type="button" id="dc-no">Không đồng ý, rời trang</button></div>' +
        '</div>' +
      '</div>';
    document.body.appendChild(ov);

    var chk = ov.querySelector('#dc-chk'), ok = ov.querySelector('#dc-ok');
    chk.addEventListener('change', function () { ok.disabled = !chk.checked; });
    ok.addEventListener('click', function () { if (chk.checked) { markConfirmed(); close(); release(); } });
    ov.querySelector('#dc-no').addEventListener('click', function () { window.location.href = LEAVE_URL; });
  }

  var prevOverflow = '';
  function open() {
    build();
    if (ov.classList.contains('on')) return;
    prevOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    ov.classList.add('on');
    setTimeout(function () { var c = ov.querySelector('#dc-chk'); if (c) c.focus(); }, 0);
  }
  function close() {
    ov.classList.remove('on');
    document.body.style.overflow = prevOverflow;
  }

  /* ---------- DẢI NHẮC NHỎ (không chặn thao tác) ---------- */
  function showBanner() {
    var bn = document.createElement('div');
    bn.id = 'dc-bn';
    bn.setAttribute('role', 'note');
    bn.innerHTML = '<span>⚠️ Nền tảng do cá nhân tự xây dựng, học sinh <b>tự nguyện</b> tham gia; nhà trường và giáo viên bộ môn <b>không</b> chịu trách nhiệm. Nội dung, điểm và xu chỉ để tham khảo, luyện tập.</span>' +
      '<button type="button" id="dc-bn-more">Xem đầy đủ</button><button type="button" id="dc-bn-x" aria-label="Đóng">×</button>';
    document.body.appendChild(bn);
    // tạo kiểu nếu hộp thoại chưa được dựng
    build();
    bn.classList.add('on');
    bn.querySelector('#dc-bn-x').addEventListener('click', function () { bn.classList.remove('on'); });
    bn.querySelector('#dc-bn-more').addEventListener('click', function () { open(); });
  }

  /* ---------- BẮT TƯƠNG TÁC ĐẦU TIÊN CỦA MỖI TRANG ---------- */
  var EVENTS = ['pointerdown', 'mousedown', 'touchstart', 'click', 'keydown'];
  var pageDone = false;
  function release() { pageDone = true; EVENTS.forEach(function (n) { window.removeEventListener(n, guard, true); }); }
  function guard(e) {
    if (pageDone) { release(); return; }
    if (ov && ov.contains(e.target)) return;             // thao tác bên trong hộp thoại thì cho qua
    if (e.type === 'keydown' && (e.key === 'Tab' || e.key === 'Shift' || e.key === 'Escape')) return;
    if (confirmedRecently()) {                           // đã xác nhận đầy đủ gần đây: chỉ nhắc nhẹ, KHÔNG chặn
      release();
      showBanner();
      return;
    }
    e.stopImmediatePropagation();                        // chưa xác nhận: chặn thao tác đầu tiên, hiện hộp thoại đầy đủ
    if (e.type === 'click' || e.type === 'keydown') e.preventDefault();
    open();
  }
  EVENTS.forEach(function (n) { window.addEventListener(n, guard, { capture: true, passive: false }); });

  // Cho phép mở lại tuyên bố từ bất kỳ nút/liên kết nào, ví dụ ở chân trang:
  // <a href="javascript:openDisclaimer()">Miễn trừ trách nhiệm</a>
  window.openDisclaimer = function () { open(); };
})();
