(function () {
  'use strict';

  /* ---------- CẤU HÌNH (chỉnh ở đây) ---------- */
  var CFG = {
    REGISTER_URL: 'https://thayhungp.blogspot.com/p/ang-ki.html',
    PRESENCE_URL: 'https://script.google.com/macros/s/AKfycbzmgpdjkPR9S7sNR3ns-si--4ni0aFSO8jlvBDFEZi70rj_Cg51NdlhUJXbR9-R70RP/exec',
    BANNER_SNOOZE_H: 24,      // khách bấm "Đóng" thì ẩn thẻ chào bấy nhiêu giờ
    MODAL_SNOOZE_H: 24,       // hộp gợi ý hiện tối đa 1 lần / bấy nhiêu giờ
    CACHE_MEMBER_H: 24,       // nhớ kết quả "đã đăng ký" bấy nhiêu giờ (đỡ gọi máy chủ)
    CACHE_GUEST_MIN: 10,      // nhớ kết quả "chưa đăng ký" bấy nhiêu phút
    COUNT_FORUM_LOGIN: true,  // true: người đã đăng nhập Diễn đàn cũng tính là thành viên
    WELCOME_MEMBER: true,     // true: thành viên thấy lời chào ngắn (mỗi ngày một lần)
    SITE_NAME: 'Vật lí Thầy Hùng',
    ADMIN_NAMES: ['admin'],        // tên đăng nhập được coi là quản trị (để [] nếu chỉ muốn dùng nhận diện của Blogger)
    ADMIN_TITLE: 'Thầy Hùng',      // tên hiện trong lời chào dành cho quản trị
    // Liên kết nào chứa các từ khóa này sẽ hiện hộp gợi ý (khách vẫn vào được)
    MEMBER_LINKS: ['he-thong-kiem-tra-truc-tuyen', 'tra-cuu-iem']
  };

  var BENEFITS = [
    ['fa-coins', 'Lưu điểm và xu tích lũy, dùng để đổi ưu đãi'],
    ['fa-pencil-alt', 'Bài kiểm tra được ghi nhận đúng kết quả của bạn'],
    ['fa-user-check', 'Hiển thị đúng tên của bạn thay vì "Khách"'],
    ['fa-unlock-alt', 'Kích hoạt khóa học và tài liệu đã đăng ký'],
    ['fa-chart-line', 'Theo dõi tiến độ học tập của mình']
  ];

  // Lời nhắn dành cho quản trị (xoay theo ngày)
  var ADMIN_LINES = [
    'Chúc Thầy một ngày làm việc nhẹ nhàng và hiệu quả.',
    'Chế độ quản trị đang bật: Thầy sẽ không thấy lời mời đăng ký dành cho khách.',
    'Chúc Thầy một buổi dạy thật vui. Các em đang chờ bài mới của Thầy.'
  ];

  // Lời nhắn cho thành viên (xoay theo ngày)
  var MEMBER_LINES = [
    'Chúc em một buổi học hiệu quả và nhiều điều thú vị.',
    'Mỗi câu hỏi "tại sao?" hôm nay là một bước tiến mới. Học vui nhé!',
    'Cứ từ từ, chắc chắn: kiến thức Vật lí được xây từng viên gạch một.',
    'Chúc em hôm nay học nhẹ nhàng mà vẫn tiến bộ rõ rệt.',
    'Có thắc mắc cứ hỏi, đừng ngại. Thầy và các bạn luôn ở đây.'
  ];

  /* ---------- TIỆN ÍCH ---------- */
  function ls(k) { try { return window.localStorage.getItem(k); } catch (e) { return null; } }
  function lsSet(k, v) { try { window.localStorage.setItem(k, v); } catch (e) {} }
  function snoozed(key, hours) {
    var t = parseInt(ls(key) || '0', 10);
    return t > 0 && (Date.now() - t) < hours * 3600000;
  }
  function track(name, where) {
    try { if (typeof window.gtag === 'function') window.gtag('event', name, { location: where }); } catch (e) {}
  }
  function debounce(fn, ms) {
    var t; return function () { clearTimeout(t); t = setTimeout(fn, ms); };
  }
  var ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return ESC[c]; }); }
  function todayKey() {
    var n = new Date();
    return n.getFullYear() + '-' + (n.getMonth() + 1) + '-' + n.getDate();
  }
  function dayIndex() { return Math.floor(Date.now() / 86400000); }
  function salutation() {
    var h = new Date().getHours();
    if (h < 11) return 'Chào buổi sáng';
    if (h < 13) return 'Chào buổi trưa';
    if (h < 18) return 'Chào buổi chiều';
    return 'Chào buổi tối';
  }
  function cleanName(n) {
    var s = String(n || '').replace(/\s*\(.*\)\s*$/, '').trim();
    return s.length > 30 ? s.slice(0, 30) : s;
  }
  function getName() {
    var a = window.physicsApp && window.physicsApp.userName;
    if (a && a !== 'Khách') return cleanName(a);
    var u = ls('userDisplayName');
    if (u && u !== 'Khách') return cleanName(u);
    try {
      var f = JSON.parse(ls('physicsForumUser'));
      if (f) { var n = f.displayName || f.username || f.name; if (n) return cleanName(n); }
    } catch (e) {}
    return '';
  }

  /* ---------- NHẬN DIỆN QUẢN TRỊ ---------- */
  // (a) Blogger chỉ hiện nút bút chì (.item-control) với người đang đăng nhập đúng tài khoản chủ blog.
  function bloggerAdmin() {
    try {
      var els = document.querySelectorAll('.item-control.blog-admin');
      for (var i = 0; i < els.length; i++) {
        if (window.getComputedStyle(els[i]).display !== 'none') return true;
      }
    } catch (e) {}
    return false;
  }
  // (b) Đã bấm "Đăng nhập" với tên nằm trong CFG.ADMIN_NAMES (chỉ để đổi lời chào, không cấp quyền gì)
  function savedAdmin() { return ls('rg_admin') === '1'; }
  function isAdmin() { return savedAdmin() || bloggerAdmin(); }
  var loginForm = document.getElementById('login-form');
  if (loginForm) loginForm.addEventListener('submit', function () {
    var u = document.getElementById('username');
    var v = u ? String(u.value || '').trim().toLowerCase() : '';
    var yes = CFG.ADMIN_NAMES.some(function (n) { return String(n).toLowerCase() === v; });
    try { if (yes) window.localStorage.setItem('rg_admin', '1'); else window.localStorage.removeItem('rg_admin'); } catch (e) {}
    try { localStorage.removeItem('rg_welcome_admin_day'); } catch (e) {}
    setTimeout(function () { removeMemberWelcome(); evaluate(); }, 800);
  });

  /* ---------- XÁC ĐỊNH TRẠNG THÁI: member | guest | unknown ---------- */
  function getPhone() {
    var p = (ls('userPhone') || '').replace(/[\s.\-]/g, '');
    return /^(\+?84|0)?\d{9,10}$/.test(p) ? p : '';
  }
  function hasForumUser() {
    try { var u = JSON.parse(ls('physicsForumUser')); return !!(u && u.id != null); } catch (e) { return false; }
  }
  function getStatus() {
    if (isAdmin()) return Promise.resolve('member');
    if (CFG.COUNT_FORUM_LOGIN && hasForumUser()) return Promise.resolve('member');
    var phone = getPhone();
    if (!phone) return Promise.resolve('guest');

    var c = null;
    try { c = JSON.parse(ls('rg_cache') || 'null'); } catch (e) {}
    if (c && c.phone === phone) {
      var age = Date.now() - c.ts;
      if (c.reg && age < CFG.CACHE_MEMBER_H * 3600000) return Promise.resolve('member');
      if (!c.reg && age < CFG.CACHE_GUEST_MIN * 60000) return Promise.resolve('guest');
    }
    var base = (window.physicsApp && window.physicsApp.config && window.physicsApp.config.PRESENCE_URL) || CFG.PRESENCE_URL;
    var url = base + '?action=presence&phone=' + encodeURIComponent(phone) +
              '&page=' + encodeURIComponent(location.pathname);
    return fetch(url)
      .then(function (r) { return r.json(); })
      .then(function (j) {
        var info = j && j.success && j.data;
        var reg = !!(info && info.registered);
        lsSet('rg_cache', JSON.stringify({ phone: phone, reg: reg, ts: Date.now() }));
        return reg ? 'member' : 'guest';
      })
      .catch(function () { return 'unknown'; });   // lỗi mạng: KHÔNG nhắc, tránh làm phiền nhầm
  }

  /* ---------- VỊ TRÍ ĐẶT THẺ ---------- */
  function mount(el) {
    var slot = document.getElementById('site-greeting');
    if (slot) { slot.appendChild(el); return; }
    var nav = document.getElementById('main-nav');
    if (nav && nav.parentNode) { nav.parentNode.insertBefore(el, nav.nextSibling); return; }
    document.body.insertBefore(el, document.body.firstChild);
  }

  /* ---------- 1) THẺ CHÀO MỪNG DÀNH CHO KHÁCH ---------- */
  function showBanner() {
    if (document.getElementById('rg-banner') || snoozed('rg_banner_ts', CFG.BANNER_SNOOZE_H)) return;
    var b = document.createElement('div');
    b.id = 'rg-banner';
    b.setAttribute('role', 'region');
    b.setAttribute('aria-label', 'Lời chào và gợi ý đăng ký');
    b.innerHTML =
      '<div class="rg-g-icon" aria-hidden="true"><i class="fas fa-atom"></i></div>' +
      '<div class="rg-g-text">' +
        '<p class="rg-g-title">Chào mừng bạn đến với ' + esc(CFG.SITE_NAME) + '</p>' +
        '<p class="rg-g-sub">Ở đây mọi hiện tượng đều có lời giải thích, và câu hỏi "tại sao?" luôn được trân trọng. ' +
        'Chúc bạn một buổi học thật nhiều hứng thú.</p>' +
        '<p class="rg-g-reg"><i class="fas fa-gift" aria-hidden="true"></i>' +
        'Đăng ký thành viên để lưu điểm, xu và theo dõi tiến độ học tập của mình. Việc này hoàn toàn tự nguyện.</p>' +
      '</div>' +
      '<div class="rg-b-actions">' +
        '<a class="rg-btn rg-btn-primary" data-rg="banner" href="' + esc(CFG.REGISTER_URL) + '">Đăng ký</a>' +
        '<button type="button" class="rg-btn rg-btn-ghost" id="rg-later">Đóng</button>' +
      '</div>';
    mount(b);
    track('register_prompt_view', 'banner');
    document.getElementById('rg-later').addEventListener('click', function () {
      lsSet('rg_banner_ts', String(Date.now()));
      removeBanner();
      track('register_prompt_later', 'banner');
    });
  }
  function removeBanner() {
    var b = document.getElementById('rg-banner');
    if (b && b.parentNode) b.parentNode.removeChild(b);
  }

  /* ---------- 1b) LỜI CHÀO NGẮN CHO THÀNH VIÊN (mỗi ngày một lần) ---------- */
  function showMemberWelcome() {
    if (!CFG.WELCOME_MEMBER || document.getElementById('rg-welcome')) return;
    var admin = isAdmin();
    var gateKey = admin ? 'rg_welcome_admin_day' : 'rg_welcome_day';
    if (ls(gateKey) === todayKey()) return;
    lsSet(gateKey, todayKey());
    var name = admin ? CFG.ADMIN_TITLE : getName();
    var lines = admin ? ADMIN_LINES : MEMBER_LINES;
    var w = document.createElement('div');
    w.id = 'rg-welcome';
    w.setAttribute('role', 'region');
    w.setAttribute('aria-label', 'Lời chào');
    w.innerHTML =
      '<div class="rg-g-icon" aria-hidden="true"><i class="fas fa-atom"></i></div>' +
      '<div class="rg-g-text">' +
        '<p class="rg-g-title">' + salutation() + (name ? ', ' + esc(name) : '') + '!</p>' +
        '<p class="rg-g-sub">' + esc(lines[dayIndex() % lines.length]) + '</p>' +
      '</div>' +
      '<button type="button" class="rg-x-top" aria-label="Đóng lời chào">&times;</button>';
    mount(w);
    w.querySelector('.rg-x-top').addEventListener('click', removeMemberWelcome);
  }
  function removeMemberWelcome() {
    var w = document.getElementById('rg-welcome');
    if (w && w.parentNode) w.parentNode.removeChild(w);
  }

  /* ---------- 2) NÚT "ĐĂNG KÝ" Ở HEADER + GỢI Ý Ở Ô XU ---------- */
  function markHeader(on) {
    var a = document.querySelector('#login-form a[href*="ang-ki"]');
    if (a) a.classList.toggle('rg-pulse', on);
    var coin = document.getElementById('coinDisplay');
    if (coin) {
      if (on) coin.setAttribute('title', 'Đăng ký để xu và điểm của bạn được lưu lại');
      else coin.removeAttribute('title');
    }
  }

  /* ---------- 3) HỘP GỢI Ý NHẸ KHI BẤM MỤC CẦN TÀI KHOẢN ---------- */
  function openModal(href, label) {
    if (document.getElementById('rg-modal')) return;
    lsSet('rg_modal_ts', String(Date.now()));
    var prev = document.activeElement;
    var items = BENEFITS.map(function (b) {
      return '<li><i class="fas ' + b[0] + '"></i><span>' + b[1] + '</span></li>';
    }).join('');
    var m = document.createElement('div');
    m.id = 'rg-modal';
    m.innerHTML =
      '<div class="rg-card" role="dialog" aria-modal="true" aria-labelledby="rg-title">' +
      '<button type="button" class="rg-x" aria-label="Đóng">&times;</button>' +
      '<h3 id="rg-title">Đăng ký để dùng đầy đủ tính năng</h3>' +
      '<p>Mục "' + esc(label || 'này') + '" hoạt động tốt nhất khi bạn có tài khoản:</p>' +
      '<ul>' + items + '</ul>' +
      '<div class="rg-actions">' +
      '<a class="rg-btn rg-btn-primary" data-rg="modal" href="' + esc(CFG.REGISTER_URL) + '">Đăng ký ngay</a>' +
      '<button type="button" class="rg-btn rg-btn-ghost rg-dark" id="rg-go">Tiếp tục như khách</button></div>' +
      '<p class="rg-note">Việc đăng ký là tự nguyện, bạn có thể bỏ qua.</p></div>';
    document.body.appendChild(m);
    track('register_prompt_view', 'modal');

    function close() {
      document.removeEventListener('keydown', onKey, true);
      if (m.parentNode) m.parentNode.removeChild(m);
      if (prev && prev.focus) { try { prev.focus(); } catch (e) {} }
    }
    function onKey(e) { if (e.key === 'Escape') { e.stopPropagation(); close(); } }
    document.addEventListener('keydown', onKey, true);
    m.addEventListener('click', function (e) { if (e.target === m) close(); });
    m.querySelector('.rg-x').addEventListener('click', close);
    document.getElementById('rg-go').addEventListener('click', function () {
      track('register_prompt_continue_guest', 'modal');
      window.location.href = href;
    });
    var first = m.querySelector('.rg-btn-primary');
    if (first) first.focus();
  }

  var state = 'unknown';
  document.addEventListener('click', function (e) {
    var el = e.target;
    var tagged = el && el.closest ? el.closest('[data-rg]') : null;
    if (tagged) track('register_prompt_click', tagged.getAttribute('data-rg'));

    if (state !== 'guest') return;
    var a = el && el.closest ? el.closest('a[href]') : null;
    if (!a || a.closest('#rg-banner') || a.closest('#rg-modal')) return;
    if (e.defaultPrevented || e.button !== 0 || e.ctrlKey || e.metaKey || e.shiftKey || a.target === '_blank') return;
    var h = a.getAttribute('href') || '';
    var hit = CFG.MEMBER_LINKS.some(function (k) { return h.indexOf(k) > -1; });
    if (!hit || snoozed('rg_modal_ts', CFG.MODAL_SNOOZE_H)) return;
    e.preventDefault();
    openModal(a.href, (a.textContent || '').trim());
  });

  /* ---------- ĐIỀU PHỐI ---------- */
  function evaluate() {
    getStatus().then(function (s) {
      if (s === 'unknown') return;
      state = s;
      if (s === 'guest') {
        markHeader(true); removeMemberWelcome(); showBanner();
      } else {
        markHeader(false); removeBanner(); showMemberWelcome();
      }
    });
  }
  var evaluateSoon = debounce(evaluate, 1800);

  setTimeout(evaluate, 1500);
  document.addEventListener('physicsAppReady', function () { setTimeout(evaluate, 600); });
  var phoneInput = document.getElementById('userPhone');
  if (phoneInput) phoneInput.addEventListener('input', evaluateSoon);
  window.addEventListener('storage', evaluateSoon);
})();
