  ];
  var ADMIN_FACT = 'Hôm nay Trái Đất đã đưa Thầy đi thêm một vòng quanh Mặt Trời: khoảng 940 triệu km, với tốc độ gần 30 km/s.';
  var FACT = 'Hôm nay Trái Đất đã đưa em đi thêm một vòng quanh Mặt Trời: khoảng 940 triệu km, với tốc độ gần 30 km/s.';

  /* ---------- TIỆN ÍCH ---------- */
  function ls(k) { try { return window.localStorage.getItem(k); } catch (e) { return null; } }
  function lsSet(k, v) { try { window.localStorage.setItem(k, v); } catch (e) {} }
  function lsDel(k) { try { window.localStorage.removeItem(k); } catch (e) {} }
  function pad(n) { return n < 10 ? '0' + n : String(n); }
  function dim(m, y) { return new Date(y, m, 0).getDate(); }
  function reduced() { return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); }
  function track(name) { try { if (typeof window.gtag === 'function') window.gtag('event', name, { location: 'birthday' }); } catch (e) {} }
  function todayKey() { var n = new Date(); return n.getFullYear() + '-' + pad(n.getMonth() + 1) + '-' + pad(n.getDate()); }

  // Bản sao ngày sinh trên máy, chỉ để điền sẵn vào hộp nhập (nguồn chính nằm trên máy chủ)
  function getBd() {
    var m = /^(\d{2})-(\d{2})$/.exec(ls('bd_md') || '');
    return m ? { m: +m[1], d: +m[2] } : null;
  }
  function cleanName(n) { return String(n || '').replace(/\s*\(.*\)\s*$/, '').trim(); }
  function defaultName() {
    var n = ls('bd_name'); if (n) return n;
    var a = window.physicsApp && window.physicsApp.userName;
    if (a && a !== 'Khách') return cleanName(a);
    var u = ls('userDisplayName');
    if (u && u !== 'Khách') return cleanName(u);
    return '';
  }
  /* ---------- QUẢN TRỊ ---------- */
  function isAdminBd() {
    if (ls('rg_admin') === '1') return true;
    try {
      var els = document.querySelectorAll('.item-control.blog-admin');
      for (var i = 0; i < els.length; i++) if (window.getComputedStyle(els[i]).display !== 'none') return true;
    } catch (e) {}
    return false;
  }
  // Trả về số ngày muộn (0 = đúng hôm nay) nếu đang trong khoảng chúc mừng, ngược lại -1
  function adminLate() {
    var m = /^(\d{2})-(\d{2})$/.exec(CFG.ADMIN_BD || '');
    if (!m) return -1;
    var n = new Date(), t0 = new Date(n.getFullYear(), n.getMonth(), n.getDate());
    var b = new Date(n.getFullYear(), +m[1] - 1, +m[2]);
    var diff = Math.round((t0 - b) / 86400000);
    return (diff >= 0 && diff <= CFG.LATE_DAYS) ? diff : -1;
  }
  function isMember() {
    try { var c = JSON.parse(ls('rg_cache') || 'null'); if (c && c.reg) return true; } catch (e) {}
    try { var u = JSON.parse(ls('physicsForumUser')); if (u && u.id != null) return true; } catch (e) {}
    return false;
  }
  function pick(name, year) {
    var h = 0, s = name + year;
    for (var i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
    return WISHES[h % WISHES.length];
  }

  /* ---------- SỐ ĐIỆN THOẠI + MÃ THIẾT BỊ + GỌI MÁY CHỦ ---------- */
  function normPhone(v) {
    v = String(v || '').replace(/[\s.\-()]/g, '');
    if (/^\+?84/.test(v)) v = '0' + v.replace(/^\+?84/, '');
    return /^0[0-9]{9}$/.test(v) ? v : '';
  }
  // Tìm số điện thoại đã biết của thành viên (thử vài nơi blog thường lưu), cuối cùng là số em đã nhập ở đây
  function getPhone() {
    var cands = [], c;
    try { c = JSON.parse(ls('rg_cache') || 'null'); if (c) cands.push(c.phone, c.sdt); } catch (e) {}
    try { c = JSON.parse(ls('physicsForumUser') || 'null'); if (c) cands.push(c.phone, c.sdt); } catch (e) {}
    cands.push(ls('userPhone'), ls('phone'), ls('bd_phone'));
    for (var i = 0; i < cands.length; i++) { var p = normPhone(cands[i]); if (p) return p; }
    return '';
  }
  function getTok() {
    var t = ls('bd_tok');
    if (/^[A-Za-z0-9]{32}$/.test(t || '')) return t;
    var ch = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', a = [], s = '', i;
    try { a = window.crypto.getRandomValues(new Uint8Array(32)); } catch (e) { for (i = 0; i < 32; i++) a[i] = Math.floor(Math.random() * 256); }
    for (i = 0; i < 32; i++) s += ch.charAt(a[i] % ch.length);
    lsSet('bd_tok', s);
    return s;
  }
  // Trả về Promise: data nếu thành công, ném lỗi có message nếu máy chủ từ chối
  function api(params) {
    var q = [];
    for (var k in params) if (Object.prototype.hasOwnProperty.call(params, k)) q.push(encodeURIComponent(k) + '=' + encodeURIComponent(params[k]));
    return window.fetch(CFG.API + '?' + q.join('&')).then(function (r) { return r.json(); }).then(function (j) {
      if (j && j.success) return j.data;
      throw new Error((j && j.message) || 'Máy chủ không phản hồi đúng.');
    });
  }

  /* ---------- PHÁO GIẤY ---------- */
  function confetti(count, origin, ms) {
    if (reduced()) return;
    var cv = document.createElement('canvas');
    cv.style.cssText = 'position:fixed;left:0;top:0;width:100%;height:100%;z-index:99996;pointer-events:none';
    cv.width = window.innerWidth; cv.height = window.innerHeight;
    var c = cv.getContext ? cv.getContext('2d') : null;
    if (!c) return;
    document.body.appendChild(cv);
    var cols = ['#ffd700', '#ff6a00', '#ff8fab', '#5dd6c4', '#7aa7ff', '#ffffff'], P = [], i;
    for (i = 0; i < count; i++) {
      P.push({
        x: origin ? origin.x : Math.random() * cv.width,
        y: origin ? origin.y : -10 - Math.random() * cv.height * 0.3,
        vx: (Math.random() - 0.5) * (origin ? 14 : 5),
        vy: origin ? -(6 + Math.random() * 10) : 2 + Math.random() * 3,
        w: 6 + Math.random() * 6, h: 8 + Math.random() * 8,
        r: Math.random() * 6.28, vr: (Math.random() - 0.5) * 0.3, c: cols[i % cols.length]
      });
    }
    var t0 = Date.now();
    (function frame() {
      var el = Date.now() - t0;
      c.clearRect(0, 0, cv.width, cv.height);
      for (var k = 0; k < P.length; k++) {
        var p = P[k];
        p.vy += 0.18; p.vx *= 0.995; p.x += p.vx; p.y += p.vy; p.r += p.vr;
        c.save(); c.translate(p.x, p.y); c.rotate(p.r);
        c.globalAlpha = Math.max(0, Math.min(1, (ms - el) / 800));
        c.fillStyle = p.c; c.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
        c.restore();
      }
      if (el < ms) window.requestAnimationFrame(frame);
      else if (cv.parentNode) cv.parentNode.removeChild(cv);
    })();
  }

  /* ---------- BÁNH KEM (SVG) ---------- */
  var CAKE_SVG =
    '<svg class="bd-cake" viewBox="0 0 200 170" role="img" aria-label="Bánh kem sinh nhật có ba ngọn nến">' +
