    '</svg>';

  /* ---------- LƯU THẺ THÀNH ẢNH ---------- */
  function rr(g, x, y, w, h, r) {
    g.beginPath(); g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r);
    g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath();
  }
  function wrap(g, text, x, y, maxW, lh) {
    var words = text.split(' '), line = '';
    for (var i = 0; i < words.length; i++) {
      var t = line ? line + ' ' + words[i] : words[i];
      if (g.measureText(t).width > maxW && line) { g.fillText(line, x, y); line = words[i]; y += lh; }
      else line = t;
    }
    g.fillText(line, x, y);
    return y + lh;
  }
  function drawPNG(titleText, name, wish) {
    var cv = document.createElement('canvas'); cv.width = 1080; cv.height = 1350;
    var g = cv.getContext ? cv.getContext('2d') : null;
    if (!g) return null;
    var bg = g.createLinearGradient(0, 0, 1080, 1350);
    bg.addColorStop(0, '#1e5f74'); bg.addColorStop(0.6, '#2c7873'); bg.addColorStop(1, '#3b9a93');
    g.fillStyle = bg; g.fillRect(0, 0, 1080, 1350);
    var seed = 7, cols = ['#ffd700', '#ff6a00', '#ff8fab', '#5dd6c4', '#7aa7ff', '#ffffff'];
    function rnd() { seed = (seed * 16807) % 2147483647; return seed / 2147483647; }
    g.globalAlpha = 0.5;
    for (var i = 0; i < 80; i++) {
      g.save(); g.translate(rnd() * 1080, rnd() * 1350); g.rotate(rnd() * 6);
      g.fillStyle = cols[i % cols.length]; g.fillRect(-7, -10, 14, 20); g.restore();
    }
    g.globalAlpha = 1;
    g.strokeStyle = '#ffd700'; g.lineWidth = 8; rr(g, 40, 40, 1000, 1270, 40); g.stroke();
    g.save(); g.translate(260, 90); g.scale(2.8, 2.8);
    g.fillStyle = '#e9eef0'; g.beginPath(); g.ellipse(100, 152, 88, 10, 0, 0, 6.2832); g.fill();
    g.fillStyle = '#ff8fab'; rr(g, 30, 100, 140, 50, 8); g.fill();
    g.fillStyle = '#ffd166'; rr(g, 50, 68, 100, 38, 8); g.fill();
    g.fillStyle = '#ffffff'; rr(g, 70, 42, 60, 32, 8); g.fill();
    var cc = ['#5dd6c4', '#7aa7ff', '#ff6a00'];
    for (var k = 0; k < 3; k++) {
      var cx = 88.5 + k * 12;
      g.fillStyle = cc[k]; rr(g, cx - 2.5, 22, 5, 22, 2); g.fill();
      g.fillStyle = '#ffd700'; g.beginPath(); g.moveTo(cx, 20); g.quadraticCurveTo(cx - 6, 12, cx, 6); g.quadraticCurveTo(cx + 6, 12, cx, 20); g.fill();
    }
    g.restore();
    g.textAlign = 'center';
    g.fillStyle = '#ffffff'; g.font = '500 52px "Segoe UI",Arial,sans-serif';
    g.fillText(titleText, 540, 650);
    var size = 120; g.font = '700 ' + size + 'px "Segoe UI",Arial,sans-serif';
    while (g.measureText(name).width > 900 && size > 40) { size -= 4; g.font = '700 ' + size + 'px "Segoe UI",Arial,sans-serif'; }
    g.fillStyle = '#ffd700'; g.fillText(name, 540, 770);
    g.fillStyle = '#ffffff'; g.font = '400 38px "Segoe UI",Arial,sans-serif';
    var y = wrap(g, wish, 540, 870, 880, 52);
    g.font = 'italic 400 30px "Segoe UI",Arial,sans-serif'; g.fillStyle = 'rgba(255,255,255,.85)';
    wrap(g, FACT, 540, y + 30, 880, 42);
    g.font = '600 30px "Segoe UI",Arial,sans-serif'; g.fillStyle = '#ffd700';
    g.fillText(CFG.TEACHER + ' · Vật lí online', 540, 1262);
    g.font = '400 24px "Segoe UI",Arial,sans-serif'; g.fillStyle = 'rgba(255,255,255,.8)';
    g.fillText(CFG.SITE, 540, 1296);
    return cv;
  }
  function savePNG(titleText, name, wish) {
    var cv = drawPNG(titleText, name, wish);
    if (!cv || !cv.toBlob) return;
    cv.toBlob(function (b) {
      if (!b) return;
      try {
        var f = new File([b], 'the-sinh-nhat.png', { type: 'image/png' });
        if (navigator.canShare && navigator.canShare({ files: [f] })) {
          navigator.share({ files: [f], title: 'Thẻ sinh nhật' }).catch(function () {});
          return;
        }
      } catch (e) {}
      var a = document.createElement('a');
      a.href = URL.createObjectURL(b); a.download = 'the-sinh-nhat.png';
      document.body.appendChild(a); a.click();
      setTimeout(function () { URL.revokeObjectURL(a.href); if (a.parentNode) a.parentNode.removeChild(a); }, 1000);
    }, 'image/png');
  }

  /* ---------- KHUNG HỘP THOẠI CHUNG ---------- */
  function openOverlay(innerHtml, cardClass, onClose) {
    var prev = document.activeElement;
    var ov = document.createElement('div'); ov.id = 'bd-overlay';
    ov.innerHTML = '<div class="bd-card ' + (cardClass || '') + '" role="dialog" aria-modal="true">' +
      '<button type="button" class="bd-x" aria-label="Đóng">&times;</button>' + innerHtml + '</div>';
    document.body.appendChild(ov);
    function close() {
      document.removeEventListener('keydown', onKey, true);
      if (ov.parentNode) ov.parentNode.removeChild(ov);
      if (prev && prev.focus) { try { prev.focus(); } catch (e) {} }
      if (onClose) onClose();
    }
    function onKey(e) { if (e.key === 'Escape') { e.stopPropagation(); close(); } }
    document.addEventListener('keydown', onKey, true);
    ov.addEventListener('click', function (e) { if (e.target === ov) close(); });
    ov.querySelector('.bd-x').addEventListener('click', close);
    return { el: ov, close: close };
  }

  /* ---------- THẺ CHÚC MỪNG ---------- */
  function openCard(o) {
    if (document.getElementById('bd-overlay')) return;
    var name = o.name || 'bạn';
    var wish = o.admin ? ADMIN_WISHES[o.year % ADMIN_WISHES.length] : pick(name, o.year);
    var titleText = o.late > 0 ? 'Chúc mừng sinh nhật muộn' : 'Chúc mừng sinh nhật';
    var guestHtml = (o.admin || isMember()) ? '' :
      '<p class="bd-guest">Em chưa đăng ký thành viên. <a href="' + CFG.REGISTER_URL + '" data-bd="register">Đăng ký</a> (tự nguyện) để lưu điểm, xu và dùng đầy đủ tính năng của trang.</p>';
    var box = openOverlay(
      '<span class="bd-ribbon"></span>' + CAKE_SVG +
      '<h2><span class="bd-t"></span><span class="bd-name"></span></h2>' +
      '<p class="bd-wish"></p>' +
      '<p class="bd-fact"><i class="fas fa-globe-asia" aria-hidden="true"></i><span></span></p>' +
      '<p class="bd-after" hidden>Điều ước đã bay đi rồi. Giờ thì cùng bắt tay vào thực hiện nhé!</p>' +
      '<div class="bd-actions"><button type="button" class="bd-btn bd-gold" id="bd-blow">Thổi nến</button>' +
      '<button type="button" class="bd-btn" id="bd-save">Lưu thẻ</button></div>' + guestHtml, '');
    var el = box.el;
    el.querySelector('.bd-card').setAttribute('aria-label', titleText);
    el.querySelector('.bd-ribbon').textContent = o.admin ? 'Vật lí online gửi tặng Thầy' : CFG.TEACHER + ' gửi tặng em';
    el.querySelector('.bd-t').textContent = titleText + ',';
    el.querySelector('.bd-name').textContent = name + '!';
    el.querySelector('.bd-wish').textContent = wish;
    el.querySelector('.bd-fact span').textContent = o.admin ? ADMIN_FACT : FACT;
    if (o.admin) el.querySelector('.bd-after').textContent = 'Điều ước đã bay đi rồi. Chúc Thầy một tuổi mới thật nhiều niềm vui!';
    if (!o.preview) lsSet((o.admin ? 'bd_admin_shown_' : 'bd_shown_') + o.year, '1');
    track('birthday_card_view');
    confetti(150, null, 5000);
    var blown = false;
    document.getElementById('bd-blow').addEventListener('click', function () {
      if (blown) return; blown = true;
      el.querySelector('.bd-cake').classList.add('bd-out');
      el.querySelector('.bd-after').hidden = false;
      this.textContent = 'Đã thổi nến'; this.disabled = true;
      var r = this.getBoundingClientRect();
      confetti(120, { x: r.left + r.width / 2, y: r.top }, 3500);
      track('birthday_blow');
    });
    document.getElementById('bd-save').addEventListener('click', function () {
      savePNG(titleText, name + '!', wish); track('birthday_save');
    });
    var reg = el.querySelector('[data-bd="register"]');
    if (reg) reg.addEventListener('click', function () { track('birthday_register_click'); });
    var b = document.getElementById('bd-blow'); if (b) b.focus();
  }

  /* ---------- HỘP NHẬP NGÀY SINH (lưu lên máy chủ) ---------- */
  function openSetup() {
    if (document.getElementById('bd-overlay')) return;
    var bd = getBd(), phone = getPhone(), i, dOpts = '', mOpts = '';
    for (i = 1; i <= 31; i++) dOpts += '<option value="' + i + '"' + (bd && bd.d === i ? ' selected' : '') + '>' + i + '</option>';
    for (i = 1; i <= 12; i++) mOpts += '<option value="' + i + '"' + (bd && bd.m === i ? ' selected' : '') + '>Tháng ' + i + '</option>';
    var box = openOverlay(
      '<h3>Thầy muốn chúc mừng sinh nhật em</h3>' +
      '<p>Chọn ngày và tháng sinh (không cần năm). Thầy chỉ lưu ngày, tháng và cách em muốn được gọi, dùng để gửi lời chúc. Em có thể xóa bất cứ lúc nào.</p>' +
      (phone ? '' : '<label for="bd-in-phone">Số điện thoại em đã đăng ký thành viên</label>' +
        '<input id="bd-in-phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="0912345678" style="margin-bottom:10px">') +
      '<label for="bd-in-name">Em muốn thầy gọi em là</label>' +
      '<input id="bd-in-name" type="text" maxlength="24" autocomplete="off" style="margin-bottom:10px">' +
      '<div class="bd-row"><div><label for="bd-in-d">Ngày</label><select id="bd-in-d">' +
      (bd ? '' : '<option value="" selected>Chọn</option>') + dOpts + '</select></div>' +
      '<div><label for="bd-in-m">Tháng</label><select id="bd-in-m">' +
      (bd ? '' : '<option value="" selected>Chọn</option>') + mOpts + '</select></div></div>' +
      '<label style="display:flex;gap:8px;align-items:flex-start;margin:10px 0;font-size:.9em"><input id="bd-in-ok" type="checkbox" style="margin-top:3px">' +
      '<span>Em đồng ý để thầy lưu thông tin này (học sinh dưới 18 tuổi cần có sự đồng ý của cha/mẹ).</span></label>' +
      '<p class="bd-err" role="alert"></p>' +
      '<div class="bd-actions" style="justify-content:flex-start"><button type="button" class="bd-btn bd-gold" id="bd-ok">Lưu</button>' +
      '<button type="button" class="bd-btn" id="bd-prev">Xem thử thẻ</button>' +
      (bd ? '<button type="button" class="bd-btn" id="bd-del">Xóa</button>' : '') + '</div>', 'bd-light');
    var el = box.el, err = el.querySelector('.bd-err');
    var nameIn = document.getElementById('bd-in-name'), dSel = document.getElementById('bd-in-d'), mSel = document.getElementById('bd-in-m');
    var phIn = document.getElementById('bd-in-phone'), okIn = document.getElementById('bd-in-ok'), okBtn = document.getElementById('bd-ok');
    nameIn.value = defaultName();
    function read() {
      var d = parseInt(dSel.value, 10), m = parseInt(mSel.value, 10);
      if (!d || !m) { err.textContent = 'Em hãy chọn đủ ngày và tháng.'; return null; }
      if (d > dim(m, 2024)) { err.textContent = 'Tháng ' + m + ' không có ngày ' + d + '.'; return null; }
      var p = phone || normPhone(phIn && phIn.value);
      if (!p) { err.textContent = 'Em hãy nhập số điện thoại đã đăng ký (10 chữ số).'; return null; }
      if (!okIn.checked) { err.textContent = 'Em hãy tích ô đồng ý để lưu.'; return null; }
      err.textContent = '';
      return { d: d, m: m, p: p };
    }
    dSel.addEventListener('change', function () { err.textContent = ''; });
    mSel.addEventListener('change', function () { err.textContent = ''; });
    okBtn.addEventListener('click', function () {
      var v = read(); if (!v) return;
      var n = nameIn.value.trim();
      okBtn.disabled = true; okBtn.textContent = 'Đang lưu...';
      api({ action: 'birthdaySet', phone: v.p, md: pad(v.m) + '-' + pad(v.d), nick: n, tok: getTok() }).then(function () {
        lsSet('bd_md', pad(v.m) + '-' + pad(v.d));
        if (n) lsSet('bd_name', n); else lsDel('bd_name');
        if (!phone) lsSet('bd_phone', v.p);
        lsDel('bd_chk');
        track('birthday_set');
        box.close();
        if (window.physicsApp && typeof window.physicsApp.showNotification === 'function') {
          try { window.physicsApp.showNotification('Đã lưu! Đến sinh nhật em, thầy sẽ gửi lời chúc.', 'success'); } catch (e) {}
        }
      }).catch(function (e) {
        err.textContent = (e && e.message) || 'Chưa lưu được. Em kiểm tra mạng rồi thử lại.';
        okBtn.disabled = false; okBtn.textContent = 'Lưu';
      });
    });
    document.getElementById('bd-prev').addEventListener('click', function () {
      var n = nameIn.value.trim() || 'bạn';
      box.close();
      openCard({ name: n, late: 0, year: new Date().getFullYear(), preview: true });
    });
    var del = document.getElementById('bd-del');
    if (del) del.addEventListener('click', function () {
      var p = phone || normPhone(ls('bd_phone'));
      function done() { lsDel('bd_md'); lsDel('bd_name'); lsDel('bd_chk'); box.close(); }
      if (!p) { done(); return; }
      api({ action: 'birthdayDelete', phone: p, tok: getTok() }).then(done).catch(function (e) {
        err.textContent = (e && e.message) || 'Chưa xóa được. Em thử lại sau.';
      });
    });
    nameIn.focus();
  }

  /* ---------- NÚT Ở HEADER ---------- */
  function addButton() {
    if (document.getElementById('bd-open')) return;
    var host = document.getElementById('login-container');
    if (!host) return;
    var b = document.createElement('button');
    b.type = 'button'; b.id = 'bd-open';
    b.setAttribute('aria-label', 'Đặt ngày sinh nhật để nhận thẻ chúc mừng');
    b.title = 'Nhận thẻ chúc mừng sinh nhật';
    b.innerHTML = '<i class="fas fa-birthday-cake" aria-hidden="true"></i>';
    b.addEventListener('click', openSetup);
    host.appendChild(b);
  }

  /* ---------- KHỞI CHẠY ---------- */
  function disclaimerOk() {
    try {
      for (var i = 0; i < window.localStorage.length; i++) {
        var k = window.localStorage.key(i);
        if (k && k.indexOf('dc_ok_') === 0) {
          var t = parseInt(window.localStorage.getItem(k) || '0', 10);
          if (t > 0 && (Date.now() - t) < 31 * 86400000) return true;
        }
      }
    } catch (e) { return true; }
    return false;
  }
  function maybeShow(tries) {
    if (/[?&]bdtest=1/.test(window.location.search) && isAdminBd()) {
      openCard({ admin: true, name: CFG.TEACHER, late: 0, year: new Date().getFullYear(), preview: true });
      return;
    }
    if (/[?&]bdtest=1/.test(window.location.search)) {
      openCard({ name: defaultName() || 'bạn', late: 0, year: new Date().getFullYear(), preview: true });
      return;
    }
    if (isAdminBd()) {
      var late = adminLate(), yr = new Date().getFullYear();
      if (late < 0 || ls('bd_admin_shown_' + yr)) return;
      if (!disclaimerOk() && tries < 40) { setTimeout(function () { maybeShow(tries + 1); }, 1500); return; }
      openCard({ admin: true, name: CFG.TEACHER, late: late, year: yr, preview: false });
      return;
    }
    var ph = getPhone(), key = todayKey();
    if (!ph || ls('bd_chk') === key) return;   // mỗi ngày chỉ hỏi máy chủ tối đa một lần
    if (!disclaimerOk() && tries < 40) { setTimeout(function () { maybeShow(tries + 1); }, 1500); return; }
    api({ action: 'birthdayCheck', phone: ph }).then(function (d) {
      if (!d || !d.registered || !d.has || !d.due || ls('bd_shown_' + d.year)) { lsSet('bd_chk', key); return; }
      openCard({ name: d.name || 'bạn', late: d.late || 0, year: d.year, preview: false });
    }).catch(function () {});
  }

  addButton();
  setTimeout(function () { maybeShow(0); }, 2500);
})();
