(function () {
  'use strict';

  var CFG = { TEACHER: 'Thầy Hùng', START_DELAY: 6000 };

  /*PURE_START*/
  var STEMS = ['Giáp', 'Ất', 'Bính', 'Đinh', 'Mậu', 'Kỷ', 'Canh', 'Tân', 'Nhâm', 'Quý'];
  var BRANCHES = ['Tý', 'Sửu', 'Dần', 'Mão', 'Thìn', 'Tỵ', 'Ngọ', 'Mùi', 'Thân', 'Dậu', 'Tuất', 'Hợi'];
  function canChi(y) { return STEMS[((y - 4) % 10 + 10) % 10] + ' ' + BRANCHES[((y - 4) % 12 + 12) % 12]; }

  // Đổi ngày dương sang ngày âm theo thuật toán âm lịch Việt Nam (múi giờ UTC+7, thuật toán của Hồ Ngọc Đức).
  function INT(d) { return Math.floor(d); }
  function jdFromDate(dd, mm, yy) {
    var a = INT((14 - mm) / 12), y = yy + 4800 - a, m = mm + 12 * a - 3;
    var jd = dd + INT((153 * m + 2) / 5) + 365 * y + INT(y / 4) - INT(y / 100) + INT(y / 400) - 32045;
    if (jd < 2299161) jd = dd + INT((153 * m + 2) / 5) + 365 * y + INT(y / 4) - 32083;
    return jd;
  }
  function newMoon(k) {
    var T = k / 1236.85, T2 = T * T, T3 = T2 * T, dr = Math.PI / 180;
    var Jd1 = 2415020.75933 + 29.53058868 * k + 0.0001178 * T2 - 0.000000155 * T3;
    Jd1 = Jd1 + 0.00033 * Math.sin((166.56 + 132.87 * T - 0.009173 * T2) * dr);
    var M = 359.2242 + 29.10535608 * k - 0.0000333 * T2 - 0.00000347 * T3;
    var Mpr = 306.0253 + 385.81691806 * k + 0.0107306 * T2 + 0.00001236 * T3;
    var F = 21.2964 + 390.67050646 * k - 0.0016528 * T2 - 0.00000239 * T3;
    var C1 = (0.1734 - 0.000393 * T) * Math.sin(M * dr) + 0.0021 * Math.sin(2 * dr * M);
    C1 = C1 - 0.4068 * Math.sin(Mpr * dr) + 0.0161 * Math.sin(dr * 2 * Mpr);
    C1 = C1 - 0.0004 * Math.sin(dr * 3 * Mpr);
    C1 = C1 + 0.0104 * Math.sin(dr * 2 * F) - 0.0051 * Math.sin(dr * (M + Mpr));
    C1 = C1 - 0.0074 * Math.sin(dr * (M - Mpr)) + 0.0004 * Math.sin(dr * (2 * F + M));
    C1 = C1 - 0.0004 * Math.sin(dr * (2 * F - M)) - 0.0006 * Math.sin(dr * (2 * F + Mpr));
    C1 = C1 + 0.0010 * Math.sin(dr * (2 * F - Mpr)) + 0.0005 * Math.sin(dr * (2 * Mpr + M));
    var dt = (T < -11) ? 0.001 + 0.000839 * T + 0.0002261 * T2 - 0.00000845 * T3 - 0.000000081 * T * T3
                       : -0.000278 + 0.000265 * T + 0.000262 * T2;
    return Jd1 + C1 - dt;
  }
  function newMoonDay(k, tz) { return INT(newMoon(k) + 0.5 + tz / 24); }
  function sunLongitude(jdn, tz) {
    var jd = jdn - 0.5 - tz / 24, T = (jd - 2451545.0) / 36525, T2 = T * T, dr = Math.PI / 180;
    var M = 357.52910 + 35999.05030 * T - 0.0001559 * T2 - 0.00000048 * T * T2;
    var L0 = 280.46645 + 36000.76983 * T + 0.0003032 * T2;
    var DL = (1.914600 - 0.004817 * T - 0.000014 * T2) * Math.sin(dr * M);
    DL = DL + (0.019993 - 0.000101 * T) * Math.sin(dr * 2 * M) + 0.000290 * Math.sin(dr * 3 * M);
    var L = (L0 + DL) * dr;
    L = L - Math.PI * 2 * INT(L / (Math.PI * 2));
    return INT(L / Math.PI * 6);
  }
  function lunarMonth11(yy, tz) {
    var off = jdFromDate(31, 12, yy) - 2415021, k = INT(off / 29.530588853);
    var nm = newMoonDay(k, tz);
    if (sunLongitude(nm, tz) >= 9) nm = newMoonDay(k - 1, tz);
    return nm;
  }
  function leapMonthOffset(a11, tz) {
    var k = INT((a11 - 2415021.076998695) / 29.530588853 + 0.5), last, i = 1;
    var arc = sunLongitude(newMoonDay(k + i, tz), tz);
    do { last = arc; i++; arc = sunLongitude(newMoonDay(k + i, tz), tz); } while (arc !== last && i < 14);
    return i - 1;
  }
  function lunarOf(date) {
    try {
      var tz = 7, dd = date.getDate(), mm = date.getMonth() + 1, yy = date.getFullYear();
      var dayNumber = jdFromDate(dd, mm, yy), k = INT((dayNumber - 2415021.076998695) / 29.530588853);
      var monthStart = newMoonDay(k + 1, tz);
      if (monthStart > dayNumber) monthStart = newMoonDay(k, tz);
      var a11 = lunarMonth11(yy, tz), b11 = a11;
      if (a11 >= monthStart) { a11 = lunarMonth11(yy - 1, tz); } else { b11 = lunarMonth11(yy + 1, tz); }
      var ld = dayNumber - monthStart + 1, diff = INT((monthStart - a11) / 29), leap = false, lm = diff + 11;
      if (b11 - a11 > 365) {
        var lmd = leapMonthOffset(a11, tz);
        if (diff >= lmd) { lm = diff + 10; if (diff === lmd) leap = true; }
      }
      if (lm > 12) lm -= 12;
      return { m: lm, d: ld, leap: leap };
    } catch (e) { return null; }
  }
  function infoOf(date) {
    var n = new Date(date.getFullYear(), date.getMonth(), date.getDate(), 12);
    var nx = new Date(n.getTime() + 86400000);
    var L = lunarOf(n), N = lunarOf(nx);
    return { y: n.getFullYear(), m: n.getMonth() + 1, d: n.getDate(), L: L,
             tetEve: !!(L && N && !N.leap && N.m === 1 && N.d === 1) };
  }
  function lunarIs(t, m, d) { return !!(t.L && !t.L.leap && t.L.m === m && t.L.d === d); }

  var H = [
    { id: 'newyear', test: function (t) { return t.m === 1 && t.d <= 2; } },
    { id: 'tet', test: function (t) { return t.tetEve || (t.L && !t.L.leap && t.L.m === 1 && t.L.d <= 3); } },
    { id: 'women8', test: function (t) { return t.m === 3 && t.d === 8; } },
    { id: 'giotohung', test: function (t) { return lunarIs(t, 3, 10); } },
    { id: 'apr30', test: function (t) { return (t.m === 4 && t.d === 30) || (t.m === 5 && t.d === 1); } },
    { id: 'child', test: function (t) { return t.m === 6 && t.d === 1; } },
    { id: 'natday', test: function (t) { return t.m === 9 && t.d <= 2; } },
    { id: 'school', test: function (t) { return t.m === 9 && t.d === 5; } },
    { id: 'midautumn', test: function (t) { return lunarIs(t, 8, 15); } },
    { id: 'vnwomen', test: function (t) { return t.m === 10 && t.d === 20; } },
    { id: 'teachers', test: function (t) { return t.m === 11 && t.d === 20; } },
    { id: 'xmas', test: function (t) { return t.m === 12 && (t.d === 24 || t.d === 25); } }
  ];
  function findToday(date) {
    var t = infoOf(date);
    for (var i = 0; i < H.length; i++) if (H[i].test(t)) return { id: H[i].id, t: t };
    return null;
  }
  /*PURE_END*/

  // Nội dung từng thiệp. year = năm dương lịch hiện tại, cy = tên năm âm lịch (Can Chi).
  function content(id, t) {
    var y = t.y, cy = canChi(y);
    var C = {
      newyear: { icon: '🎆', c: ['#1b2a6b', '#6a1b9a'], conf: ['#ffd700', '#ff6b9d', '#6ee7ff', '#fff'],
        title: 'Chúc mừng năm mới ' + y,
        wish: 'Thầy chúc các em bước vào năm mới với sức khỏe, niềm vui và thật nhiều tiến bộ trong học tập. Mỗi ngày học một chút, cả năm sẽ đi được một đoạn đường dài.',
        admin: 'Chúc Thầy năm mới ' + y + ' vạn sự như ý, sức khỏe dồi dào và luôn giữ ngọn lửa nhiệt huyết với nghề.' },
      tet: { icon: '🧧', c: ['#a50e0e', '#e65100'], conf: ['#ffd700', '#ff5252', '#ffb300', '#fff'],
        title: (t.tetEve ? 'Giao thừa: chúc mừng năm mới ' : 'Chúc mừng năm mới ') + cy,
        wish: 'Thầy chúc các em và gia đình một cái Tết an khang, thịnh vượng. Năm mới học tập tiến bộ, sức khỏe dồi dào, vạn sự như ý!',
        admin: 'Chúc Thầy và gia đình một cái Tết ấm áp, an khang thịnh vượng. Năm ' + cy + ' mạnh khỏe, hạnh phúc và vạn sự như ý!' },
      women8: { icon: '🌸', c: ['#ad1457', '#ef6c00'], conf: ['#ff80ab', '#ffd1dc', '#ffd700', '#fff'],
        title: 'Chúc mừng Ngày Quốc tế Phụ nữ 8/3',
        wish: 'Thầy gửi lời chúc đến các bạn nữ và các cô, các mẹ: luôn khỏe mạnh, xinh tươi, tự tin theo đuổi điều mình yêu thích.',
        admin: 'Chúc Thầy một ngày 8/3 thật vui. Chúc những người phụ nữ bên cạnh Thầy luôn khỏe mạnh và hạnh phúc.' },
      giotohung: { icon: '🏯', c: ['#7f1d1d', '#b45309'], conf: ['#ffd700', '#ff7043', '#fff'],
        title: 'Giỗ Tổ Hùng Vương 10/3 âm lịch',
        wish: 'Con người có tổ, như cây có cội, như nước có nguồn. Chúc các em có một ngày nghỉ ý nghĩa bên gia đình.',
        admin: 'Nhân ngày Giỗ Tổ Hùng Vương, chúc Thầy và gia đình bình an, sức khỏe và có một ngày nghỉ thật ý nghĩa.' },
      apr30: { icon: '🇻🇳', c: ['#b71c1c', '#e65100'], conf: ['#ffd700', '#ff5252', '#fff'],
        title: 'Mừng ngày 30/4 và Quốc tế Lao động 1/5',
        wish: 'Chúc các em có kỳ nghỉ lễ vui vẻ, nghỉ ngơi thật tốt để quay lại với năng lượng mới.',
        admin: 'Chúc Thầy kỳ nghỉ lễ 30/4 và 1/5 thật thư thái bên gia đình.' },
      child: { icon: '🎈', c: ['#0277bd', '#7b1fa2'], conf: ['#ffeb3b', '#ff80ab', '#69f0ae', '#fff'],
