  }

  /* ---------- TIỆN ÍCH ---------- */
  function ls(k) { try { return window.localStorage.getItem(k); } catch (e) { return null; } }
  function lsSet(k, v) { try { window.localStorage.setItem(k, v); } catch (e) {} }
  function reduced() { return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); }
  function track(name, id) { try { if (typeof window.gtag === 'function') window.gtag('event', name, { location: 'holiday_' + id }); } catch (e) {} }
  function isAdmin() {
    if (ls('rg_admin') === '1') return true;
    try {
      var els = document.querySelectorAll('.item-control.blog-admin');
      for (var i = 0; i < els.length; i++) if (window.getComputedStyle(els[i]).display !== 'none') return true;
    } catch (e) {}
    return false;
  }
  function cleanName(n) {
    var x = String(n || '').replace(/\s*\(.*\)\s*$/, '').trim();
    return x.length > 30 ? x.slice(0, 30) : x;
  }
  // Tên người dùng đã đăng nhập / đăng ký trên trình duyệt này; khách thì trả về chuỗi rỗng
  function getName() {
    var a = window.physicsApp && window.physicsApp.userName;
    if (a && a !== 'Khách') return cleanName(a);
    var u = ls('userDisplayName');
    if (u && u !== 'Khách') return cleanName(u);
    try {
      var f = JSON.parse(ls('physicsForumUser'));
      if (f) { var n = f.displayName || f.username || f.name; if (n) return cleanName(n); }
    } catch (e) {}
    return '';
  }
  function disclaimerOk() {
    try {
      for (var i = 0; i < window.localStorage.length; i++) {
        var k = window.localStorage.key(i);
        if (k && k.indexOf('dc_ok_') === 0) {
          var t = parseInt(window.localStorage.getItem(k) || '0', 10);
          if (t > 0 && (Date.now() - t) < 31 * 86400000) return true;
        }
      }
    } catch (e) { return true; }
    return false;
  }
  function otherDialogOpen() {
    return !!(document.getElementById('bd-overlay') || document.getElementById('rg-modal') || document.getElementById('hd-overlay'));
  }

  /* ---------- PHÁO GIẤY ---------- */
  function confetti(colors) {
    if (reduced()) return;
    var cv = document.createElement('canvas');
    cv.id = 'hd-confetti';
    cv.width = window.innerWidth; cv.height = window.innerHeight;
    document.body.appendChild(cv);
    var g = cv.getContext('2d'), ps = [], i;
    for (i = 0; i < 130; i++) ps.push({
      x: Math.random() * cv.width, y: -20 - Math.random() * cv.height * 0.6,
      vx: (Math.random() - 0.5) * 2.2, vy: 2 + Math.random() * 3.2,
      s: 5 + Math.random() * 6, r: Math.random() * 6, vr: (Math.random() - 0.5) * 0.3,
      c: colors[i % colors.length]
    });
    var end = Date.now() + 4500;
    (function frame() {
      g.clearRect(0, 0, cv.width, cv.height);
      var alive = false;
      ps.forEach(function (p) {
        p.x += p.vx; p.y += p.vy; p.r += p.vr;
        if (p.y < cv.height + 20) alive = true;
        g.save(); g.translate(p.x, p.y); g.rotate(p.r);
        g.fillStyle = p.c; g.fillRect(-p.s / 2, -p.s / 4, p.s, p.s / 2); g.restore();
      });
      if (alive && Date.now() < end + 3000) requestAnimationFrame(frame);
      else if (cv.parentNode) cv.parentNode.removeChild(cv);
    })();
  }

  /* ---------- LƯU THIỆP THÀNH ẢNH ---------- */
  function wrap(g, text, x, y, maxW, lh) {
    var words = text.split(' '), line = '', i, test;
    for (i = 0; i < words.length; i++) {
      test = line ? line + ' ' + words[i] : words[i];
      if (g.measureText(test).width > maxW && line) { g.fillText(line, x, y); line = words[i]; y += lh; }
      else line = test;
    }
    if (line) g.fillText(line, x, y);
    return y + lh;
  }
  function savePNG(card, from) {
    var cv = document.createElement('canvas'); cv.width = 1080; cv.height = 1350;
    var g = cv.getContext('2d');
    var gr = g.createLinearGradient(0, 0, 1080, 1350);
    gr.addColorStop(0, card.c[0]); gr.addColorStop(1, card.c[1]);
    g.fillStyle = gr; g.fillRect(0, 0, 1080, 1350);
    g.fillStyle = '#fff'; g.textAlign = 'center';
    g.font = '600 38px sans-serif'; g.fillText(from, 540, 150);
    g.font = '230px sans-serif'; g.fillText(card.icon, 540, 470);
    var top = 650;
    if (card.to) {
      g.fillStyle = '#ffd700'; g.font = '700 52px sans-serif'; g.fillText(card.to, 540, 590);
      g.fillStyle = '#fff'; top = 690;
    }
    g.font = '700 66px sans-serif';
    var y = wrap(g, card.title, 540, top, 900, 84);
    g.font = '400 44px sans-serif';
    wrap(g, card.text, 540, y + 40, 880, 64);
    g.font = '600 34px sans-serif'; g.fillText(CFG.TEACHER + ' · Vật lí online', 540, 1270);
    cv.toBlob(function (b) {
      if (!b) return;
      var f = null;
      try { f = new File([b], 'thiep-chuc-mung.png', { type: 'image/png' }); } catch (e) {}
      if (f && navigator.canShare && navigator.canShare({ files: [f] }) && /Mobi|Android/i.test(navigator.userAgent)) {
        navigator.share({ files: [f], title: 'Thiệp chúc mừng' }).catch(function () {}); return;
      }
      var a = document.createElement('a');
      a.href = URL.createObjectURL(b); a.download = 'thiep-chuc-mung.png';
      document.body.appendChild(a); a.click();
      setTimeout(function () { URL.revokeObjectURL(a.href); if (a.parentNode) a.parentNode.removeChild(a); }, 1000);
    }, 'image/png');
  }

  /* ---------- HIỆN THIỆP ---------- */
  function openCard(id, t, preview) {
    if (document.getElementById('hd-overlay')) return;
    var c = content(id, t); if (!c) return;
    var admin = isAdmin();
    var text = admin ? c.admin : c.wish;
    var nm = admin ? '' : getName();
    var to = nm ? 'Gửi ' + nm + ',' : '';
    var from = admin ? 'Vật lí online gửi tặng Thầy' : CFG.TEACHER + ' gửi tặng ' + (nm || 'em');
    var ov = document.createElement('div');
    ov.id = 'hd-overlay';
    ov.innerHTML =
      '<div class="hd-card" role="dialog" aria-modal="true" aria-labelledby="hd-title">' +
      '<span class="hd-ribbon"></span><div class="hd-icon" aria-hidden="true"></div>' +
      '<p class="hd-to"></p><h2 id="hd-title"></h2><p class="hd-wish"></p>' +
      '<div class="hd-actions"><button type="button" class="hd-btn" id="hd-save">Lưu thiệp</button>' +
      '<button type="button" class="hd-btn hd-ghost" id="hd-close">Đóng</button></div></div>';
    var card = ov.querySelector('.hd-card');
    card.style.background = 'linear-gradient(135deg,' + c.c[0] + ',' + c.c[1] + ')';
    ov.querySelector('.hd-ribbon').textContent = from;
    ov.querySelector('.hd-icon').textContent = c.icon;
    var toEl = ov.querySelector('.hd-to');
    if (to) toEl.textContent = to; else toEl.style.display = 'none';
    ov.querySelector('h2').textContent = c.title;
    ov.querySelector('.hd-wish').textContent = text;
    var prevFocus = document.activeElement;
    function close() {
      document.removeEventListener('keydown', onKey, true);
      if (ov.parentNode) ov.parentNode.removeChild(ov);
      var cf = document.getElementById('hd-confetti'); if (cf && cf.parentNode) cf.parentNode.removeChild(cf);
      try { if (prevFocus && prevFocus.focus) prevFocus.focus(); } catch (e) {}
    }
    function onKey(e) { if (e.key === 'Escape') { e.stopPropagation(); close(); } }
    ov.addEventListener('click', function (e) { if (e.target === ov) close(); });
    document.addEventListener('keydown', onKey, true);
    document.body.appendChild(ov);
    ov.querySelector('#hd-close').addEventListener('click', close);
    ov.querySelector('#hd-save').addEventListener('click', function () {
      savePNG({ c: c.c, icon: c.icon, title: c.title, text: text, to: to }, from); track('holiday_save', id);
    });
    if (!preview) lsSet('hd_' + id + '_' + t.y, '1');
    track('holiday_card_view', id);
    confetti(c.conf);
    var b = ov.querySelector('#hd-close'); if (b) b.focus();
  }

  function maybeShow(tries) {
    var m = /[?&]hdtest=([a-z0-9]+)/.exec(window.location.search);
    if (m) {
      var t0 = infoOf(new Date());
      if (content(m[1], t0)) { openCard(m[1], t0, true); }
      return;
    }
    var hit = findToday(new Date());
    if (!hit || ls('hd_' + hit.id + '_' + hit.t.y)) return;
    // chờ hộp thông báo / thẻ sinh nhật đóng rồi mới hiện
    if ((!disclaimerOk() || otherDialogOpen()) && tries < 60) {
      setTimeout(function () { maybeShow(tries + 1); }, 2000); return;
    }
    openCard(hit.id, hit.t, false);
  }

  setTimeout(function () { maybeShow(0); }, CFG.START_DELAY);
})();
