(function () {
  'use strict';
  if (window.__aeLoaded) return; window.__aeLoaded = true;

  // ===== CẤU HÌNH =====
  var AE = {
    AUTH_API: 'https://script.google.com/macros/s/AKfycbwZtFufSTnRDLon-AIfnPWmafcPqbgBEeFOW7FvYfcKkAtk65bGOJUS_NxthoQcXawLbw/exec',  // máy chủ đăng nhập (Quản lí điểm)
    BANK_API: 'https://script.google.com/macros/s/AKfycbxdocxDem4OwqhrsGsiEX1WqJzzulLR36vjE5J0zB_D81tByFvS0GytzszQeaMGi5I0VQ/exec',  // máy chủ ngân hàng câu hỏi
    ADMIN_NAMES: ['admin']   // tên đăng nhập ở trang chủ được thử xác thực quyền quản trị
  };

  var S = null;   // trạng thái đang sửa: {label, updated, data, indent, set, sel, dirty, q}
  var SKIP = { type: 1, mainQuestion: 1, question: 1, explanation: 1, choices: 1, subQuestions: 1 };

  // ===== TIỆN ÍCH =====
  function $(s, r) { return (r || document).querySelector(s); }
  function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
  function isTrue(v) { if (typeof v === 'boolean') return v; var s = String(v == null ? '' : v).toLowerCase().trim(); return s === 'true' || s === 'đúng' || s === 'đ'; }
  function plain(s) { return String(s == null ? '' : s).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim(); }
  function lsGet(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
  var toastTimer = null;
  function toast(msg, kind) {
    var t = $('#ae-toast');
    if (!t) { t = document.createElement('div'); t.id = 'ae-toast'; document.body.appendChild(t); }
    t.className = kind || ''; t.textContent = msg; t.style.display = 'block';
    clearTimeout(toastTimer); toastTimer = setTimeout(function () { t.style.display = 'none'; }, kind === 'err' ? 7000 : 3500);
  }

  // ===== PHIÊN ĐĂNG NHẬP ADMIN =====
  function getSess() { try { var o = JSON.parse(lsGet('ae_session') || 'null'); return o && o.token ? o : null; } catch (e) { return null; } }
  function setSess(o) {
    try { if (o) localStorage.setItem('ae_session', JSON.stringify(o)); else localStorage.removeItem('ae_session'); } catch (e) {}
    try { if (o) sessionStorage.setItem('adminAuthToken', o.token); else sessionStorage.removeItem('adminAuthToken'); } catch (e) {}
  }
  function authPost(params) {
    var b = new URLSearchParams();
    Object.keys(params).forEach(function (k) { b.append(k, params[k]); });
    return fetch(AE.AUTH_API, { method: 'POST', body: b }).then(function (r) { return r.json(); });
  }
  function doLogin(user, pass) {
    return authPost({ action: 'login', username: user, password: pass }).then(function (j) {
      if (!j || !j.success || !j.data || !j.data.token) throw new Error((j && (j.error || j.message)) || 'Sai tên đăng nhập hoặc mật khẩu');
      var role = j.data.role || 'full';
      if (role !== 'full') throw new Error('Tài khoản này không có quyền quản trị toàn quyền');
      var s = { token: j.data.token, user: user, role: role, ts: Date.now() };
      setSess(s); refreshFab();
      return s;
    });
  }
  function promptLogin() {
    return new Promise(function (resolve, reject) {
      var w = document.createElement('div');
      w.style.cssText = 'position:fixed;inset:0;z-index:100001;background:rgba(0,0,0,.55);display:flex;align-items:center;justify-content:center;font:14px system-ui,sans-serif';
      w.innerHTML = '<form style="background:#fff;padding:20px;border-radius:12px;width:min(340px,92vw);display:grid;gap:10px">' +
        '<b style="font-size:16px">🔑 Đăng nhập quản trị</b>' +
        '<input name="u" placeholder="Tên đăng nhập" value="' + esc(AE.ADMIN_NAMES[0] || '') + '" style="padding:8px;border:1px solid #bbb;border-radius:6px">' +
        '<input name="p" type="password" placeholder="Mật khẩu" style="padding:8px;border:1px solid #bbb;border-radius:6px">' +
        '<div class="ae-lerr" style="color:#dc3545;min-height:18px"></div>' +
        '<div style="display:flex;gap:8px;justify-content:flex-end"><button type="button" class="ae-lc" style="padding:7px 12px">Hủy</button><button type="submit" style="padding:7px 14px;background:#4361ee;color:#fff;border:0;border-radius:6px">Đăng nhập</button></div></form>';
      document.body.appendChild(w);
      var f = $('form', w);
      f.p.focus();
      $('.ae-lc', w).onclick = function () { w.remove(); reject(new Error('Đã hủy đăng nhập')); };
      f.onsubmit = function (e) {
        e.preventDefault();
        $('.ae-lerr', w).textContent = 'Đang xác thực...';
        doLogin(f.u.value.trim(), f.p.value).then(function (s) { w.remove(); resolve(s); })
          .catch(function (err) { $('.ae-lerr', w).textContent = err.message; });
      };
    });
  }
  // Trả về phiên hợp lệ (xác thực lại với máy chủ); chưa có/hết hạn thì hỏi đăng nhập
  function ensureSession() {
    var s = getSess();
    if (!s) return promptLogin();
    return authPost({ action: 'validateToken', token: s.token }).then(function (j) {
      if (j && j.success && j.data && j.data.valid && (j.data.role || 'full') === 'full') { s.ts = Date.now(); setSess(s); return s; }
      setSess(null); refreshFab();
      return promptLogin();
    }).catch(function (err) {
      if (err && /Đã hủy/.test(err.message)) throw err;
      throw new Error('Không kết nối được máy chủ đăng nhập: ' + (err && err.message || err));
    });
  }
  function postBank(body) {
    var s = getSess(); body.token = s ? s.token : '';
    return fetch(AE.BANK_API, { method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: JSON.stringify(body) })
      .then(function (r) { return r.text(); })
      .then(function (t) {
        var j; try { j = JSON.parse(t); } catch (e) { throw new Error('Máy chủ không trả về JSON — có thể chưa Deploy phiên bản mới của Apps Script'); }
        if (!j.ok) { var er = new Error(j.message || j.error || 'Máy chủ từ chối'); er.code = j.error; er.info = j; throw er; }
        return j;
      });
  }

  // ===== NHẬN DIỆN NHÃN CỦA TRANG =====
  function detectLabels() {
    var raw = [];
    try { if (typeof LESSON_CFG !== 'undefined' && LESSON_CFG && LESSON_CFG.quiz && LESSON_CFG.quiz.label) raw.push(String(LESSON_CFG.quiz.label)); } catch (e) {}
    try { var m = location.pathname.match(/\/label\/([^/?#]+)/); if (m) raw.push(decodeURIComponent(m[1])); } catch (e) {}
    try { if (typeof pageContent !== 'undefined' && pageContent && pageContent.practiceLink) { var m2 = String(pageContent.practiceLink).match(/\/label\/([^/?#]+)/); if (m2) raw.push(decodeURIComponent(m2[1])); } } catch (e) {}
    var out = [];
    raw.join(';').split(/[;,]/).forEach(function (x) { x = x.trim(); if (/^[A-Za-z0-9_-]{1,80}$/.test(x) && out.indexOf(x) < 0) out.push(x); });
    return out;
  }

  // ===== NÚT NỔI =====
  function bloggerAdmin() {
    try { var els = document.querySelectorAll('.item-control.blog-admin'); for (var i = 0; i < els.length; i++) if (getComputedStyle(els[i]).display !== 'none') return true; } catch (e) {}
    return false;
  }
  function fabsOff() { try { return sessionStorage.getItem('ae_fab_off') === '1'; } catch (e) { return false; } }
  function hideFabs() {
    try { sessionStorage.setItem('ae_fab_off', '1'); } catch (e) {}
    ['ae-fab', 'al-fab'].forEach(function (id) { var x = document.getElementById(id); if (x) x.remove(); });
  }
  function refreshFab() {
    var show = !fabsOff() && (!!getSess() || lsGet('rg_admin') === '1' || bloggerAdmin());   // chỉ để HIỆN nút; quyền thật do máy chủ kiểm tra
    var b = $('#ae-fab');
    if (show && !b) {
      b = document.createElement('button'); b.id = 'ae-fab'; b.type = 'button';
      b.innerHTML = '✏️ Sửa câu hỏi<span class="ae-x" title="Ẩn nút (đến khi mở tab mới)">×</span>';
      b.setAttribute('data-html2canvas-ignore', 'true');
