    m = document.createElement('div'); m.id = 'ae-modal';
    m.innerHTML =
      '<div class="ae-box">' +
      '<div class="ae-top"><b>✏️ Sửa câu hỏi</b>' +
      '<input id="ae-label" list="ae-labels" placeholder="Nhãn file, VD: lt-10-2-4"><datalist id="ae-labels"></datalist>' +
      '<button id="ae-open" type="button">Mở</button>' +
      '<span id="ae-status"></span>' +
      '<button id="ae-save" class="ae-pri" type="button" disabled>💾 Lưu lên Drive</button>' +
      '<button id="ae-logout" type="button">Đăng xuất</button>' +
      '<button id="ae-close" type="button">Đóng</button></div>' +
      '<div class="ae-body"><div class="ae-left">' +
      '<div class="ae-tabs"><button id="ae-t1" type="button">quizData</button><button id="ae-t2" type="button">extraPracticeData</button></div>' +
      '<input id="ae-search" placeholder="Tìm theo ID hoặc nội dung...">' +
      '<div id="ae-list"></div>' +
      '<div style="padding:6px;display:flex;gap:6px"><button id="ae-clone" type="button">⧉ Nhân bản</button><button id="ae-del" class="ae-danger" type="button">🗑 Xóa</button></div>' +
      '</div><div class="ae-right" id="ae-form"><p>Nhập nhãn file rồi bấm <b>Mở</b>.</p></div></div></div>';
    document.body.appendChild(m);
    $('#ae-open').onclick = function () { var v = $('#ae-label').value.trim(); if (v) loadLabel(v); };
    $('#ae-label').onkeydown = function (e) { if (e.key === 'Enter') $('#ae-open').click(); };
    $('#ae-save').onclick = save;
    $('#ae-close').onclick = closeEditor;
    $('#ae-logout').onclick = function () { setSess(null); refreshFab(); closeEditor(true); toast('Đã đăng xuất quản trị'); };
    $('#ae-t1').onclick = function () { switchSet('quizData'); };
    $('#ae-t2').onclick = function () { switchSet('extraPracticeData'); };
    $('#ae-search').oninput = renderList;
    $('#ae-list').onclick = function (e) { var d = e.target.closest('[data-id]'); if (d) select(d.getAttribute('data-id')); };
    $('#ae-clone').onclick = cloneQ;
    $('#ae-del').onclick = delQ;
    return m;
  }
  function closeEditor(force) {
    if (!force && S && S.dirty && !confirm('Có thay đổi chưa lưu. Đóng và bỏ thay đổi?')) return;
    S = null; var m = $('#ae-modal'); if (m) m.style.display = 'none';
  }
  window.addEventListener('beforeunload', function (e) { if (S && S.dirty) { e.preventDefault(); e.returnValue = ''; } });
  function status(msg, bad) { var s = $('#ae-status'); if (s) { s.textContent = msg || ''; s.style.color = bad ? '#dc3545' : '#333'; } }

  function openEditor() {
    ensureSession().then(function () {
      var m = buildModal(); m.style.display = 'flex';
      var labs = detectLabels();
      $('#ae-labels').innerHTML = labs.map(function (l) { return '<option value="' + esc(l) + '">'; }).join('');
      if (!S) { if (labs.length) $('#ae-label').value = labs[0]; if (labs.length === 1) loadLabel(labs[0]); }
    }).catch(function (e) { toast(e.message, 'err'); });
  }

  function loadLabel(label) {
    if (S && S.dirty && !confirm('Có thay đổi chưa lưu. Tải file khác và bỏ thay đổi?')) return;
    status('Đang tải ' + label + '.json từ Drive...');
    postBank({ action: 'bank_read_file', label: label }).then(function (j) {
      var data; try { data = JSON.parse(j.text); } catch (e) { throw new Error('File JSON trên Drive đang lỗi: ' + e.message); }
      var mi = /^\s*[\{\[]\s*\r?\n([ \t]+)"/.exec(j.text);
      S = { label: label, updated: j.updated, data: data, indent: mi ? mi[1] : '', crlf: j.text.indexOf('\r\n') !== -1, set: data.quizData ? 'quizData' : 'extraPracticeData', sel: null, dirty: false };
      $('#ae-save').disabled = false;
      renderAll();
      status('Đã mở ' + label + ' — ' + count('quizData') + ' + ' + count('extraPracticeData') + ' câu');
    }).catch(function (e) { status(e.message, true); });
  }
  function count(set) { return S && S.data[set] ? Object.keys(S.data[set]).length : 0; }
  function setObj() { return (S.data[S.set] && typeof S.data[S.set] === 'object') ? S.data[S.set] : {}; }
  function dirty() { if (S) { S.dirty = true; status('● Có thay đổi chưa lưu'); } }

  function switchSet(name) { if (!S) return; S.set = name; S.sel = null; renderAll(); }
  function renderAll() {
    $('#ae-t1').textContent = 'quizData (' + count('quizData') + ')';
    $('#ae-t2').textContent = 'extraPracticeData (' + count('extraPracticeData') + ')';
    $('#ae-t1').className = S.set === 'quizData' ? 'on' : '';
    $('#ae-t2').className = S.set === 'extraPracticeData' ? 'on' : '';
    renderList(); renderForm();
  }
  function renderList() {
    if (!S) return;
    var f = String($('#ae-search').value || '').toLowerCase(), o = setObj(), keys = Object.keys(o), h = '', shown = 0;
    for (var i = 0; i < keys.length && shown < 300; i++) {
      var q = o[keys[i]], t = plain(q && (q.mainQuestion || q.question));
      if (f && (keys[i] + ' ' + t).toLowerCase().indexOf(f) < 0) continue;
      shown++;
      h += '<div data-id="' + esc(keys[i]) + '" class="' + (keys[i] === S.sel ? 'on' : '') + '"><b>' + esc(keys[i]) + '</b> <small>' + esc(q && q.type) + '</small>' + esc(t.slice(0, 90)) + '</div>';
    }
    $('#ae-list').innerHTML = h || '<div>Không có câu nào</div>';
  }
  function select(id) { S.sel = id; renderList(); renderForm(); }

  // ----- Hàm đọc/ghi cờ đúng-sai, giữ nguyên kiểu dữ liệu gốc (chuỗi "true"/"false" hay boolean) -----
  function flagOk(c) { return isTrue(c.answer !== undefined ? c.answer : (c.isCorrect !== undefined ? c.isCorrect : c.correct)); }
  function flagSet(c, on) {
    var any = false;
    ['answer', 'isCorrect', 'correct'].forEach(function (f) { if (c[f] !== undefined) { any = true; c[f] = (typeof c[f] === 'string') ? (on ? 'true' : 'false') : !!on; } });
    if (!any) c.answer = on ? 'true' : 'false';
  }

  function renderForm() {
    var box = $('#ae-form');
    var q = S && S.sel ? setObj()[S.sel] : null;
    if (!q) { box.innerHTML = '<p>Chọn một câu ở danh sách bên trái.</p>'; return; }
    var h = '<div><b>ID:</b> ' + esc(S.sel) + ' &nbsp; <b>Loại:</b> ' + esc(q.type) + '</div>';
    h += '<label>Đề bài (mainQuestion)</label><textarea rows="4" data-f="mainQuestion">' + esc(q.mainQuestion) + '</textarea>';
    if (typeof q.question === 'string') h += '<label>question</label><textarea rows="2" data-f="question">' + esc(q.question) + '</textarea>';
    Object.keys(q).forEach(function (k) {
      if (SKIP[k]) return; var v = q[k];
      if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') h += '<label>' + esc(k) + '</label><input type="text" data-s="' + esc(k) + '" value="' + esc(v) + '">';
    });
    if (Array.isArray(q.choices)) {
      h += '<label>Các phương án (' + (q.type === 'multipleChoice' ? 'chọn 1 đáp án đúng' : 'tích những phương án đúng') + ')</label>';
      q.choices.forEach(function (c, i) {
        h += '<div class="ae-ch"><input type="checkbox" data-ck="' + i + '"' + (flagOk(c) ? ' checked' : '') + '>' +
          '<textarea rows="2" data-ct="' + i + '">' + esc(c.choice) + '</textarea>' +
          (c.score !== undefined ? '<input type="text" class="ae-cscore" data-cs="' + i + '" value="' + esc(c.score) + '" title="điểm">' : '') + '</div>';
      });
    }
    if (Array.isArray(q.subQuestions)) {
      h += '<label>Các ý nhỏ (subQuestions)</label>';
      q.subQuestions.forEach(function (c, i) {
        h += '<div class="ae-ch"><textarea rows="2" data-qt="' + i + '">' + esc(c.question) + '</textarea>';
        if (q.type === 'trueFalse') h += '<select data-qa="' + i + '"><option value="1"' + (flagOk(c) ? ' selected' : '') + '>Đúng</option><option value="0"' + (flagOk(c) ? '' : ' selected') + '>Sai</option></select>';
        else if (c.answer !== undefined) h += '<input type="text" class="ae-cscore" style="width:140px" data-qv="' + i + '" value="' + esc(c.answer) + '">';
        h += '</div>';
      });
    }
    if (typeof q.explanation === 'string') h += '<label>Lời giải (explanation)</label><textarea rows="5" data-f="explanation">' + esc(q.explanation) + '</textarea>';
    h += '<details style="margin-top:14px"><summary>JSON của câu này (nâng cao: thêm/bớt trường, sửa hình, v.v.)</summary>' +
      '<textarea id="ae-json" rows="12">' + esc(JSON.stringify(q, null, 2)) + '</textarea>' +
      '<button type="button" id="ae-applyjson" style="margin-top:6px">Áp dụng JSON này</button></details>';
    box.innerHTML = h;
    box.oninput = onInput; box.onchange = onChange;
    var aj = $('#ae-applyjson');
    if (aj) aj.onclick = function () {
      try { var n = JSON.parse($('#ae-json').value); if (!n || typeof n !== 'object' || Array.isArray(n) || typeof n.type !== 'string' || typeof n.mainQuestion !== 'string') throw new Error('Cần đối tượng có type và mainQuestion'); setObj()[S.sel] = n; dirty(); renderAll(); toast('Đã áp dụng JSON', 'ok'); }
      catch (e) { toast('JSON lỗi: ' + e.message, 'err'); }
    };
  }
  function curQ() { return S && S.sel ? setObj()[S.sel] : null; }
  function onInput(e) {
    var q = curQ(), t = e.target; if (!q) return;
    if (t.dataset.f) q[t.dataset.f] = t.value;
    else if (t.dataset.s) { var k = t.dataset.s, o = q[k]; q[k] = typeof o === 'number' ? ((t.value.trim() !== '' && isFinite(t.value)) ? Number(t.value) : t.value) : (typeof o === 'boolean' ? t.value === 'true' : t.value); }
    else if (t.dataset.ct !== undefined) q.choices[+t.dataset.ct].choice = t.value;
    else if (t.dataset.cs !== undefined) q.choices[+t.dataset.cs].score = t.value;
    else if (t.dataset.qt !== undefined) q.subQuestions[+t.dataset.qt].question = t.value;
    else if (t.dataset.qv !== undefined) q.subQuestions[+t.dataset.qv].answer = t.value;
    else return;
    dirty();
  }
  function onChange(e) {
    var q = curQ(), t = e.target; if (!q) return;
    if (t.dataset.ck !== undefined) {
      var i = +t.dataset.ck;
      if (q.type === 'multipleChoice') { q.choices.forEach(function (c, j) { flagSet(c, j === i ? t.checked : false); }); if (!t.checked) flagSet(q.choices[i], false); renderForm(); }
      else flagSet(q.choices[i], t.checked);
      dirty();
    } else if (t.dataset.qa !== undefined) { flagSet(q.subQuestions[+t.dataset.qa], t.value === '1'); dirty(); }
    renderList();
  }

  function cloneQ() {
    var q = curQ(); if (!q) return toast('Chọn một câu để nhân bản', 'err');
    var id = prompt('ID cho câu mới (chữ, số, gạch ngang/dưới):', S.sel + '_copy');
    if (!id) return; id = id.trim();
    if (!/^[A-Za-z0-9_.-]{1,100}$/.test(id)) return toast('ID không hợp lệ', 'err');
    if ((S.data.quizData && S.data.quizData[id]) || (S.data.extraPracticeData && S.data.extraPracticeData[id])) return toast('ID đã tồn tại', 'err');
    if (!S.data[S.set]) S.data[S.set] = {};
    var n = JSON.parse(JSON.stringify(q)); if (n.ID !== undefined) n.ID = id;
    S.data[S.set][id] = n; S.sel = id; dirty(); renderAll();
  }
  function delQ() {
    var q = curQ(); if (!q) return toast('Chọn một câu để xóa', 'err');
    if (!confirm('Xóa câu ' + S.sel + '? (vẫn có bản sao lưu trên Drive sau khi lưu)')) return;
    delete S.data[S.set][S.sel]; S.sel = null; dirty(); renderAll();
  }

  function stringify() {
    var out = S.indent ? JSON.stringify(S.data, null, S.indent) : JSON.stringify(S.data);
    return S.crlf ? out.replace(/\r?\n/g, '\r\n') : out;
  }
  function save(confirmShrink) {
    if (!S) return;
    var btn = $('#ae-save'); btn.disabled = true; status('Đang lưu lên Drive...');
    postBank({ action: 'bank_save_file', label: S.label, text: stringify(), baseUpdated: S.updated, confirmShrink: confirmShrink === true })
      .then(function (j) {
        S.updated = j.updated; S.dirty = false;
        try { sessionStorage.removeItem('qapi_' + S.label); } catch (e) {}   // bỏ bộ nhớ tạm của trang để thấy ngay bản mới
        status('✓ Đã lưu ' + j.count + ' câu (trước đó ' + j.previousCount + '). Có bản sao lưu trong _bank_backup.');
        toast('Đã lưu vào Drive. Học sinh thấy bản mới khi tải lại trang.', 'ok');
      })
      .catch(function (e) {
        if (e.code === 'shrink' && confirm(e.message + '\n\nVẫn lưu?')) { btn.disabled = false; return save(true); }
        status(e.message, true);
        if (e.code === 'conflict') toast('File đã bị sửa ở nơi khác. Bấm Mở để tải lại bản mới nhất (thay đổi chưa lưu của bạn sẽ mất).', 'err');
        else if (e.code === 'unauthorized') { setSess(null); refreshFab(); toast('Phiên đăng nhập hết hạn — đóng cửa sổ, mở lại và đăng nhập (thay đổi chưa lưu vẫn còn nếu bạn chưa tải lại trang).', 'err'); }
        else toast(e.message, 'err');
      })
      .then(function () { btn.disabled = false; });
  }

  // ===== TRANG CHỦ: đăng nhập admin ở ô đăng nhập có sẵn =====
  var lf = document.getElementById('login-form');
  if (lf) lf.addEventListener('submit', function () {
    var u = document.getElementById('username'), p = document.getElementById('password');
    var name = u ? String(u.value || '').trim() : '';
    if (!name || !p || !p.value) return;
    if (!AE.ADMIN_NAMES.some(function (n) { return n.toLowerCase() === name.toLowerCase(); })) return;
    doLogin(name, p.value)
      .then(function () { toast('Đã mở quyền quản trị (✏️ Sửa câu hỏi) — hiệu lực khoảng 2 giờ', 'ok'); })
      .catch(function (e) { toast('Chưa mở được quyền quản trị: ' + e.message, 'err'); });
  });

  refreshFab(); setInterval(refreshFab, 2000);
  window.AdminEditor = {   // dùng chung phiên đăng nhập cho khối "sửa bài giảng"
    open: openEditor, ensureSession: ensureSession, getSess: getSess, toast: toast, esc: esc,
    hint: function () { return !fabsOff() && (!!getSess() || lsGet('rg_admin') === '1' || bloggerAdmin()); },
    hideFabs: hideFabs
  };
})();
