// 
(function () {
  'use strict';
  if (window.__aeLessonLoaded) return; window.__aeLessonLoaded = true;
  var AEc = window.AdminEditor;
  if (!AEc || !AEc.ensureSession) { try { console.warn('Khối "sửa bài giảng" cần khối "admin_editor_cau_hoi.html" dán TRƯỚC nó.'); } catch (e) {} return; }

  var CFG = {
    LESSON_API: 'https://script.google.com/macros/s/AKfycbyq99M8liZkOpFpfDHehz4j5sXCUrLcM_CkwYwMvBYLcfhnN8VvtTAYSG-A71GEN9Yh/exec',  // project "Ngân hàng câu hỏi" (BAIGIANG_API_URL)
    KINDS: [
      ['baigiang', 'Bài giảng lý thuyết'],
      ['cdbt', 'Chuyên đề bài tập'],
      ['cdvatli', 'Chuyên đề Vật lí'],
      ['gddp', 'Giáo dục địa phương']
    ],
    LOPS: ['10', '11', '12']
  };
  var esc = AEc.esc, toast = AEc.toast;
  var L = null;   // {kind,lop,fileId,fileName,updated,data,indent,crlf,dirty,mode,open:{}}
  function $(s, r) { return (r || document).querySelector(s); }
  function $$(s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); }
  function status(m, bad) { var s = $('#al-status'); if (s) { s.textContent = m || ''; s.style.color = bad ? '#dc3545' : '#333'; } }
  function dirty() { if (L) { L.dirty = true; status('● Có thay đổi chưa lưu'); } }

  function guessKind() {
    try { if (typeof CDVATLI_API_URL !== 'undefined') return 'cdvatli'; } catch (e) {}
    try { if (typeof CDBT_API_URL !== 'undefined') return 'cdbt'; } catch (e) {}
    try { if (typeof GDDP_API_URL !== 'undefined') return 'gddp'; } catch (e) {}
    return 'baigiang';
  }

  // ===== GỌI MÁY CHỦ =====
  function post(body) {
    var s = AEc.getSess(); body.token = s ? s.token : '';
    return fetch(CFG.LESSON_API, { method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: JSON.stringify(body) })
      .then(function (r) { return r.text(); })
      .then(function (t) {
        var j; try { j = JSON.parse(t); } catch (e) { throw new Error('Máy chủ không trả về JSON — có thể chưa dán bản vá hoặc chưa Deploy phiên bản mới'); }
        if (j.ok === undefined && j.success === false) throw new Error('Máy chủ chưa hỗ trợ sửa bài giảng (chưa dán bản vá + sửa doPost?): ' + (j.error || ''));
        if (!j.ok) { var er = new Error(j.message || j.error || 'Máy chủ từ chối'); er.code = j.error; throw er; }
        return j;
      });
  }

  // ===== NÚT NỔI + KHUNG =====
  function refreshFab() {
    var show = AEc.hint(), b = $('#al-fab');
    if (show && !b) {
      b = document.createElement('button'); b.id = 'al-fab'; b.type = 'button';
      b.innerHTML = '📝 Sửa bài giảng<span class="ae-x" title="Ẩn nút (đến khi mở tab mới)">×</span>';
      b.setAttribute('data-html2canvas-ignore', 'true');
      b.onclick = function (e) { if (e.target.className === 'ae-x') { e.stopPropagation(); AEc.hideFabs(); return; } openEditor(); };
      document.body.appendChild(b);
    }
    else if (!show && b) b.remove();
  }
  function buildModal() {
    var m = $('#al-modal'); if (m) return m;
    m = document.createElement('div'); m.id = 'al-modal';
    m.innerHTML =
      '<div class="al-box"><div class="al-top"><b>📝 Sửa bài giảng</b>' +
      '<select id="al-kind">' + CFG.KINDS.map(function (k) { return '<option value="' + k[0] + '">' + esc(k[1]) + '</option>'; }).join('') + '</select>' +
      '<select id="al-lop">' + CFG.LOPS.map(function (l) { return '<option value="' + l + '">Lớp ' + l + '</option>'; }).join('') + '</select>' +
      '<select id="al-file"><option value="">-- chọn file --</option></select>' +
      '<button id="al-open" type="button">Mở</button>' +
      '<input id="al-find" placeholder="Tìm trong bài..." style="width:150px">' +
      '<span id="al-status"></span>' +
      '<button id="al-mode" type="button">{ } JSON</button>' +
      '<button id="al-save" class="al-pri" type="button" disabled>💾 Lưu lên Drive</button>' +
      '<button id="al-close" type="button">Đóng</button></div>' +
      '<div id="al-form"><p>Chọn loại, lớp, rồi file bài cần sửa và bấm <b>Mở</b>.</p></div></div>';
    document.body.appendChild(m);
    $('#al-kind').onchange = loadList; $('#al-lop').onchange = loadList;
    $('#al-open').onclick = function () { var id = $('#al-file').value; if (id) loadFile(id); };
    $('#al-mode').onclick = toggleMode;
    $('#al-save').onclick = function () { save(false); };
    $('#al-close').onclick = closeEditor;
    $('#al-find').oninput = applyFilter;
    var f = $('#al-form');
    f.addEventListener('input', onInput); f.addEventListener('change', onChange); f.addEventListener('click', onClick);
    f.addEventListener('toggle', function (e) { if (L && e.target.tagName === 'DETAILS' && e.target.dataset.k) L.open[e.target.dataset.k] = e.target.open; }, true);
    return m;
  }
  function closeEditor() {
    if (L && L.dirty && !confirm('Có thay đổi chưa lưu. Đóng và bỏ thay đổi?')) return;
    L = null; var m = $('#al-modal'); if (m) m.style.display = 'none';
  }
  window.addEventListener('beforeunload', function (e) { if (L && L.dirty) { e.preventDefault(); e.returnValue = ''; } });

  function openEditor() {
    AEc.ensureSession().then(function () {
      var m = buildModal(); m.style.display = 'flex';
      if (!L) { $('#al-kind').value = guessKind(); loadList(); }
    }).catch(function (e) { toast(e.message, 'err'); });
  }
  function loadList() {
    if (L && L.dirty && !confirm('Có thay đổi chưa lưu. Đổi danh sách và bỏ thay đổi?')) return;
    L = null; $('#al-save').disabled = true;
    var sel = $('#al-file'); sel.innerHTML = '<option value="">Đang tải danh sách...</option>';
    post({ action: 'lesson_list', kind: $('#al-kind').value, lop: $('#al-lop').value }).then(function (j) {
      sel.innerHTML = '<option value="">-- chọn file (' + j.files.length + ') --</option>' +
        j.files.map(function (f) { return '<option value="' + esc(f.fileId) + '">' + esc(f.fileName) + '</option>'; }).join('');
      status('');
    }).catch(function (e) { sel.innerHTML = '<option value="">(lỗi)</option>'; status(e.message, true); });
  }
  function loadFile(fileId) {
    status('Đang tải file từ Drive...');
    post({ action: 'lesson_read', kind: $('#al-kind').value, lop: $('#al-lop').value, fileId: fileId }).then(function (j) {
      var data; try { data = JSON.parse(j.text); } catch (e) { throw new Error('File JSON trên Drive đang lỗi: ' + e.message); }
      var mi = /^\s*[\{\[]\s*\r?\n([ \t]+)"/.exec(j.text);
      L = { kind: $('#al-kind').value, lop: $('#al-lop').value, fileId: j.fileId, fileName: j.fileName, updated: j.updated, data: data,
            indent: mi ? mi[1] : '', crlf: j.text.indexOf('\r\n') !== -1, dirty: false, mode: 'form', open: {} };
      $('#al-save').disabled = false; $('#al-mode').textContent = '{ } JSON';
      $('#al-find').value = ''; renderForm(); status('Đã mở ' + j.fileName);
    }).catch(function (e) { status(e.message, true); });
  }

  // ===== CÂY BIỂU MẪU TỔNG QUÁT (không cần biết trước cấu trúc pageContent) =====
  function getAt(root, p) { var o = root; for (var i = 0; i < p.length; i++) o = o[p[i]]; return o; }
  function setAt(root, p, v) { getAt(root, p.slice(0, -1))[p[p.length - 1]] = v; }
  function pa(p) { return esc(JSON.stringify(p)); }
  function blank(v) {
    if (typeof v === 'string') return '';
    if (Array.isArray(v)) return [];
    if (v && typeof v === 'object') { var o = {}; Object.keys(v).forEach(function (k) { o[k] = blank(v[k]); }); return o; }
    return v;
  }
  function preview(o) {
    if (typeof o === 'string') return o;
    if (!o || typeof o !== 'object') return '';
    var keys = ['title', 'name', 'heading', 'label', 'text', 'question', 'id'];
    for (var i = 0; i < keys.length; i++) if (typeof o[keys[i]] === 'string' && o[keys[i]]) return o[keys[i]];
    for (var k in o) if (typeof o[k] === 'string' && o[k]) return o[k];
    return '';
  }
  function plain(s) { return String(s).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 60); }

  function node(v, p, label, depth, bar) {
    var key = JSON.stringify(p);
    if (typeof v === 'string') {
      var big = v.length > 90 || /[\n<]/.test(v);
      return '<div class="al-row"><label>' + esc(label) + (bar || '') + '</label>' +
        (big ? '<textarea rows="' + Math.min(14, Math.max(2, Math.ceil(v.length / 90))) + '" data-p="' + pa(p) + '" data-t="s">' + esc(v) + '</textarea>'
             : '<input type="text" data-p="' + pa(p) + '" data-t="s" value="' + esc(v) + '">') + '</div>';
    }
    if (typeof v === 'number') return '<div class="al-row"><label>' + esc(label) + (bar || '') + '</label><input type="text" data-p="' + pa(p) + '" data-t="n" value="' + esc(v) + '"></div>';
    if (typeof v === 'boolean') return '<div class="al-row"><label>' + esc(label) + (bar || '') + '</label><input type="checkbox" data-p="' + pa(p) + '" data-t="b"' + (v ? ' checked' : '') + '></div>';
    if (v === null) return '<div class="al-row"><label>' + esc(label) + ' (null — gõ để đặt giá trị chữ)' + (bar || '') + '</label><input type="text" data-p="' + pa(p) + '" data-t="z" value=""></div>';
    var open = L.open[key] !== undefined ? L.open[key] : depth < 1;
    var h;
    if (Array.isArray(v)) {
      h = '<details data-k="' + esc(key) + '"' + (open ? ' open' : '') + '><summary>' + esc(label) + (bar || '') + ' <span class="al-n">[' + v.length + ' mục]</span></summary>';
      v.forEach(function (it, i) {
        var pv = plain(preview(it));
        var ib = '<span class="al-itembar"><button type="button" class="al-mini" data-act="up" data-p="' + pa(p.concat(i)) + '">↑</button><button type="button" class="al-mini" data-act="down" data-p="' + pa(p.concat(i)) + '">↓</button><button type="button" class="al-mini al-danger" data-act="del" data-p="' + pa(p.concat(i)) + '">✕</button></span>';
        h += node(it, p.concat(i), '#' + (i + 1) + (pv && typeof it === 'object' ? ' — ' + pv : ''), depth + 1, ib);
      });
      h += '<button type="button" class="al-mini" data-act="add" data-p="' + pa(p) + '">＋ Thêm mục</button></details>';
      return h;
    }
    h = '<details data-k="' + esc(key) + '"' + (open ? ' open' : '') + '><summary>' + esc(label) + (bar || '') + '</summary>';
    Object.keys(v).forEach(function (k) { h += node(v[k], p.concat(k), k, depth + 1); });
    return h + '</details>';
  }
  function renderForm() {
    var box = $('#al-form'), top = box.scrollTop;
    if (L.mode === 'json') { box.innerHTML = '<textarea id="al-json" spellcheck="false"></textarea>'; $('#al-json').value = JSON.stringify(L.data, null, 2); $('#al-json').oninput = dirty; return; }
    var d = L.data, h = '';
    Object.keys(d).forEach(function (k) { h += node(d[k], [k], k, 0); });
    box.innerHTML = h; box.scrollTop = top; applyFilter();
  }
  function applyFilter() {
    if (!L || L.mode !== 'form') return;
    var f = String($('#al-find').value || '').toLowerCase().trim();
    var rows = $$('#al-form .al-row'), dets = $$('#al-form details');
    rows.forEach(function (r) {
      if (!f) { r.style.display = ''; return; }
      var inp = $('input,textarea', r), txt = (r.textContent + ' ' + (inp ? inp.value : '')).toLowerCase();
      r.style.display = txt.indexOf(f) >= 0 ? '' : 'none';
    });
    for (var i = dets.length - 1; i >= 0; i--) {
      var dd = dets[i];
      if (!f) { dd.style.display = ''; continue; }
      var has = !!dd.querySelector('.al-row:not([style*="none"])') || dd.querySelector(':scope > summary').textContent.toLowerCase().indexOf(f) >= 0;
      dd.style.display = has ? '' : 'none'; if (has) dd.open = true;
    }
  }
  function toggleMode() {
    if (!L) return;
    if (L.mode === 'form') { L.mode = 'json'; $('#al-mode').textContent = '☰ Biểu mẫu'; renderForm(); return; }
    try { L.data = JSON.parse($('#al-json').value); } catch (e) { return toast('JSON lỗi, chưa chuyển được: ' + e.message, 'err'); }
    L.mode = 'form'; $('#al-mode').textContent = '{ } JSON'; renderForm();
  }

  function onInput(e) {
    var t = e.target; if (!L || !t.dataset || !t.dataset.p) return;
    var p = JSON.parse(t.dataset.p), ty = t.dataset.t;
    if (ty === 's') setAt(L.data, p, t.value);
    else if (ty === 'n') setAt(L.data, p, (t.value.trim() !== '' && isFinite(t.value)) ? Number(t.value) : t.value);
    else if (ty === 'z') setAt(L.data, p, t.value === '' ? null : t.value);
    else return;
    dirty();
  }
  function onChange(e) {
    var t = e.target; if (!L || !t.dataset || t.dataset.t !== 'b') return;
    setAt(L.data, JSON.parse(t.dataset.p), t.checked); dirty();
  }
  function onClick(e) {
    var b = e.target.closest ? e.target.closest('[data-act]') : null; if (!L || !b) return;
    e.preventDefault();
    var act = b.dataset.act, p = JSON.parse(b.dataset.p);
    if (act === 'add') {
      var arr = getAt(L.data, p); arr.push(arr.length ? blank(arr[arr.length - 1]) : '');
    } else {
      var idx = p[p.length - 1], arr2 = getAt(L.data, p.slice(0, -1));
      if (act === 'del') { if (!confirm('Xóa mục này?')) return; arr2.splice(idx, 1); }
      else if (act === 'up' && idx > 0) { var a = arr2[idx]; arr2[idx] = arr2[idx - 1]; arr2[idx - 1] = a; }
      else if (act === 'down' && idx < arr2.length - 1) { var c = arr2[idx]; arr2[idx] = arr2[idx + 1]; arr2[idx + 1] = c; }
      else return;
    }
    dirty(); renderForm();
  }

  // ===== LƯU =====
  function stringify() {
    var out = L.indent ? JSON.stringify(L.data, null, L.indent) : JSON.stringify(L.data);
    return L.crlf ? out.replace(/\r?\n/g, '\r\n') : out;
  }
  function save(confirmShrink) {
    if (!L) return;
    if (L.mode === 'json') { try { L.data = JSON.parse($('#al-json').value); } catch (e) { return toast('JSON lỗi: ' + e.message, 'err'); } }
    if (!L.data || typeof L.data !== 'object' || !L.data.pageContent || typeof L.data.pageContent !== 'object') return toast('Thiếu "pageContent" — các trang đang dùng trường này', 'err');
    var btn = $('#al-save'); btn.disabled = true; status('Đang lưu lên Drive...');
    post({ action: 'lesson_save', kind: L.kind, lop: L.lop, fileId: L.fileId, baseUpdated: L.updated, text: stringify(), confirmShrink: confirmShrink === true })
      .then(function (j) {
        L.updated = j.updated; L.dirty = false;
        status('✓ Đã lưu ' + j.fileName + ' (' + j.length + ' ký tự). Bản cũ nằm trong _lesson_backup.');
        toast('Đã lưu vào Drive. Tải lại trang bài giảng để thấy bản mới.', 'ok');
      })
      .catch(function (e) {
        if (e.code === 'shrink' && confirm(e.message + '\n\nVẫn lưu?')) { btn.disabled = false; return save(true); }
        status(e.message, true);
        if (e.code === 'conflict') toast('File đã bị sửa ở nơi khác. Bấm Mở để tải lại bản mới nhất (thay đổi chưa lưu sẽ mất).', 'err');
        else if (e.code === 'unauthorized') toast('Phiên đăng nhập hết hạn — đóng cửa sổ này, mở lại và đăng nhập (đừng tải lại trang nếu chưa lưu).', 'err');
        else toast(e.message, 'err');
      })
      .then(function () { btn.disabled = false; });
  }

  refreshFab(); setInterval(refreshFab, 2000);
})();
