//
(function () {
  'use strict';
  if (window.top !== window.self) return;   // không chạy trong khung nhúng

  /* ---------- CẤU HÌNH (chỉnh ở đây) ---------- */
  var CFG = {
    REGISTER_URL: 'https://thayhungp.blogspot.com/p/ang-ki.html',
    PRESENCE_URL: 'https://script.google.com/macros/s/AKfycbzmgpdjkPR9S7sNR3ns-si--4ni0aFSO8jlvBDFEZi70rj_Cg51NdlhUJXbR9-R70RP/exec',
    FREE_SOLUTIONS_PER_DAY: 3,   // số lời giải khách được xem thử mỗi ngày (trang bài tập)
    FREE_LESSON_SOLUTIONS: 1,    // số bài giải đầu tiên khách xem được (trang bài giảng)
    COUNT_FORUM_LOGIN: true,     // người đã đăng nhập Diễn đàn tính là thành viên
    CACHE_MEMBER_H: 24,          // nhớ kết quả "đã đăng ký" (giờ), dùng chung rg_cache với khối nhắc đăng ký
    CACHE_GUEST_MIN: 10          // nhớ kết quả "chưa đăng ký" (phút)
  };

  // Tính năng chỉ dành cho thành viên. type: 'click' | 'submit'
  var LOCKED = [
    { sel: '#final-submit-btn',   type: 'click',  what: 'nộp bài' },
    { sel: '#modal-submit-btn',   type: 'click',  what: 'gửi bài' },
    { sel: '#student-info-form',  type: 'submit', what: 'gửi bài' },
    { sel: '#submit-comment',     type: 'click',  what: 'gửi bình luận' }
  ];

  /* ---------- TIỆN ÍCH ---------- */
  function ls(k) { try { return window.localStorage.getItem(k); } catch (e) { return null; } }
  function lsSet(k, v) { try { window.localStorage.setItem(k, v); } catch (e) {} }
  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function today() { var n = new Date(); return n.getFullYear() + '-' + (n.getMonth() + 1) + '-' + n.getDate(); }
  function cleanPhone(p) { return String(p || '').replace(/[\s.\-]/g, ''); }
  function validPhone(p) { return /^(\+?84|0)?\d{9,10}$/.test(p); }
  function getPhone() { var p = cleanPhone(ls('userPhone') || ls('user_phone')); return validPhone(p) ? p : ''; }

  /* ---------- TRẠNG THÁI: member | guest | unknown ---------- */
  // Chỉ tin nút bút chì của Blogger (cần đăng nhập đúng tài khoản chủ blog).
  // KHÔNG tin 'rg_admin' vì ai gõ tên "admin" vào form cũng đặt được cờ này.
  function bloggerAdmin() {
    try {
      var els = document.querySelectorAll('.item-control.blog-admin');
      for (var i = 0; i < els.length; i++) if (getComputedStyle(els[i]).display !== 'none') return true;
    } catch (e) {}
    return false;
  }
  function hasForumUser() {
    try { var u = JSON.parse(ls('physicsForumUser')); return !!(u && u.id != null); } catch (e) { return false; }
  }
  function checkPhone(phone) {
    var url = CFG.PRESENCE_URL + '?action=presence&phone=' + encodeURIComponent(phone) + '&page=' + encodeURIComponent(location.pathname);
    return fetch(url).then(function (r) { return r.json(); }).then(function (j) {
      var info = j && j.success && j.data;
      var reg = !!(info && info.registered);
      lsSet('rg_cache', JSON.stringify({ phone: phone, reg: reg, ts: Date.now() }));
      return { reg: reg, name: info && info.displayName };
    });
  }
  var state = 'pending';   // pending | member | guest | unknown
  function getStatus() {
    if (bloggerAdmin()) return Promise.resolve('member');
    if (CFG.COUNT_FORUM_LOGIN && hasForumUser()) return Promise.resolve('member');
    var phone = getPhone();
    if (!phone) return Promise.resolve('guest');
    var c = null;
    try { c = JSON.parse(ls('rg_cache') || 'null'); } catch (e) {}
    if (c && c.phone === phone) {
      var age = Date.now() - c.ts;
      if (c.reg && age < CFG.CACHE_MEMBER_H * 3600000) return Promise.resolve('member');
      if (!c.reg && age < CFG.CACHE_GUEST_MIN * 60000) return Promise.resolve('guest');
    }
    return checkPhone(phone).then(function (r) { return r.reg ? 'member' : 'guest'; })
      .catch(function () { return 'unknown'; });   // lỗi mạng: cho qua, không làm phiền nhầm
  }
  function refresh() {
    return getStatus().then(function (s) { state = s; applyLocks(); return s; });
  }
  function canUse() { return state === 'member' || state === 'unknown'; }

  /* ---------- HỘP MỜI ĐĂNG KÝ ---------- */
  var modal = null, pending = null, passing = false, lastFocus = null;
  function closeModal() {
    if (modal) { modal.remove(); modal = null; }
    document.removeEventListener('keydown', onKey, true);
    if (lastFocus && lastFocus.focus) try { lastFocus.focus(); } catch (e) {}
  }
  function onKey(e) { if (e.key === 'Escape') closeModal(); }

  function showModal(what, quotaText) {
    if (modal) return;
    lastFocus = document.activeElement;
    modal = document.createElement('div');
    modal.className = 'rgx-overlay';
    modal.innerHTML =
      '<div class="rgx-box" role="dialog" aria-modal="true" aria-labelledby="rgx-t">' +
      '<button class="rgx-x" type="button" aria-label="Đóng" data-rgx="close">&times;</button>' +
      '<h3 id="rgx-t">Đăng ký miễn phí để ' + esc(what) + '</h3>' +
      '<p>' + (quotaText || 'Bạn vẫn có thể đọc bài, xem video và làm thử bài luyện tập. Tính năng này dành cho thành viên để kết quả được ghi đúng tên bạn.') + '</p>' +
      '<ul><li>Nộp bài và lưu điểm, xu tích lũy</li><li>Xem đầy đủ lời giải chi tiết</li><li>Tham gia thảo luận</li></ul>' +
      '<div class="rgx-row">' +
      '<a class="rgx-btn rgx-primary" href="' + esc(CFG.REGISTER_URL) + '" target="_blank" rel="noopener">Đăng ký ngay</a>' +
      '<button class="rgx-btn rgx-ghost" type="button" data-rgx="close">Tiếp tục như khách</button></div>' +
      '<div class="rgx-sep"><b>Đã đăng ký rồi?</b> Nhập số điện thoại để xác nhận:' +
      '<input type="tel" id="rgx-phone" inputmode="tel" autocomplete="tel" placeholder="Số điện thoại đã đăng ký" value="' + esc(getPhone()) + '"/>' +
      '<div class="rgx-row" style="margin:0"><button class="rgx-btn rgx-primary" type="button" data-rgx="verify">Xác nhận</button></div>' +
      '<div class="rgx-msg" id="rgx-msg" role="status" aria-live="polite"></div></div></div>';
    document.body.appendChild(modal);
    document.addEventListener('keydown', onKey, true);
    var inp = modal.querySelector('#rgx-phone');
    if (inp) inp.focus();
  }

  function verifyFromModal() {
    var inp = document.getElementById('rgx-phone'), msg = document.getElementById('rgx-msg');
    if (!inp || !msg) return;
    var phone = cleanPhone(inp.value);
    msg.className = 'rgx-msg';
    if (!validPhone(phone)) { msg.textContent = 'Số điện thoại chưa đúng dạng.'; return; }
    msg.textContent = 'Đang kiểm tra...';
    checkPhone(phone).then(function (r) {
      if (!r.reg) { msg.textContent = 'Số này chưa có trong danh sách thành viên. Bạn hãy bấm "Đăng ký ngay".'; return; }
      lsSet('userPhone', phone); lsSet('user_phone', phone);
      if (r.name) lsSet('userDisplayName', r.name);
      try { window.dispatchEvent(new Event('storage')); } catch (e) {}
      state = 'member'; applyLocks();
      msg.className = 'rgx-msg ok'; msg.textContent = 'Xác nhận thành công!';
      var p = pending; pending = null;
      setTimeout(function () { closeModal(); if (p) replay(p); }, 500);
    }).catch(function () { msg.textContent = 'Không kết nối được máy chủ. Bạn thử lại sau nhé.'; });
  }

  document.addEventListener('click', function (e) {
    var t = e.target.closest ? e.target.closest('[data-rgx]') : null;
    if (!t || !modal || !modal.contains(t)) return;
    if (t.getAttribute('data-rgx') === 'close') closeModal();
    if (t.getAttribute('data-rgx') === 'verify') verifyFromModal();
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' && modal && e.target && e.target.id === 'rgx-phone') { e.preventDefault(); verifyFromModal(); }
  });

  function replay(p) {   // làm lại đúng thao tác khách đang dở
    passing = true;
    try {
      if (p.type === 'submit' && p.el.requestSubmit) p.el.requestSubmit();
      else p.el.click();
    } finally { passing = false; }
  }

  /* ---------- CHẶN TÍNH NĂNG CỐT LÕI ---------- */
  function intercept(e) {
    if (passing) return;
    var t = e.target;
    if (!t || !t.closest) return;
    for (var i = 0; i < LOCKED.length; i++) {
      var L = LOCKED[i];
      if (L.type !== e.type) continue;
      var el = e.type === 'submit' ? (t.matches(L.sel) ? t : null) : t.closest(L.sel);
      if (!el) continue;
      if (canUse()) return;
      e.preventDefault(); e.stopImmediatePropagation();
      if (state === 'pending') {            // chưa kiểm tra xong: kiểm tra rồi mới quyết định
        refresh().then(function () {
          if (canUse()) replay({ el: el, type: L.type }); else { pending = { el: el, type: L.type }; showModal(L.what); }
        });
      } else { pending = { el: el, type: L.type }; showModal(L.what); }
      return;
    }
    // Trang bài tập: khách xem thử vài lời giải mỗi ngày
    var tg = e.type === 'click' ? t.closest('.solution-toggle') : null;
    if (tg && !canUse()) {
      var id = tg.getAttribute('data-question-id') || (tg.getAttribute('data-problem-index') + '-' + tg.getAttribute('data-example-index'));
      var q = {};
      try { q = JSON.parse(ls('rgx_free_sol') || '{}'); } catch (x) {}
      if (q.day !== today()) q = { day: today(), ids: [] };
      if (q.ids.indexOf(id) > -1) return;
      if (q.ids.length < CFG.FREE_SOLUTIONS_PER_DAY) { q.ids.push(id); lsSet('rgx_free_sol', JSON.stringify(q)); return; }
      e.preventDefault(); e.stopImmediatePropagation();
      pending = null;
      showModal('xem thêm lời giải', 'Hôm nay bạn đã xem thử ' + CFG.FREE_SOLUTIONS_PER_DAY + ' lời giải. Đăng ký miễn phí để xem đầy đủ không giới hạn.');
    }
  }
  document.addEventListener('click', intercept, true);
  document.addEventListener('submit', intercept, true);

  /* ---------- LÀM MỜ LỜI GIẢI TRANG BÀI GIẢNG (từ bài thứ 2 trở đi) ---------- */
  function applyLocks() {
    var box = document.getElementById('lesson-solutions');
    if (!box) return;
    var items = box.querySelectorAll(':scope > .solution');
    var cta = box.querySelector('.rgx-cta');
    if (canUse() || items.length <= CFG.FREE_LESSON_SOLUTIONS) {
      Array.prototype.forEach.call(items, function (n) { n.classList.remove('rgx-locked'); });
      if (cta) cta.remove();
      return;
    }
    Array.prototype.forEach.call(items, function (n, i) {
      if (i >= CFG.FREE_LESSON_SOLUTIONS) n.classList.add('rgx-locked');
    });
    if (!cta) {
      cta = document.createElement('div');
      cta.className = 'rgx-cta';
      cta.innerHTML = '<span>Đăng ký miễn phí để xem đầy đủ lời giải chi tiết.</span>' +
        '<button type="button" class="rgx-btn rgx-primary" data-rgx-cta="1">Đăng ký / Xác nhận</button>';
      cta.querySelector('button').addEventListener('click', function () { pending = null; showModal('xem đầy đủ lời giải'); });
      var firstLocked = box.querySelector('.rgx-locked');
      if (firstLocked) box.insertBefore(cta, firstLocked);
    }
  }
  var t1;
  try {
    new MutationObserver(function () { clearTimeout(t1); t1 = setTimeout(applyLocks, 300); })
      .observe(document.body, { childList: true, subtree: true });
  } catch (e) {}

  refresh();
  document.addEventListener('physicsAppReady', function () { setTimeout(refresh, 600); });
  window.addEventListener('storage', function () { setTimeout(refresh, 800); });
})();
//
